/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"-0SiVi\":[\"兆米和千兆米出现在行星科学中。地球直径和轨道距离以原始米为单位是很尴尬的；带前缀的兆米或科学记数法使数字保持可读性。\"],\"-4BlXE\":[\"美国的木工仍然使用英尺和英寸，包括分数英寸。接受过公制培训的木工转换计划必须根据适合关键零件决定是软转换（最接近方便的毫米）还是硬转换（精确为每英寸 25.4 毫米）。\"],\"-66dxX\":[\"一平方码约等于 0.836 平方米。地毯、织物和景观美化经常以平方码为单位引用面积。\"],\"-6aMA_\":[\"一平方厘米 (cm²) 等于 10⁻⁴ 平方米。这是学校和实验室熟悉的小表面单位。\"],\"-7W-el\":[\"<0>广告数据：</0>在征得同意后启用广告时，Google AdSense和合作伙伴可能会处理 Cookie 和设备标识符以展示和衡量广告。\"],\"-B-lAA\":[\"What volume unit pairs with kilograms for SI density?\"],\"-BwTJr\":[\"Pick economy style (L/100 km or mpg). Convert distance and fuel volume into the units that formula needs. Convert highway pace with km/h ↔ mph when comparing trips across countries. Only then compute or convert the economy figure with the correct gallon definition.\"],\"-C9xP8\":[\"工作习惯面积：200 平方英尺至平方米。首先转换长度：1 ft = 0.3048 m，因此 1 ft² = 0.092 903 04 m²。那么 200 × 0.092 903 04 = 18.580 608 平方米。注意平方因子——跳过这一步将是灾难性的错误。\"],\"-Erj6j\":[\"实时结果\"],\"-EvUuc\":[\"是的。 Units Converters 可供学生、专业人士和日常任务免费使用。结果仅供参考——始终遵循安全关键工作的行业标准。\"],\"-J5iWY\":[\"立方英尺\"],\"-MPLZZ\":[\"即使地板按面积出售，衬垫、粘合剂和装饰有时也按长度出售。单独跟踪数量类型，这样您就不会像平方米一样对待线性米。\"],\"-PC2P3\":[\"一分升 (dL) 等于 100 毫升。一些国家的烹饪和营养标签使用分升。\"],\"-SGpOv\":[\"Because 14 lb make a stone, leftover pounds always run from 0 to 13 in normal speech. Saying “11.4 stone” casually might mean 11 st 4 lb to a listener—or 11.4 × 14 lb to a spreadsheet. Those disagree. Prefer “11 st 4 lb” in writing.\"],\"-TpHs4\":[\"有关转换杯子、升、汤匙和茶匙的实用厨房指南，以及在称重时击败体积以实现一致的烘焙。\"],\"-Udhzz\":[\"联系我们 | Units Converters\"],\"-ZAtn2\":[\"换算表\"],\"-a6gBA\":[\"化学品池容量：升和立方米\"],\"-cHB7E\":[\"Use feet to metres when US real-estate listings, lumber lengths, or flight levels described in feet must feed metric planning tools, EU building codes, or GPS apps set to metres. Survey notes and climbing guidebooks also flip between these. Divide feet by 3.28084, or multiply by 0.3048 exactly.\"],\"-f_6jA\":[\"Common mistakes\"],\"-iy9_F\":[\"Recipes use grams for most ingredients. Kilograms appear for large dough batches (1 kg flour). Milligrams appear in nutrition labels and caffeine or supplement contexts—1,000 mg = 1 g. Do not dose medicine from a kitchen scale unless the device and procedure are appropriate; this guide is about cooking units.\"],\"-jAHTX\":[\"正好 1 000 000 000 纳米 (10⁹ nm)。一纳米等于 10⁻⁹ 米。\"],\"-mdYJ1\":[\"仪器制造商开始标记固定点，例如融化的冰、沸水或人体温度。固定点的选择以及固定点之间的度数产生了相互竞争的尺度。在约定确定之前，甚至编号方向（一端为零）也发生了变化。\"],\"-n86uv\":[\"5K 是五公里（约 3.1 英里）。比赛名称中的 K 始终读作公里。\"],\"-oEWCf\":[\"A foot per second (ft/s) equals exactly 0.3048 metres per second. Engineering, ballistics, and some US technical contexts use feet per second.\"],\"-tbTIi\":[\"当图表列出每 10,000 升的剂量时，请将泳池容积转换为升，除以 10,000，然后乘以列出的剂量。在每个中间数旁边写下单位。\"],\"-uY40k\":[\"何时使用 \",[\"tFrom\"],\" 与 \",[\"tTo\"]],\"-uhfR3\":[\"一旦每个单元映射到一个基础，任何对都会分两步进行转换。这比存储每个单元与其他单元的巨大矩阵更易于维护，并且它可以保持因子一致。\"],\"-uxhlJ\":[\"户外公里和英里\"],\"-vpOo3\":[\"埃尔\"],\"-w9nPE\":[\"燃料、实验室和工业\"],\"-xcRjp\":[\"科学等级：\"],\"-y0hUl\":[\"Milligram\"],\"-yU7G4\":[\"我们可能会不时更新这些服务条款。发布更改后继续使用本网站即表示接受修订后的条款。我们鼓励您定期查看此页面。\"],\"-ztKvx\":[\"牛顿和其他历史尺度\"],\"00BfTm\":[\"有限元和 CFD 模型对于单位一致性是无情的。选择SI作为模型，转换输入，转换输出。混合单元套牌是传奇的失败模式。\"],\"01oAfy\":[\"平方米\"],\"02KbvL\":[\"An international mile per hour (mph) equals exactly 0.44704 metres per second. It is the everyday road-speed unit in the United States and United Kingdom.\"],\"03-4zJ\":[\"Units Converters 由位于巴西的Voyager Tecnologias LTDA 运营。对于隐私问题，请联系<0>voyagertecnologias@gmail.com</0>。\"],\"055uyK\":[\"A centimetre per second (cm/s) equals 0.01 metres per second. Laboratory flow rates and slow mechanical motions are often expressed in cm/s.\"],\"06TQZF\":[\"They run in opposite directions: higher mpg is better; lower L/100 km is better. Convert with proper factors before comparing a US mpg sticker to a metric L/100 km sticker.\"],\"0AIRPc\":[\"Confusing mg with µg (micrograms)—a 1,000× error that is dangerous for medication. Tablet strength in mg is not the same as dose if you take multiple tablets—convert the total mass you swallow. Do not assume mg of a vitamin equals mg of elemental nutrient without the salt form factor.\"],\"0ArAQV\":[\"使用明确的方法测量一次（当精度很重要时，可使用壁挂式测距仪）。转换为表格所需的单位。圆形仅用于显示。仔细检查英尺和英寸是否没有互换。\"],\"0B7LAd\":[\"大麦\"],\"0CAVbP\":[\"国际英寸正好是25.4毫米。国际英尺正好是 0.3048 m。一升正好是 0.001 立方米。在通常的实验室意义上，一立方厘米正好是 1 毫升（1 立方厘米 = 10⁻⁶ 立方米）。这些是定义，而不是测量。\"],\"0F9UuU\":[\"A gram (g) equals one thousandth of a kilogram. It is the familiar metric unit for kitchen scales, nutrition labels, and small packages.\"],\"0G_7_W\":[\"管道和木材的标称尺寸并不总是实际测量的尺寸。单位转换无法修复标称与实际不匹配的情况——测量您拥有的零件。\"],\"0KApmg\":[\"您无法使用厨房尺子验证 20 nm 特征。将仪器与规模相匹配：电子显微镜和纳米专业计量学；微米级光学显微镜；千分尺和毫米坐标测量机。转换不能升级仪器的分辨率。\"],\"0OJ9Po\":[[\"tQuantity\"],\" 转换\"],\"0TIAUP\":[\"Get volume units straight\"],\"0TOxMR\":[\"Scientific experiments often need milliseconds or microseconds. Convert 0.0025 s to milliseconds (2.5 ms) carefully: multiply seconds by 1,000 for milliseconds, by 1,000,000 for microseconds. Off-by-thousand errors are common when SI prefixes and sexagesimal time mix.\"],\"0UCLPw\":[\"了解为什么二进制浮点会产生奇怪的转换残差，当这些错误很重要时，以及十进制或有理算术如何保持单位转换器的可信度。\"],\"0Vwwul\":[\"Millisecond\"],\"0Ww9ut\":[\"No. A leap year is a calendar year with an extra day. A Julian year is a constant duration equal to the average length of a year in the old Julian leap pattern (365.25 days).\"],\"0dLIIp\":[\"How many seconds are in an hour?\"],\"0fJzsZ\":[\"Is 100 on the sign mph or km/h?\"],\"0hQ0Q4\":[\"公顷\"],\"0nEBio\":[\"Multiply knots by 1.852. Example: 100 kt = 185.2 km/h.\"],\"0usQ4p\":[\"UI 转换器通常通过四舍五入到固定的小数位数来隐藏问题。用户看到干净的结果而不会注意到内部噪音。当另一个系统使用原始浮点数时就会出现问题：CAD 内核、CSV 导出或比较全精度字符串的单元测试。\"],\"0y9e1o\":[\"A curtain drop of 84 inches is 7 feet exactly—standard floor-length drapery. A workbench at 36 inches high is 3 feet, matching many metric 900 mm benches within a few millimetres.\"],\"15Tpag\":[\"Multiply the min/km pace by 1.609344. Example: 5:00 /km ≈ 8:03 /mile. Or convert via km/h ↔ mph and back to pace.\"],\"1IEF32\":[\"哪些换算系数在纸面上是准确的\"],\"1Ip6j3\":[\"Use outer dimensions, including bulges and protruding handles. Soft packs are measured as the rectangular envelope they occupy. Convert all three sides into one length unit before multiplying. Mixing centimetres and inches in the same product is a classic quote killer.\"],\"1L66kB\":[\"了解单位转换背后的机制——基本单位、转换系数、尺寸分析，以及为什么链接转换会小心地保持答案准确。\"],\"1Qcw4d\":[\"Identify whether the source value is knots. Convert with 1.852 to km/h when talking to metric land audiences. Keep internal logs in knots if your charts are nautical. Dual-label passenger briefings (“8 knots, about 15 km/h”) when helpful.\"],\"1RF6BO\":[\"Economy depends strongly on driving speed. Converting km/h ↔ mph lets you compare trips or test conditions fairly before you compare L/100 km or mpg results.\"],\"1Rafvn\":[\"在选择米与英尺之前，先选择长度、面积与体积。许多“单位”问题都是变相的数量问题，尤其是在施工估算中。\"],\"1RaqL_\":[\"科学级单位\"],\"1SDUel\":[\"何时更看重重量而不是体积\"],\"1VRa7f\":[\"Units Converters 由 <0>Voyager Tecnologias LTDA</0> 开发和维护。我们是一个小团队，热衷于构建高质量的数字实用程序，以卓越的技术解决日常问题。\"],\"1WacFx\":[\"换算公式\"],\"1e_JkI\":[\"Digital tools often store seconds (or milliseconds) as the base and format displays as hh:mm:ss. When you convert, prefer going through seconds for multi-step work: hours → seconds → minutes, rather than chaining rounded intermediate displays.\"],\"1ilaSd\":[\"The kilogram (kg) is the SI base unit of mass. It is defined by fixing the Planck constant and is the reference for everyday weighing and science.\"],\"1tCIxd\":[\"Convert seconds to minutes for race results, microwave experiments, and API timeouts when logs show raw seconds. Divide seconds by 60. Sports broadcasting and backend SLAs both humanize seconds this way.\"],\"2-MYa-\":[\"Planck长度是一个基本物理常数，代表了关于空间和重力的经典观念崩溃的尺度。它的大小约为 1.6 × 10⁻³⁵ 米，用于理论物理。\"],\"208s5O\":[\"一旦代数自动化，在线转换器就成为一种速度工具而不是拐杖。您将在绘制或剂量之前发现倒置因素、错误的数量类型和温度偏移错误。即使您信任某个特定网站，这项技能也很重要，因为您仍然需要验证其数量模式和舍入行为。\"],\"218ZDU\":[\"硬转换使用精确的因子，然后根据保留容差意图的规定规则进行舍入。软转换在其他系统中选择一个方便的附近标称值。两者都是有效的策略——但它们是不同的策略。在修订块中写下您使用的是哪一个。\"],\"24A_yj\":[\"在某些地区，手机屏幕、笔记本电脑和桌面配件以英寸为单位销售，即使其他地区则以公制单位销售。将这些英寸视为营销惯例，如果您需要公制包或袖子中的间隙，请进行转换。\"],\"24rSD1\":[\"Multiplying by 1.6 (the linear mile factor) instead of ~2.59 is the standard mistake. Township grids and “sections” (1 sq mi) convert cleanly; irregular coastal counties still use the same factor on their reported area. Keep water vs land area labels intact after converting.\"],\"25a9CX\":[\"SI 通常最适合科学和国际工程，但本地规范、工具和受众可能需要习惯单位。当他们这样做时，仔细转换并记录权威系统。\"],\"27B7uY\":[\"值得信赖的土地转换工作流程\"],\"29C6iW\":[\"了解更多\",[\"tQuantity\"]],\"2Aplq9\":[\"Use the mile-per-hour ↔ kilometre-per-hour converter for exact values when a work zone lists an unusual number. Anchors are for glance checks; exact math is for planning and disputes.\"],\"2VWuzt\":[\"通过我们的指南学习\"],\"2aQdBR\":[\"A 4×6 inch photo is 24 in², about 155 cm² of print area. A 1 in² ventilation hole is 6.45 cm² for metric airflow notes.\"],\"2cR6Dq\":[\"1 公顷 = 10 000 平方米。 1 平方公里 = 100 公顷 = 1 000 000 平方米。 1 英亩 ≈ 0.404 686 公顷。 1 英亩 ≈ 4 047 平方米（更准确地说是 4 046.856 422 4 平方米）。根据与调查/国际英尺讨论相关的美国习惯土地测量中的定义，1 英亩 = 43 560 平方英尺。记住公顷和英亩到平方米的对；需要时导出其余部分。\"],\"2fKQ-1\":[\"提示：开尔文在 SI 书写中从不使用度数符号（K，而不是 °K）。 1 K 的变化相当于 1 °C 的变化。对于烘焙，首先转换配方，然后针对风扇烤箱进行调整。\"],\"2mpp6P\":[\"Units Converters is a free educational utility operated by \",[\"0\"],\". Please read these limitations before relying on any result.\"],\"2nr-Ad\":[\"杯子\"],\"2op5th\":[\"面积、体积和衍生量\"],\"2wazXz\":[\"单一基数使每个单元定义保持一致并减少存储因子的数量。当你信任直接因素时，它们就很好；基本单元路径是软件和检查手工计算的可靠模式。\"],\"2xIadB\":[\"<0>您发送的反馈：</0> 姓名、电子邮件和消息（如果您使用我们的联系方式或反馈表）。\"],\"2yEcJZ\":[\"快速、准确且易于使用的长度、温度、面积和体积单位转换器。科学精确，舍入误差为零。\"],\"3-O-U2\":[\"Rhode Island’s land area near 1,034 sq mi is about 2,678 km². A 10 sq mi flood zone is roughly 25.9 km² for metric emergency maps.\"],\"30hVC9\":[\"当实验室协议显示 250 nm 而卡尺读数为毫米时，十的幂思维可以防止恐慌。首先转换为米：250 nm = 2.5 × 10⁻⁷ m = 0.000 25 mm——远低于卡尺分辨率。转换正确；仪器选择错误。\"],\"324qxJ\":[\"No. You need both distance (mile↔km) and volume (gallon↔litre) factors, and you must know whether the gallon is US or imperial.\"],\"32nfzA\":[\"Dimensional weight formulas in practice\"],\"350ym0\":[\"From sketch to order form\"],\"35GwnE\":[\"精密单位转换器：公制、英制和科学\"],\"3CoO29\":[\"分升\"],\"3E5zLe\":[\"Nautical miles and knots travel together. If you convert speed to km/h, convert distance to kilometres too before dividing for time.\"],\"3E7v2_\":[\"家里的毫米和厘米\"],\"3Fv6-r\":[\"三种刻度，两种零\"],\"3N9RRw\":[\"跨境通信量\"],\"3NPiUv\":[\"汤匙在国际上也有所不同。许多公制勺子的容量为 15 毫升；一些传统的澳大利亚汤匙是 20 毫升。当配方很重要时，最好选择称重的成分或毫升的量度。\"],\"3P9P3g\":[\"A stone equals 14 avoirdupois pounds, or exactly 6.35029318 kilograms. Body weight in the United Kingdom is still often quoted in stones and pounds.\"],\"3PqcjI\":[\"在国外租车时，请注意行车电脑显示的是公里还是英里。在旅途中用错误的心理单位重置平均值会产生无意义的成本估算。\"],\"3R4dl3\":[\"Is 1.30 hours the same as 1 hour 30 minutes?\"],\"3SMznx\":[\"使用Units Converters，即表示您确认您已阅读、理解并同意受这些服务条款和我们的隐私政策的约束。如果您不同意，请不要使用该网站。\"],\"3SRSvY\":[\"日常生活中的长度单位：从毫米到英里\"],\"3UzgKd\":[\"For durations over 24 hours, decide whether to display total hours (36 h) or days plus hours (1 d 12 h). Converting total seconds into either presentation is fine—just label the result so readers know which form you chose.\"],\"3ZVFSt\":[\"天气和烹饪主导摄氏温度和华氏温度的使用。舒适的室温约为 20–22 °C (68–72 °F)。体温约为 37 °C (98.6 °F)。烤箱食谱可能会同时列出两者；请务必确认转换后的烤箱设置是否与您的设备标记相符。\"],\"3aowmP\":[\"Grams are usually clearer for small ingredients and metric recipes. Ounces are fine if the whole recipe and your scale stay in ounces. Pick one system per bake.\"],\"3bUZ78\":[\"化学图表和安全性\"],\"3coptQ\":[\"通过中间步骤保持完全精度。给观众一轮：烹饪博客可能会显示小数点后一位；机械车间可能需要三个。在多步计算中提前舍入会产生原始测量中不存在的误差。\"],\"3eng2d\":[\"Dimensional (volumetric) weight is a billing weight derived from package dimensions using a carrier divisor. You typically pay on the higher of actual scale weight and dimensional weight.\"],\"3gBC8W\":[\"有效数字应反映测量能力和功能需求。转换卷尺尺寸后列出八位小数会假装您没有精度。检查员应该被告知哪些数字是有效的，哪些是转换显示的假象。\"],\"3k5XM4\":[\"我们的转换器专为准确性和速度而设计。与其他可能存在较小舍入误差的工具不同，我们使用专门的库来确保每个小数点都是正确的。这对于科学计算、工程任务或任何精度至关重要的情况尤其重要。\"],\"3kl9_I\":[\"Writing 1.5 kg as 1.5 g on a scale that reads grams underdoses by 1,000×. Shipping dimensional weight in kg is unrelated to converting product mass to grams—keep those workflows separate. Jewelry grams are mass; carats are different.\"],\"3lxmj2\":[\"我们的公里 ↔ 英里转换器页面包含常见道路距离的表格，因此您可以快速翻译行程注释。\"],\"3mhTKi\":[\"远足地图可能使用以米为单位的等高线间隔，而越野地图则使用英里。 GPS 设备设置应与地图和团体语言相匹配，以减少集合错误。\"],\"3pCUdM\":[\"全球可访问性：\"],\"3r4LPB\":[\"微米 (μm) 涵盖了电池和许多制造公差。纳米 (nm) 涵盖可见光波长和纳米颗粒尺寸。 ångström (Å) 等于 0.1 nm 或 10⁻10 m，在晶体学和化学中的键长中仍然很常见。\"],\"3r5jgz\":[\"SI 纯粹主义者更喜欢纳米或皮米，许多期刊都接受其中之一。协作时，就表格的单位达成一致，并在补充数据中保持一致的转换。审阅者注意到图 1 使用 nm 而表 2 使用 Å 时没有转换说明。\"],\"3tIoob\":[\"10 m/s is about 22.4 mph—a stiff cycling headwind. Terminal-velocity ballpark 50 m/s is roughly 112 mph before posture and drag details.\"],\"3u-0-0\":[\"提示：将工程图端到端保存在一个系统（公制或英制）中。仅在项目边界处进行转换以避免公差叠加。当团队跨越国家时，双标签高度和道路距离。\"],\"3u90fF\":[\"A height of 175 cm is 5.74 feet, usually spoken as 5 ft 9 in. A 240 cm curtain fabric cut is 7.87 feet—order 8 feet of material if the shop sells by the foot.\"],\"3vXqnf\":[\"一国际英里正好等于 1.609344 公里。粗略估计，8 公里 ≈ 5 英里。\"],\"3vk9Xp\":[\"Minutes to seconds: multiply by 60. Hours to seconds: multiply by 3,600. Days to hours: multiply by 24. Reverse with division. For mixed inputs like 2 h 15 min 40 s, convert each part to seconds, add, then convert to the target unit once.\"],\"3z_7Nd\":[\"Use yards to metres when US fabric, turf, or concrete “by the yard” quotes must match metric project plans. Quilters and civil estimators working with mixed suppliers rely on this. One international yard is exactly 0.9144 m.\"],\"47xD74\":[\"Alternatively, convert pace to a speed in km/h, convert speed to mph, then convert mph back to min/mile. Use whichever chain produces fewer rounding steps for you.\"],\"49XKfg\":[\"A flight that leaves at 17:00 and lands at 19:00 local at the destination may last 8–12 hours depending on zones. Always trust block time (a duration) from the airline for “how long you sit,” and local times for “when to be at the gate.”\"],\"4FE7_g\":[\"为什么我的蛋糕在正确转换后仍然烧焦？\"],\"4HE7vS\":[\"Clinic forms may ask for kilograms while your bathroom scale shows pounds, or the reverse. Convert the reading you actually measured; do not “feel” a number in the other unit. A 2–3 lb morning fluctuation is normal; a unit mix-up of 2.2× is a medical-record disaster.\"],\"4JISh_\":[\"飞米\"],\"4O0cEB\":[\"How many pounds are in one kilogram?\"],\"4OnBIV\":[\"贸易技能中的英寸、英尺和码\"],\"4Qgkrl\":[\"Dual-label key sessions: “5:30 /km (8:51 /mile) ≈ 10.9 km/h (6.8 mph).” The first time takes a minute; the clarity lasts a season.\"],\"4S_eXT\":[\"Convert litres to cubic feet when metric cooler, tank, or heater capacities must match US appliance and HVAC catalog language. Divide litres by about 28.3168. Importers localizing EU product sheets use this pair.\"],\"4SxPEz\":[\"Using ÷1.6 is fine for rough driving; for calibration use the exact factor. Wind forecasts in km/h vs mph change perceived severity—convert before comparing to Beaufort mental models. Do not convert pace min/km with a pure speed formula without inverting correctly.\"],\"4WS4sV\":[\"光日\"],\"4WT--N\":[\"面积测量表面积：长度的平方。体积衡量空间：长度的立方。如果没有厚度或深度等附加信息，平方米 (m²) 无法转换为升（体积）。如果一个工具提供了这种转换，那么它要么是错误的，要么是默默地假设了一个高度。\"],\"4XMbOB\":[\"这两个系统都不是更正确的。一米的路和一码的布料都可以测量长度。改变的是扩展、国际交流和保持算术简单的容易程度。工程师、科学家和世界上大多数人都默认使用公制。某些地区的建筑业、航空业、美国的烹饪业以及较旧的法律文件仍然严重依赖英制或美国的习惯单位。\"],\"4ZCZap\":[\"一公里 (km) 等于 1,000 米。它是道路距离、地图和体育比赛的标准公制单位。\"],\"4Z_hj5\":[[\"tFrom\"],\" 至 \",[\"label\"]],\"4_SW3I\":[\"一平方毫米 (mm²) 等于 10⁻⁶ 平方米。工程图纸和小部件横截面通常使用它。\"],\"4bbTla\":[\"Convert pounds to kilograms or grams before combining with metric volumes. 1 lb ≈ 453.592 g. Kitchen scales that show ounces need the same care: convert oz → g, then apply density.\"],\"4bnTBN\":[\"在<0>长度</0>、<1>温度</1>、<2>面积</2>和<3>体积</3>之间快速转换。无论您是学生、工程师还是业余爱好者，我们的工具都能提供从日常测量到高级科学数据的高精度结果。\"],\"4dfhhk\":[\"立方英里\"],\"4eyt5-\":[\"假设您需要将<0>\",[\"exampleInput\"],\"</0>\",[\"tFrom\"],\"转换为\",[\"tTo\"],\"。使用与上述计算器相同的基本单元电桥，<1>\",[\"exampleInput\"],\"</1>\",[\"0\"],\"等于<2>\",[\"exampleOutput\"],\"</2>\",[\"1\"],\"。\"],\"4htqm_\":[\"Disclaimer | Units Converters\"],\"4izzev\":[\"日常流畅意味着无需计算器即可了解大致尺寸：信用卡长约 85 毫米；门口高约2m；城市街区各不相同，但通常只有几百米； 5K 跑是 5 公里。\"],\"4jhles\":[\"正好一万平方米。一公顷是每边 100 米的正方形。\"],\"4oZ5j_\":[\"我可以仅从长度单位转换池体积吗？\"],\"4qZFYZ\":[\"板英尺\"],\"4qu2HU\":[\"In everyday speech, a year is what calendars do: birthdays, fiscal periods, and school terms follow Gregorian rules with leap days. In astronomy and many scientific constants, a Julian year is a fixed duration of exactly 365.25 days, each day 86,400 seconds—exactly 31,557,600 seconds.\"],\"4wUv2L\":[\"我们的 \",[\"tQuantity\"],\" 转换器如何工作\"],\"4yOpty\":[\"Interval workouts that mix “400 m repeats” with “mph recovery jogs” need both length and speed converters. Write every line with units before you lace up.\"],\"4yUaO4\":[\"A 100 m dash is about 109.4 yards. Ordering 3 m of upholstery fabric means about 3.28 yards; round up if the bolt is sold in whole yards only.\"],\"5-L30Y\":[\"简短的决策秘诀\"],\"528nU7\":[\"Proxima Centauri at about 4.25 ly is roughly 4.02×10¹³ km away. Saying that out loud shows why probes take decades even at high speed: kilometres make the gap concrete.\"],\"56W9Uj\":[\"A “5:00 min/km” pace is 12 km/h. A “8:00 min/mile” pace is 7.5 mph. Those are different efforts—convert carefully before you race your training partners’ screenshots.\"],\"58dnGV\":[\"Payroll and aviation sometimes use decimal hours (1.5 h). Sports and media use 1:30. To convert decimal hours to minutes, multiply the fractional part by 60. To convert hh:mm to decimal hours, divide minutes by 60. Never read the minutes field as a decimal fraction.\"],\"59sdtS\":[\"一纳米 (nm) 等于十亿分之一米 (10⁻⁹ m)。它是光、纳米技术和薄膜波长的日常单位。\"],\"5A1BRJ\":[\"从 CAD 或 GIS 工具导出的 CSV 有时会丢失单位元数据。在转换之前重新连接单元，并检查大小：500 平方米的房屋面积可能是平方米； 500 000 英亩的土地可能不是英亩。\"],\"5ABbuU\":[\"Assuming every “cup” is 250 mL when the recipe is US customary (240 mL) shifts sugar and flour enough to change texture. Scooping flour by volume is already imprecise—conversion cannot fix packing density. Liquid cups and dry cups are the same volume unit; weight still differs by ingredient.\"],\"5CuV4Q\":[\"面积测量表面积：房间以平方米或平方英尺为单位，土地以公顷和英亩为单位。选择下面的起始单位，然后转换为任何其他面积单位，无需舍入漂移。\"],\"5Fh9kd\":[\"US bathroom scales and forms almost never use stone. If you move between the UK and US, you will translate between stone↔lb and stone↔kg often. Freight and science do not use stone—keep it in the body-weight and informal UK context.\"],\"5Hk-XC\":[\"我们如何使用信息\"],\"5JPpQY\":[\"The metre per second (m/s) is the SI derived unit of speed. Physics and engineering treat it as the base unit for velocity and speed conversions.\"],\"5MU6OU\":[\"如果孩子要旅行或阅读国际媒体，请教他们这两种系统。双重读写能力是一种实用的生活技能，而不是一种政治声明。厨房温度计、道路地图集和来自另一个国家的缝纫图案足以练习转换，而无需单独使用工作表。\"],\"5P4d2U\":[\"请联系 Voyager Tecnologias LTDA 咨询 Units Converters。发送反馈或通过电子邮件联系我们：voyagertecnologias@gmail.com。\"],\"5PxpgF\":[\"Oven roast at 180 °C is 356 °F (often rounded to 350 °F on US dials). A mild 22 °C room is about 72 °F—typical comfort wording in US building guides.\"],\"5Rjv-n\":[\"地块面积可以是英亩；建筑面积可以是平方米或平方英尺。他们测量不同的多边形。如果转换单位但混合了错误的多边形，则容积率计算会失败。\"],\"5_adq5\":[\"An hour equals 3,600 seconds, or 60 minutes. Civil timekeeping, labour, and travel durations are usually expressed in hours.\"],\"5eZ6SO\":[\"当用 ± 公差转换标称值时，转换限值（上限和下限），然后重新表述标称值和公差，或者使用一致的舍入规则转换标称值和公差，以免无意中缩小允许区域。\"],\"5gLOyE\":[\"服务条款 | Units Converters\"],\"5i4RiS\":[\"A candy thermometer reading of 300 °F is about 149 °C for soft-crack stage in metric candy charts. Weather at 68 °F is 20 °C—handy when packing for a city that posts only Celsius.\"],\"5jFarL\":[\"我们的目标是仅收集运行和改进网站所需的内容：\"],\"5mk-lJ\":[\"在国际市场上，土地和房产的使用面积并排使用公顷和英亩。一公顷等于 10 000 平方米；根据国际定义，一英亩为 4 046.856 422 4 m²。房地产列表有时会激进地进行四舍五入——验证调查平台，而不是营销手册。\"],\"5o6fJj\":[\"温度选择取决于您是否需要绝对热力学温度（开尔文）或面向人类的天气和烹饪尺度（摄氏度或华氏度）。\"],\"5odHYG\":[\"Sliding three decimal places the wrong way turns 500 g into 500 kg. Nutrition labels in grams per serving still need portion count before totaling kilograms for bulk prep. Do not confuse g with mg on medicine labels.\"],\"5qFrDO\":[\"半导体工艺节点历史上使用纳米品牌；谨慎解释营销节点与物理门长度。尽管如此，纳米仍然是小型电子特征的语言家园。关于纳米颗粒的材料论文同样默认直径为 nm，表面积为 m²/g，不要混合这些数量类型。\"],\"6-lWKx\":[\"一米比一码长吗？\"],\"61CiXo\":[\"Convert grams to milligrams when a lab balance reading in grams must match pharmaceutical or supplement labels in mg. Multiply grams by 1,000. Compounding and nutrition science use this constantly.\"],\"6A1R02\":[\"For exports, customs may care about net and gross mass in kilograms even when your commercial invoice was drafted in pounds. Keep both actual mass and package cube documented so logistics and compliance teams share one truth.\"],\"6AiOIQ\":[\"我应该如何比较测试中的转换器结果？\"],\"6Al-Ue\":[\"After you trust net area. Add 5–15% (more for patterns), then convert to the seller’s unit if needed and round up to packaging.\"],\"6B5JWe\":[\"摄氏度和摄氏度\"],\"6DLZ9r\":[\"当您的源数据、标准或仪器已报告该单位时，请选择 <0>\",[\"tFrom\"],\"</0>。当与需要不同 \",[\"tQuantity\"],\" 约定的团队、工具或文档协作时，请切换到 <1>\",[\"tTo\"],\"</1>。\"],\"6PMmOj\":[\"说明单位的不确定性。将 1.540 0 Å 转换为纳米应保留有效数字：如果精度是真实的，则为 0.154 00 nm。\"],\"6PosYV\":[\"工程图纸应当声明转换政策。混合方法的全球团队生产出几乎适合的零件，这比明显不适合的零件更糟糕。几乎合适的零件会浪费检查时间并削弱供应商之间的信任。\"],\"6RddZQ\":[\"A knot is one international nautical mile per hour, equal to 1852/3600 metres per second. Aviation and maritime navigation report speed in knots.\"],\"6TrT9O\":[\"英国食谱有时会使用英制品脱和公制重量——这种混合在当地有意义，但却让进口商感到困惑。对于便携式版本，将液体转换为毫升，将干货转换为克。\"],\"6U7zRe\":[\"US customary tablespoons are 14.8 mL and Australian tablespoons are 20 mL—do not assume every tbsp is metric 15 mL. Heaping vs level spoons dominate error more than unit math. Do not convert spoon volumes to grams without the ingredient density.\"],\"6UYTy8\":[\"Minute\"],\"6VHY1j\":[\"5K 比赛是五公里还是五英里？\"],\"6VO62n\":[\"一立方公里 (km³) 等于十亿立方米。地质学和海洋学将其用于巨大的自然体积。\"],\"6XgEPi\":[\"Hour\"],\"6bBy6I\":[\"公制与英制：您应该使用哪种系统？\"],\"6clLDQ\":[\"A 12 oz steak is about 340 g—handy for metric doneness charts per centimetre thickness. First-class mail at 3.5 oz is about 99 g.\"],\"6dN923\":[\"Converting knots cleanly\"],\"6g7YAo\":[\"许多商店只验证一个单位的范围。使用错误的系数进行转换，或者在一个字段中将英尺/英寸与厘米混合，会触发这些检查。\"],\"6h3o07\":[\"脚（国际）\"],\"6hTphd\":[\"Convert avoirdupois pounds to kilograms for passport medical forms, EU shipping labels, and metric gym programs when the starting number is in pounds. Multiply lb by 0.45359237 exactly. Couriers and coaches use this daily.\"],\"6ho4DE\":[\"烘烤温度：摄氏度和华氏度\"],\"6j5rE1\":[[\"name\"]],\"6jG3Ph\":[\"Convert square centimetres to square inches for US packaging die-lines, bandage sizes, and small panel cutouts when the CAD file is metric. Divide cm² by 6.4516. Print finishers and medical device labeling use this often.\"],\"6m-c2x\":[\"Real-world example\"],\"6y0UdC\":[\"记住一些与你的身体和家庭息息相关的锚点：你的身高（厘米和英尺/英寸）；您的门宽度；本地赛道 100 m；在熟悉的道路上行驶一英里。锚点胜过抽象表格以进行快速估计。\"],\"7-1d79\":[\"如果软件将 25.4 存储为二进制浮点数，则在任何转换运行之前可能已经出现轻微错误。乘以另一个不精确的因子会加剧误差。即使算法在概念上是正确的，断言严格相等的往返测试也会失败。\"],\"7-A57D\":[\"Programming libraries distinguish Instant/ZonedDateTime from Duration/Period. Convert seconds with duration tools; convert zones with zone databases (IANA). Do not roll your own offset table from memory.\"],\"71wsvF\":[\"杯子的一致性甚至更差。美国习惯杯、美国营养标签法定杯和公制杯（通常为 250 毫升）都出现在食谱中。始终确定来源采用的杯子。当博客省略该细节时，请谨慎转换或找到同一食谱的加权版本。\"],\"7C1JIS\":[\"<0>同意偏好：</0>您是否接受或拒绝存储在您的浏览器（localStorage）中的非必要cookie。\"],\"7C3Rik\":[\"天文单位\"],\"7CoI9M\":[\"Contact us at <0>\",[\"0\"],\"</0> if you spot an error or need clarification about how a conversion is defined.\"],\"7D3Du8\":[\"CAD 双重尺寸标注应从主要单位导出次要单位，而不是交替使用相反的单位。基层单位拥有设计权。次要价值观是沟通的辅助工具，而不是第二个真理来源。\"],\"7DaEzk\":[\"Shipping cares about mass and dimensional volume separately for billing. Density explains why pillows bill on volume and steel bills on mass, but the carrier formula still wins for price.\"],\"7Fd9fc\":[\"有关公制和英制单位、温标、SI前缀、烹饪换算和精密测量的深入指南。\"],\"7Fpl88\":[\"Common mix-ups with land units\"],\"7FyB9w\":[\"Worked conversion patterns\"],\"7GXDvT\":[\"一毫米 (mm) 等于 0.001 米。它是小物体、工程图纸和降雨量的常用日常公制单位。\"],\"7IA3Mr\":[\"Freight and courier services may use kilograms worldwide even when the shipper thinks in pounds. Dimensional weight is a separate rule (volume-based billing). Convert actual scale weight correctly first; then apply the carrier’s dimensional-weight formula in the unit the carrier specifies.\"],\"7IvdVj\":[\"Ordering from room perimeter instead of area. Perimeter helps trim length; it does not equal carpet area.\"],\"7JKA3u\":[\"现场清单\"],\"7Krvzl\":[\"Mixing troy ounces (precious metals) with avoirdupois ounces (food and freight). This site’s everyday ounce unit is avoirdupois. Gold and silver use a different ounce—do not convert jewellery the same way you convert flour.\"],\"7LsmlS\":[\"对于矩形：长×宽×平均深度。将所有三个长度保持在同一单位，计算立方长度（立方米或立方英尺），然后如果您的化学图表需要升，则转换为升。\"],\"7QsmKa\":[\"如果您转换存档的法律描述，请记下测量机构使用的纪元和英尺定义。 GIS 专业人员关心这一点；后院园丁通常不这样做。\"],\"7Qx5-T\":[\"Portioning meal prep: convert the weekly protein target to grams, divide into containers, and ignore ounces until you publish a US-facing blog post.\"],\"7SXyp_\":[\"The console was likely in mph while you expected km/h (or the reverse). Check the unit label before you trust the number.\"],\"7SkS_Y\":[\"快速心算：将公顷乘以 2.47 来估算英亩；将英亩乘以 0.4 来估算公顷。然后用精确的转换器进行精炼以进行法律工作。现场估算可以使用粗略的因素；合同和地籍更新不应该。\"],\"7TK6ys\":[\"Work shifts logged as “7.5 hours” are durations. Convert to minutes (450) for payroll systems that want minutes. Time-zone entry only matters for when the shift started, not for how long 7.5 hours is.\"],\"7U0oLh\":[\"艾萨克·牛顿根据自由冷却材料和其他参考文献对温标进行了实验。牛顿标度出现在一些转换器中，作为一种历史奇观，在接近冰点时为零，在沸腾时具有较小的度数。\"],\"7UFvIc\":[\"双精度足以进行单位转换吗？\"],\"7VxoBS\":[\"当您必须比较、制造、剂量或跨系统导航时进行转换。如果当地建筑规范、速度限制或包装标签已与您的工具匹配，请在该系统中工作并仅在接口（进口、出口和发布的规格）处进行转换。\"],\"7_ePmj\":[\"Use density = mass / volume with consistent weight and volume units, convert kilograms, grams, litres, and cubic metres, and avoid cup-vs-gram mistakes.\"],\"7_lrbG\":[\"约塔梅特雷\"],\"7edIF8\":[\"避免在同一段落中混合 nm 和 Å 而不进行转换。专家可以切换；混杂的观众迷失了方向。当幻灯片从微米级的细胞宽度跳跃到纳米级的膜厚度且尺度之间没有语言桥梁时，同样的建议也适用。\"],\"7fyhDy\":[\"Two meanings of “year”\"],\"7h4xrB\":[\"Multiply mph by 1.609344 for an exact value. For a mental estimate, multiply by 1.6. Example: 70 mph ≈ 112.7 km/h.\"],\"7nkrrp\":[\"Track races may publish times to 0.01 s while road races use whole seconds. Converting a 3:45 marathon split into decimal minutes for pace math is useful; inventing hundredths the watch never measured is not. Preserve the precision you actually recorded.\"],\"7o1zK6\":[\"我们包括用于高级科学研究的罕见且精确的单位，例如 Planck 长度、玻尔半径和 Ångström。\"],\"7r_Iz_\":[\"Using 4,000 m² per acre is a rough cut that drifts ~1.2%. Acre-feet measure water volume, not area—do not drop the “feet” and convert as pure acres. City lots listed in fractions of an acre need full decimal acres before multiplying.\"],\"7tI8CF\":[\"保留您实际使用的前缀的少量参考。您不需要记住 yocto 和 yotta 来进行建筑工作；你确实需要毫冷、微冷和公斤冷。如果你阅读材料或电子论文，请添加 nano；如果您使用行星或数据中心物理工厂规模，请添加兆级和千兆级。\"],\"7tkhyb\":[\"酿造和饮料行业历来依赖于当地定义的桶和加仑。现代质量体系越来越标准化升，同时保留传统的营销名称。尽可能将营销单位视为标签，将生产单位视为升。\"],\"8-CHL5\":[\"提示：不要将地板平方米与油漆升数混淆——面积和体积是不同的数量类型。\"],\"81pHBk\":[\"Convert litres to cubic metres for water tanks, aquarium sums, and HVAC airflow-adjacent liquid volumes when SI building models want m³. One cubic metre is exactly 1,000 L. Civil and aquarium hobby math share this pair.\"],\"82_S3f\":[\"Dividing by 2.0 overstates m/s. Posted ramp speeds in mph become unsafe inputs if left unconverted in a metric model. Treadmill mph to m/s uses the same factor as vehicle speed.\"],\"82hkkt\":[\"测量链（冈特链）等于 66 英尺，或约 20.117 米。它是英语国家土地测量的基础。\"],\"82v0CX\":[\"简单、快速、科学级精度。在几秒钟内将任何东西从纳米转换为光年。\"],\"87ZOlX\":[\"A 18 ft³ refrigerator is about 510 L—compare to European fridge labels in litres. A 2 ft³ minifridge is roughly 56.6 L of internal volume.\"],\"8AULTO\":[\"它是如何运作的\"],\"8BQeht\":[\"Example: 2.5 Julian years = 2.5 × 365.25 = 913.125 days. Example: 10,000 days ÷ 365.25 ≈ 27.378 Julian years. Keep enough decimals when the result feeds another scientific formula.\"],\"8HXvHC\":[\"SI 通过现代计量学中的基本常数定义了开尔文，完成了从冰浴到量子标准的旅程。出于直觉，日常用户仍然会转换为摄氏度。实验室笔记本仍应记录传感器固件发出的量程——此处的假设会导致多度偏差。\"],\"8IehbN\":[\"在线分享食谱时，请包括两个秤。您的国际读者不必猜测您指的是哪种“气痕”文化。\"],\"8Jd9P3\":[\"公司：\"],\"8P_FxZ\":[\"Compute area in square metres, then multiply by about 10.7639—or use an area converter. Do not convert only one wall length to feet.\"],\"8QF2qf\":[\"Convert feet per second to mph when a US lab, wind-tunnel, or projectile chronograph reads ft/s but you want road-speed intuition. Divide ft/s by 1.46667, or use mph = ft/s × 15/22. Safety briefings often want mph.\"],\"8Qpa7Q\":[\"硬件加速和 GPU 管道通常会强制浮动。在这些情况下，请在 CPU 或服务器上保留十进制的权威转换，并将 GPU 浮点视为显示或中间近似值。\"],\"8S1T6W\":[\"150 seconds of rest is 2.5 minutes between sets. A 3,600-second timeout is 60 minutes—one hour for a long job.\"],\"8TLHSU\":[\"When teaching mixed audiences, give knots first (ops truth) and a converted gloss second (public truth).\"],\"8U1Wou\":[\"土地面积与水量\"],\"8WkbAX\":[\"As a duration unit in simple converters, 1 day = 24 hours. Civil clock days can be 23 or 25 hours across daylight-saving transitions.\"],\"8c995T\":[\"是的。绝对零为 0 K，等于 -273.15 °C。普通的热力学系统没有达到低于该值的温度。\"],\"8eHaYx\":[\"Measuring real rooms\"],\"8euFNe\":[\"浏览全部指南\"],\"8fs_RU\":[\"Convert metres to feet for room dimensions, athletic track splits, and building heights when the source is metric but the audience thinks in feet. Architects reviewing SI drawings for a US client and runners comparing race distances use this pair often. One metre is about 3.28084 international feet.\"],\"8g-qDy\":[\"提示：将工程图端到端保存在一个系统（公制或英制）中。仅在项目边界处进行转换以避免公差叠加。\"],\"8iPd_0\":[\"该服务按<0>\\\\“按原样”</0> 和<1>\\\\“可用”</1> 提供，不提供任何形式的明示或暗示的保证，包括但不限于准确性、完整性、适销性或针对特定用途的适用性。\"],\"8jHem_\":[\"种子和施肥量将面积单位与质量混合：千克/公顷与磅/英亩。分别转换面积和质量，然后合并。维度分析可防止比率倒挂。\"],\"8lvaZJ\":[\"Why bakers prefer weight\"],\"8nJn60\":[\"Convert miles to kilometres when US highway distances, flight route charts in statute miles, or bike computer settings must match metric signage and European navigation. Couriers quoting door-to-door miles for overseas clients need the km figure. Multiply miles by 1.609344.\"],\"8vdUGj\":[\"Dividing by 3,600 incorrectly as 3,000. Displaying only whole hours hides useful fractional hours for short jobs. Stopwatch sports times in seconds convert cleanly; including countdown pauses is a measurement issue.\"],\"8zKQrL\":[\"团队\"],\"9-uAp_\":[\"Pediatric and athletic charts may use kilograms internationally. Convert once from a measured scale reading. Re-weigh rather than eternally converting an old stone value after training cycles.\"],\"94_ABr\":[\"10 st ≈ 63.5 kg ≈ 140 lb; 11 st ≈ 69.9 kg ≈ 154 lb; 12 st ≈ 76.2 kg ≈ 168 lb; 14 st ≈ 88.9 kg ≈ 196 lb. Anchors help conversation; exact converters help forms.\"],\"957mDG\":[\"Julian calendar dates (the historical calendar Julius Caesar introduced) are yet another topic. “Julian year” as a 365.25-day unit should not be confused with Julian calendar day numbering or Julian Day Count (JD), though the shared adjective confuses newcomers.\"],\"959Vfh\":[\"摄氏度这个词在历史上描述了一百级的等级。如今，摄氏度已成为科学交流中的首选名称，与开尔文正式联系在一起。\"],\"96dZEM\":[\"Practical workflow\"],\"9AIeUi\":[\"Get mass units straight\"],\"9B12Hm\":[\"News articles sometimes convert knots to mph incorrectly by using 1.6 (the statute mile factor) instead of about 1.15. When accuracy matters, re-convert from the original knot value.\"],\"9BCuew\":[\"Tare the scale (subtract pallet or container weight) when the rate applies to net shipment weight. For multi-piece shipments, know whether the carrier sums chargeable weights per piece or allows shipment-level aggregation—those rules change optimization tactics.\"],\"9Bp5Rv\":[\"其他因素经过测量或历史四舍五入。较旧的测量英尺、当地土地测量值或实验常数可能带有不确定性。当一个因子是近似值时，转换后的结果会继承这种不确定性——如实报告重要数字。\"],\"9DO-KV\":[\"建立个人转化锚\"],\"9E6g4y\":[\"APIs should store instants in UTC or with explicit offsets, and store durations in seconds. Display layers apply zones. Mixing display strings into arithmetic is the bug.\"],\"9F1FDN\":[\"它们来自加仑的不同历史定义。美国液体加仑定义为 231 立方英寸（约 3.785 升）。英国历史上使用的英制加仑较大（约 4.546 L）。务必检查配方、燃油经济性数据或化学品安全表所假定的加仑数。\"],\"9FEF2i\":[\"立方码\"],\"9Fk_m2\":[\"此处，公制滴落量标准化为 50 微升。药房和实验室说明有时会通过滴剂来计量液体。\"],\"9INfx0\":[\"遵循期刊和您所在领域的规范。晶体学通常仍然使用埃格斯特伦（ångströms）；纳米科学的大部分内容更喜欢纳米。手稿的一致性最为重要。\"],\"9K1siw\":[\"英制（国际）\"],\"9KfN-m\":[\"A 20-knot wind is 37 km/h—near a strong breeze on land-based km/h apps. A ship cruising at 15 kn makes about 27.8 km/h over water.\"],\"9MpX2H\":[\"第三方广告\"],\"9OMJOQ\":[\"How many days are in a Julian year?\"],\"9OP0of\":[\"Example bridge: speed (km/h) = 60 ÷ pace (min/km). Pace (min/km) = 60 ÷ speed (km/h). For miles: speed (mph) = 60 ÷ pace (min/mile). Always track whether the pace distance is a kilometre or a mile.\"],\"9Qs99X\":[\"电子邮件：\"],\"9R2Q_O\":[\"Area first, then conversion\"],\"9Ru4GA\":[\"平方纳米\"],\"9T3uW6\":[\"CNPJ:\"],\"9Z89rA\":[\"距离单位显示在燃油经济性中（L/100 公里 vs 英里/加仑）。仅换算旅行长度并不能换算经济数据——经济数据需要有自己的公式。\"],\"9aBORt\":[\"面积和体积需要平方和立方前缀\"],\"9aKMyD\":[\"Mental anchors\"],\"9brUFH\":[\"Convert days to hours for shipping ETAs, antibiotic courses, and server uptime when plans use days but operations think in hours. Multiply days by 24 for civil mean days. Logistics and on-call rotations rely on this.\"],\"9cgJA5\":[\"这个网站如何改进？\"],\"9fW-dh\":[\"If a log says a job finished at 01:10 after starting at 23:50, the duration is 80 minutes (or 1 h 20 min), including the midnight crossing. Convert that duration with time units; do not subtract the clock faces as decimal numbers without handling day rollover.\"],\"9hxz2e\":[\"持久的长度示例\"],\"9iWFRw\":[\"圆形英制\"],\"9j9_c5\":[\"对于混合团体，请在共享行程中发布公里和英里。双总数阻止“还能走多远？”车里的争吵。\"],\"9l599X\":[\"我应该在论文中使用埃姆还是纳米？\"],\"9mFi34\":[\"Using 2 or 4 feet per yard is a quick mental error. Square yards and cubic yards are not converted by multiplying by 3—that factor is only for linear yards. Keep partial yards (2.5 yd = 7.5 ft) as decimals.\"],\"9mS3qf\":[\"未找到类别 | Units Converters\"],\"9pJyPJ\":[\"天文单位 (AU) 大致相当于地球与太阳的距离，约为 1.496 × 10^1 米。行星轨道和航天器轨迹经常使用 AU。一光年约为 63 241 个天文单位。\"],\"9utJAy\":[\"工作习惯：将 12 英尺转换为米。准确使用 1 英尺（国际）= 0.3048 m。 12 × 0.3048 = 3.6576 m。对于显示，您可以根据公差写入 3.658 m 或 3.66 m。\"],\"9wG3f-\":[\"Packaging choices that change chargeable weight\"],\"9wW_0V\":[\"Nutrition labels and package net weights\"],\"A2Nh9c\":[\"了解 Units Converters 如何收集和使用数据，包括 Cookie、PostHog 分析和 Google AdSense 广告。\"],\"A3LmyE\":[\"Convert seconds to hours for uptime reports, render-farm jobs, and endurance sports when logs show seconds but humans want hours. Divide seconds by 3,600. Cloud billing dashboards often store seconds underneath.\"],\"A5neWO\":[\"相关换算器\"],\"ADsjhY\":[\"烹饪后果\"],\"AGI27x\":[\"适合学生和专业人士的高精度单位转换。立即转换数百个单位。\"],\"AHRDPK\":[\"温标描述了物体的热度或冷度。摄氏温度和华氏温度主导着日常生活；开尔文是SI科学标度。使用精确的公式在它们之间进行转换，而不是浮点快捷方式。\"],\"AIqsCx\":[\"Convert acres to square metres when a US land deed in acres must feed metric civil engineering, drainage calculations, or EU-style planning apps. One acre is exactly 4,046.8564224 m². Surveyors and solar designers use this for panel layout density.\"],\"ALn0nW\":[\"为什么温度转换不同？\"],\"AO7lxi\":[\"立方微米\"],\"AP4oUf\":[\"平方英里\"],\"ASs9cS\":[\"Exactly 60 seconds make a minute; 60 minutes make an hour; 24 hours make a day in ordinary civil usage. Those ratios are exact for conversion between these units. Mistakes come from treating decimal hours like sexagesimal minutes—writing 1.30 h when you mean 1 h 30 min (which is 1.5 h).\"],\"AWwdQz\":[\"Age, birthdays, and why they diverge\"],\"AXEawP\":[\"Microgram\"],\"AXhspr\":[\"欧洲产品数据表以平方米为单位；许多北美床单使用 ft²。如果安装人员和供应商不同意，请保留包含两栏的单个项目表。\"],\"AXoYRC\":[\"Tonne (Metric)\"],\"AZvQdm\":[\"每次转换都会经过精心定义的 \",[\"tQuantity\"],\" 基本单位。我们使用任意精度的十进制算术，因此科学工作、家庭作业和专业估计的结果保持稳定。\"],\"A_E97M\":[\"ERP 系统中的自动转换器需要对货币相关数量和规定尺寸进行十进制算术。二进制浮点剩余物显示为植物之间不匹配的哈希值。\"],\"A_Yltl\":[\"由于在日常使用中 1 Å = 10⁻10 m，因此换算后是 10 的干净幂，非常适合十进制算术，而且与常规单位因子相比，更不容易出现奇异的浮点戏剧。仍然标记每一列；干净的数学并不能成为模棱两可的标题的借口。\"],\"Ab1IcB\":[\"在线分享您自己的食谱时，请在杯子旁边发布毫升和克。每个国家的未来读者都会感谢您，并且您将减少真正属于单元问题的支持问题。\"],\"Aex9bg\":[\"大约 9.46 万亿公里（9.46 × 10^2 公里），具体取决于所使用的确切年份定义。为了进行精确的工作，请使用转换器记录的常数通过仪表进行转换。\"],\"Af82OU\":[\"Using 2.2 lb/kg is fine for luggage estimates but drifts on commercial invoices. Do not confuse avoirdupois pounds with troy pounds used for precious metals. Force in pounds-force vs mass in pounds is a physics trap—this conversion is mass to mass.\"],\"Afd4_y\":[\"Converting km to miles then forgetting to square the factor (use ÷2.59, not ÷1.61) understates area badly. Lakes and admin boundaries may use different shoreline rules—unit conversion does not fix definition differences. Do not mix nautical miles into land area.\"],\"AmmtnH\":[\"冲击、氯和酸性产品可以使用不同的图表约定。将体积一次转换为您可以为每个产品重复使用的“家庭单位”。\"],\"ApnX7Q\":[\"Convert grams to kilograms for shopping, lab reagents, and postage when fine scales use grams but tariffs and recipes batch in kilograms. Divide grams by 1,000. Food service and compounding pharmacies jump this scale often.\"],\"AqwQEc\":[[\"0\"],\" | Units Converters 指南\"],\"B0NIBw\":[\"阅读较旧的英国材料时，除非另有说明，否则假设为英制加仑。阅读美国材料时，除非指定公制杯子，否则假定采用美国液体测量。\"],\"B3phg2\":[\"大众科学青睐光年，因为旅行时间的比喻很直观。研究论文通常倾向于秒差距。它们之间的转换是通过米进行常规长度转换。\"],\"B6ZO29\":[\"温度转换是仿射（比例加偏移），而不是简单的乘法。这就是“除以二”民间传说失败的原因。使用适当的转换器或精确的公式。\"],\"B6_cWQ\":[\"简单的烘焙工作流程\"],\"BB3hek\":[\"Race finish time ≈ pace × distance when units match. Convert a marathon distance to kilometres or miles to match your pace unit before multiplying. A marathon is 42.195 km or 26.21875 miles—not 42 miles.\"],\"BQPexS\":[\"Human age in years is a civil concept tied to calendar dates, not a pure second count divided by 31,557,600. Leap days, time zones, and local midnight rules affect birthday boundaries. Do not convert a person’s age with Julian years unless you are doing a physics-style duration exercise and say so.\"],\"BR8_kT\":[\"A 3 m³ water delivery is 3,000 L—about sixty 50 L barrels. An aquarium billed as 0.36 m³ is a 360 L tank in hobby shop language.\"],\"BRAW5m\":[\"仪表板和 UI 转换器应默认为区域设置敏感的单位，但允许覆盖。记住用户偏好，而不违反法律标签要求。记录的分析事件应存储规范单位，以便偏好更改不会破坏历史聚合。\"],\"BTiJ7H\":[\"厨房的核心体积关系\"],\"BVxiN6\":[\"对于海洋和航空而言，将海里分开——它们与法定英里不同。\"],\"BXmAOD\":[\"生物学和机械加工中的微米\"],\"BcL8Ac\":[\"Do I need a time zone to convert hours to minutes?\"],\"BiFdAo\":[\"开尔文温度和绝对温度\"],\"BmfykU\":[\"指南\"],\"BmsDT1\":[\"A 23 kg airline allowance is about 50.7 lb—just over a common 50 lb US checked-bag limit. A 100 kg barbell is roughly 220.5 lb on a US plate math board.\"],\"BnJzQv\":[\"了解 Units Converters、我们对科学精度的承诺以及零舍入误差转换工具背后的技术。\"],\"Bproz9\":[\"Learn how carriers bill the higher of actual weight and dimensional (volume) weight, convert kilograms and pounds correctly, and measure boxes so quotes match invoices.\"],\"BpyhsK\":[\"km/h, mph, and m/s in reports\"],\"BqL2-s\":[\"美国以外的大多数医疗和 ID 系统都以厘米为单位存储高度（例如 175 厘米）。米 (1.75 m) 在科学文本中更清晰，但在需要整数厘米的表格中却很尴尬。\"],\"Br0a7Q\":[\"A half-acre suburban lot is about 2,023 m². A 10-acre solar field offers roughly 40,469 m² of land before setbacks and roads.\"],\"Bsnqds\":[\"提示：开尔文在 SI 书写中从不使用度数符号（K，而不是 °K）。 1 K 的变化相当于 1 °C 的变化。\"],\"Bum03c\":[\"Logging “job took 2:30” without saying h:mm vs hh:mm:ss recreates decimal-hour bugs. ISO-8601 durations (PT2H30M) fix the ambiguity.\"],\"BxXGvi\":[\"一分米 (dm) 等于 0.1 米或 10 厘米。它出现在公制教育和一些工业规范中。\"],\"C-H7bp\":[\"责任限制\"],\"C3r5wf\":[\"一米等于 1 000 毫米、1 000 000 微米或 1 000 000 000 纳米。从nm爬升到m就是爬十的九次方。这一跨度涵盖了 DNA 宽度、细菌、人类毛发、昆虫和人体尺度的物体——这也是科学传播如此依赖尺度阶梯的原因。\"],\"C420Ed\":[\"付诸实践\"],\"C4gpAv\":[\"当结果看起来令人惊讶时，请询问您是否转换了单位或意外转换了数量。这个问题就可以拯救项目。第二个快速检查是几何的：这个数字是否意味着深度、厚度或从未说明过的覆盖率？缺少几何形状通常意味着有人将面积视为体积。\"],\"C7uWe7\":[\"本隐私政策解释了当您使用 Units Converters 时，Voyager Tecnologias LTDA（“我们”）如何收集、使用和共享信息。\"],\"C7uhe0\":[\"Ounces and pounds in US recipes\"],\"C87HOb\":[\"公制和SI一样吗？\"],\"CAPENq\":[\"不会。与 °C 和 °F 不同，现代风格写的是 300 K，没有度数符号。单位是开尔文。\"],\"CHp68X\":[\"Label every log line: distance unit, volume unit, economy style. Dual-display dashboards are fine; dual-meaning spreadsheets are not.\"],\"CKIz2Y\":[\"永不失败的转换模式\"],\"CKM_It\":[\"一国际英亩约等于 4,047 平方米。它仍然是美国和英国的主要陆地面积单位。\"],\"CKyk7Q\":[\"返回\"],\"CPaJqI\":[\"Airspeeds and ATIS winds are typically in knots. One knot = 1.852 km/h = about 1.15078 mph. When a POH lists V-speeds in knots, convert for a passenger explanation if you want—but memorize and fly the knot values you trained with.\"],\"CU9R4b\":[\"We calculate conversions with arbitrary-precision decimal arithmetic (Decimal.js) and published unit definitions. Results are intended for learning, everyday planning, and general technical reference.\"],\"CWPZJa\":[\"英亩英尺\"],\"CZpj_s\":[\"Using “2.5 acres per hectare” is close but high by about 1%. Confusing hectares with square kilometres (100 ha = 1 km²) blows land deals by two orders of magnitude. Pasture stocking rates change with area unit—convert area before applying head-per-acre rules.\"],\"CbTonE\":[\"极端单位教导尺度堆叠：从Planck长度到可观测宇宙跨越了几十个数量级。前缀米和科学计数法是桥梁。实验室墙上的一页刻度梯（nm、μm、mm、m）比另一张前缀琐事幻灯片可以防止更多错误。\"],\"CdAYjA\":[\"如果你始终如一的话，这两种方法都有效。大多数人以一个单位计算面积，添加废物，然后转换为供应商的包装单位。\"],\"CdD4XN\":[\"精密加工和计量可能会以微米（或商店行话中的微米）为单位指定公差。确认绘图的微米是否意味着微米——在现代实践中几乎总是肯定的。当图纸将微米公差与英寸公差混合在一起时，请在向客户报价之前将一个系统转换为权威系统。\"],\"CeG8fO\":[\"If you convert metres to feet on only one side of a rectangle before multiplying, the area is wrong. If you convert both sides to feet and multiply, you get square feet directly. If you multiply in metres, convert with an area converter. Pick one path and stay on it.\"],\"CgfJlz\":[\"<0>使用数据：</0>查看的页面、根据 IP 得出的​​大致位置、设备/浏览器类型以及推荐信息 — 通常在您同意后通过分析工具获得。\"],\"CjGnuz\":[\"Checklist before you buy a label\"],\"CjTgKQ\":[\"Car drivers often think in mph or km/h and underestimate boat/aircraft speeds quoted in knots because the numbers look “smaller.” Fifteen knots is not a jogging pace—it is about 28 km/h over ground if SOG matches.\"],\"CngmkZ\":[\"建立对从纳米到米的长度的直觉——十的幂、日常类比以及跨 SI 前缀的干净转换习惯。\"],\"CnvyXZ\":[\"为什么摄氏度与开尔文大小相同？\"],\"CpMczN\":[\"要将英里每小时转换为米每秒，请分别转换长度和时间，然后合并。写出因子的完整乘积，以便取消每个不需要的单元。一旦你知道了复合尺寸，同样的方法就可以扩展到密度、压力和能量。\"],\"CqR5NF\":[\"电子表格有时将温度存储为标题中没有单位的数字。然后下游脚本应用错误的公式。始终用刻度标记列，包括度数符号或字母 K。\"],\"CrLxAB\":[\"Dividing by 365 only ignores the average leap day. Using 365.2425 (Gregorian) is better for civil history, not for Julian-year based constants. Do not convert “trading days” with 365.25.\"],\"CrsICs\":[\"平方米和平方公里是SI友好的面积单位。全球土地测量均采用公顷（1 公顷 = 10 000 平方米）。英亩在美国土地话题中占主导地位，并出现在许多英语财产记录中。国际投资者通常需要将这三项内容整合到一份情况说明书中。\"],\"CuqvVE\":[\"徒步旅行和跑步活动\"],\"CuujzZ\":[\"Convert kilometres to miles for road trips, race results, and fuel economy discussions when maps or cars show km but drivers think in miles. Tourism, logistics, and running (5K, 10K) all cross this boundary. One international mile is exactly 1.609344 km.\"],\"Cvs5DP\":[\"Example directionality: about 8 L/100 km is roughly 29–30 US mpg (order of magnitude check). Always recompute with exact factors for claims or regulations.\"],\"D16asK\":[\"主要的\"],\"D1yKic\":[\"Layover math: if landing is at one local time and departure at another, convert both to UTC (or another single offset), subtract to get a duration in seconds or minutes, then format. Do not convert time zones by “adding duration units” blindly.\"],\"D2P6Qz\":[\"A detector cooled to 77 K is about −321 °F—colder than dry ice (−109 °F). Human skin temperature ~306 K is about 91 °F, matching infrared thermometer expectations.\"],\"D6nVvu\":[\"公司详情\"],\"D73kiV\":[\"为什么我的地板报价与计算器不同？\"],\"D8Thx0\":[\"Cubic feet appear in US tanks and fridges. Convert ft³ → m³ or litres before using a metric density table.\"],\"D8cLPv\":[\"Confusing hectolitres with hectolitres of pure alcohol (a tax statistic) versus beer volume. Using ×1,000 (as if converting kL) overshoots. Decalitres (10 L) are another step—do not mix daL and hL labels on farm tanks.\"],\"DB6GbG\":[\"Switch inches to feet when a tape reading in inches is longer than a foot and you need architectural or lumber language (room height, joist spacing, fabric cuts). Carpenters often measure in inches then report in feet and leftover inches. Twelve international inches make exactly one foot.\"],\"DB7w-2\":[\"飞米 (fm)，也称为费米，等于 10⁻15 米。核物理学家用它来测量原子核和核子的大小。\"],\"DCLceB\":[\"长度测量距离——从材料科学中的纳米到天文学中的光年。该中心收集日常和科学长度单位，因此您可以打开任何对进行公式、表格和高精度转换。\"],\"DGCK_s\":[\"Not professional advice\"],\"DHuMm6\":[\"Convert hectolitres to litres for brewery output, wine harvest tanks, and agricultural liquid fertilizer when industry quotes hL but cellar or field gear is labeled in L. Multiply hL by 100. European beer statistics are often in hectolitres.\"],\"DLKAlh\":[\"Convert hours to seconds for computation timeouts, video timecode budgets, and physics problems that need SI seconds from a human hour count. Multiply hours by 3,600. Software and lab DAQ systems prefer seconds.\"],\"DPKPR5\":[\"60 mph is exactly 88 ft/s—the classic driving-physics mnemonic. A baseball at 90 mph is 132 ft/s toward the plate.\"],\"DPodsc\":[\"一阿米 (am) 等于 10⁻18 米。当描述与原子核大小相当的距离时，它很有用。\"],\"DQIUZW\":[\"Using “3 feet per metre” undershoots by nearly 10%. Ceiling heights listed as 2.4 m are about 7.87 ft, not 8 ft—important for ladder and furniture clearance. Do not mix statute miles (for long distance) into short metre-to-foot room math.\"],\"DSQp0D\":[\"Is 23 kg the same as 50 lb for airline bags?\"],\"DSdsOn\":[\"No. One hour is always 60 minutes as a duration. Time zones only change clock labels for moments in time.\"],\"DU39ti\":[\"350°F 是多少摄氏度？\"],\"DVjsxz\":[\"Rounding rules matter as much as the divisor. Some carriers round each dimension up to the next centimetre; others round the final chargeable weight up to the next half kilogram. Convert units first, then apply rounding in the order the tariff states.\"],\"DWgR4U\":[\"我们使用Google AdSense来显示广告。 Google 及其合作伙伴可能会根据您之前访问本网站或其他网站的情况，使用 Cookie 或类似技术来投放广告，但须遵守您的同意选择。您可以在<0>Google 广告政策</0>了解更多信息，并在<1>Google 广告设置</1>管理广告个性化。\"],\"DY9sZd\":[\"了解这些尺度的存在有助于阅读较旧的论文，但对于新的工作，更喜欢使用摄氏度来表示交流，使用开尔文来表示绝对热力学量。\"],\"DYR0BH\":[\"我应该对每次测量进行双重标记吗？\"],\"DZkjcm\":[\"小数库（例如，decimal.js、Big.js 或语言本机小数）以 10 为基数存储数字。精确的小数因数（例如 0.3048 和 0.001）在所选精度范围内保持精确。关心正确性的单位转换器通常通过十进制基本单位进行转换。\"],\"DZsWq3\":[\"什么是光年？距离，而不是时间\"],\"DbDx5L\":[\"一国际英里正好是 1.609344 公里。对于旅行计划来说，这个因素就足够了。您很少需要比十分之一公里或英里更高的精度。\"],\"DbFygU\":[\"Exact relationship: 1 mph = 1.609344 km/h because the international mile is exactly 1.609344 km and the hour is the same in both units. Conversely, 1 km/h ≈ 0.621371192 mph. For dashboard glances, many drivers remember “multiply mph by 1.6” or “multiply km/h by 0.62,” then refine when planning.\"],\"Dc6r_W\":[\"测量脚和历史警告\"],\"Dd4MGI\":[\"支持电子邮件：<0>\",[\"supportEmail\"],\"</0>\"],\"Dd8R82\":[\"我们可能会不时更新本隐私政策。当我们这样做时，顶部的“最后更新”日期将会改变。更改后继续使用该网站即表示您接受更新后的政策。\"],\"DdkR-D\":[\"描述您的问题，我们会尽快回复您。\"],\"DeHj7V\":[\"海拔增益也是一种长度——通常以米或英尺为单位。与水平距离分开转换增益；它们是计划中的不同列。\"],\"DeyDo0\":[\"国际转账\"],\"Dg4jBX\":[\"摄氏征服了国际天气预报、美国以外的烹饪以及大多数工程教育。它与开尔文度大小一致，使得科学转换变得整洁。\"],\"DkfdV1\":[\"是的。一米约为 1.094 码，或约 3.281 英尺。一米比一码稍长。\"],\"DpUgLQ\":[\"用于转换任何配方的可靠工作流程\"],\"DqGaXj\":[\"将单元与任务相匹配\"],\"DsvDLu\":[\"A metric tonne (t) equals 1,000 kilograms. Industry, shipping, and agriculture use tonnes for bulk cargo and large loads.\"],\"Dt2lOd\":[\"尺度直觉是科学教育、微加工和生物学领域的一项专业技能。转换器给出数字；类比给出判断。拥有一组共同地标的团队可以更少地浪费时间来争论结果是否合理。\"],\"DxvqBO\":[\"©\",[\"0\"],\"Units Converters。版权所有。\"],\"Dz_BPx\":[\"华氏度的实用刻度\"],\"E30KJo\":[\"Treating 1/8″ as “3 mm” (true value ≈ 3.175 mm) stacks error across a part with many holes. Fractional inches must become decimals before multiplying. Do not confuse thousandths of an inch (mil) with millimetres—1 mil is 0.0254 mm, not 1 mm.\"],\"E9jbKj\":[\"一百升 (hL) 等于 100 升。酿造、葡萄酒生产和谷物贸易历来都青睐百升。\"],\"EAX9Yw\":[\"No. Fluid ounces measure volume; scale ounces measure mass. Convert volume and mass separately, using density if you must bridge them.\"],\"ECCEhO\":[\"一立方码约等于 0.765 立方米。美国的建筑和景观美化按立方码购买混凝土、土壤和覆盖物。\"],\"ED605G\":[\"实用的财产和农业例子\"],\"EFwY8C\":[\"在转换工程常用单位时，首选精确的 SI 因子。更喜欢贸易和土地的书面法律定义。仅在满足这些约束后才倾向于在某个领域举行社区会议。\"],\"EHFvuN\":[\"软件默认值会影响一切。 CAD 模板、传感器固件和 CSV 导出器默默地选择单位并对其进行审核。项目开始时十五分钟的默认审查可以防止随后数周的法医单位考古工作。\"],\"EHclsu\":[\"秒差距更大——大约 3.26 光年。专业天文学通常更喜欢秒差距；外展通常更喜欢光年。\"],\"EIl6-2\":[\"Our Julian year ↔ day converter pages exist specifically to keep that definition visible—use them when reconciling catalogue values or teaching why a light-year is a length.\"],\"ENpdhX\":[\"Units Converters | Fast & Precise Unit Conversion Tool\"],\"EPtcRf\":[\"<0>温度：</0>摄氏度、华氏度、开尔文度和牛顿度。\"],\"EUgW7r\":[\"经典的 0.1 + 0.2 问题遇到单位\"],\"EV9SSM\":[\"孩子们\"],\"EWZu3-\":[\"GPX 工具有时会在内部默认使用仪表。导出设置可以静默切换显示单位；在共享路线之前验证汇总总数。\"],\"EYzeDq\":[\"一立方英寻大约等于 6.12 立方米。历史上的海运货物和疏浚环境使用立方英寻。\"],\"EcmlKU\":[\"生物学和化学总是以微升和纳摩尔浓度进行讨论。精密零件的机械图纸可能会标注微米公差。电子产品从微米特征尺寸迁移到纳米节点——前缀是行业词汇的一部分。\"],\"EghcSN\":[\"选择语言\"],\"EgpmZP\":[\"Multiplying by 100 or 10,000 from digit-counting slips. Concrete “cubic metres” are solid volume; do not assume the same number of litres of mix water without the recipe. Gas metres in m³ are not liquid litres without density and state conditions.\"],\"EiLAfk\":[\"摄氏度换算华氏度：°F = °C × 9/5 + 32。华氏度换算摄氏度：°C = (°F − 32) × 5/9。将偏移量和 9/5 因子一起记住——丢掉任何一个步骤都是常见的课堂错误。\"],\"Ek008v\":[\"当您需要国际协作、科学报告或简单扩展时，请选择指标。当您的本地规范、工具和供应商已经存在时，请选择英制或美国习惯，并记录选择。如果两个值均来自一个主单元，则二维图纸可以在车间提供帮助。\"],\"EnxBSk\":[\"Jet streams and ATIS winds are typically in knots. Airport visibility and runway lengths may use metres or feet—different quantities. Do not treat a wind of 15 kt like 15 km/h; that underestimates wind by nearly half.\"],\"EpuR3A\":[\"A 12 m yacht length overall is about 39.4 feet for marina berth booking in the US. A 3 m sofa wall needs roughly 9.8 feet of clear space—buyers often round up to 10 feet when shopping.\"],\"EqUGWT\":[\"因为每一步都是十的因数，心算很简单：2.4 km 是 2 400 m； 75 厘米是 0.75 m。电子表格和 CAD 工具可以干净地处理公制，国际标准（ISO、IEC、大多数科学期刊）期望使用 SI 单位或明确定义的公制导数。\"],\"Eqve2s\":[\"Sports science may log m/s. Multiply by 3.6 for km/h, then convert to pace with 60 / (km/h). Example: 3.33 m/s ≈ 12 km/h ≈ 5:00 min/km.\"],\"EtsosN\":[\"首先转换打印的配方温度，然后应用风扇调节。不要混合步骤，否则您将重复更正。\"],\"EuXeB_\":[\"不。它是距离的度量：光在一年内传播多远。时间比喻有助于直觉，但单位本身就是长度。\"],\"EwoQqu\":[\"Use our kilogram ↔ pound tools for the mass side and cubic metre ↔ litre tools when you reason about cube. Then apply the carrier formula—converters handle units; tariffs handle money.\"],\"EwtKsD\":[\"Units Converters 上的所有内容、品牌、布局和软件（不包括第三方材料）均归 Voyager Tecnologias LTDA 或其许可方所有，并受适用的知识产权法保护。您可以将本网站用于个人、非商业转换目的。未经事先书面许可，您不得复制、抄袭、重新发布或商业利用我们的内容或技术。\"],\"ExTSN0\":[\"否。对于更改，请跳过偏移量。 Δ°F = Δ°C × 9/5，ΔK = Δ°C。将 +32 或 +273.15 应用于差异是不正确的。\"],\"EzSMrQ\":[\"公引\"],\"F0-dhG\":[\"44 ft/s is 30 mph—a common residential speed comparison. A fall speed of 100 ft/s is about 68 mph before drag limits.\"],\"F1yJs-\":[\"Spreadsheets aggravate this: formatting a cell as time versus number changes what “1.5” means. When exchanging files, store an explicit unit column (“hours decimal” or “seconds”) instead of relying on cell format alone.\"],\"F4Jah4\":[\"为什么美国和英国加仑不同？\"],\"F6likP\":[\"丹尼尔·加布里埃尔·华氏 (Daniel Gabriel Fahrenheit) 在 18 世纪初生产了可靠的水银温度计，并用方便的数字表示熟悉的天气和体温。水在 32 摄氏度结冰，在 212 摄氏度沸腾，这两个点之间有 180 个分区。这些数字既是科学选择，也是工程选择。\"],\"F6pmwv\":[\"Splits on odd distances (5K, 10K, half) are easier in the distance unit printed on the bib. Convert published pace after you fix the distance language.\"],\"F7GQy7\":[\"千分尺\"],\"F8XkNg\":[\"Why can’t I convert cups of flour with water’s density?\"],\"F8v0B_\":[\"您始终乘以等于一的比率。数字因子看起来像乘法还是除法取决于您编写比率的方式。如果您要消除的单位位于测量的分母中，请将其放入因子的分子中，以便将其消除。\"],\"F9Ur1v\":[\"A 1,200 sq ft bungalow is about 111.5 m² for a European energy certificate. A 200 sq ft deck needs about 18.6 m² of board coverage before waste.\"],\"FAO7bP\":[\"Convert \",[\"0\"],\" and more.\"],\"FCcyCC\":[\"A 75 m² flat is about 807 sq ft—typical one-bedroom sizing talk in US cities. Ordering vinyl for 20 m² means roughly 215 sq ft; add waste percentage after converting.\"],\"FER9kS\":[\"No. Cubic metres measure volume. Shipping cost uses actual mass and a dimensional-weight formula. Volume helps you compute dimensional weight but is not the invoice by itself.\"],\"FFQFcV\":[\"打开针对这两个单元定制的公式、参考表、工作示例和简短常见问题解答的转换对。\"],\"FJHV07\":[\"A 50 cm² adhesive patch is about 7.75 in²—compare to US first-aid box labels. A business card near 46 cm² is roughly 7.1 in².\"],\"FJsRhQ\":[\"通过乘以 10⁻⁹ 将 nm → m 转换。通过除以 1 000 将 nm → µm 转换。在实验室笔记本中明确保留 10 的幂。每次转换后进行单行尺寸检查，可以在大多数转录错误进入纸质草稿之前发现它们。\"],\"FMo4Be\":[\"A 1,000 km² national park is about 386 sq mi. A wildfire mapped at 50 km² covers roughly 19.3 sq mi for US incident reports.\"],\"FNRfvh\":[\"返回首页\"],\"FOKanD\":[\"根据定义，开尔文和摄氏度具有相同的大小。刻度仅因零的位置而不同：开尔文从绝对零开始；摄氏度偏移 273.15。\"],\"FQVDnS\":[\"“2 hours 15 minutes” is a duration. “14:15” is a clock reading. Converters that change seconds into hours answer duration questions. Time-zone shifts and DST change clock labels without changing how long a process took.\"],\"FV-M_m\":[\"对于许多显示器来说，四舍五入后差异是不可见的。对于与财务相关的剂量、数控刀具路径、合法土地面积或期望完全相等的自动测试断言，这些残差会成为真正的错误。\"],\"FXES9z\":[\"美国表格通常需要英尺和剩余英寸（5 英尺 9 英寸），而不是小数英尺（5.75 英尺）。小数英尺在调查软件中很好用，但在医学调查问卷中却让人感到困惑。\"],\"F_Kw4m\":[\"A 3-minute plank hold is 180 seconds on a phone timer. Developing film for 7.5 minutes means 450 seconds on a metronome-style process clock.\"],\"Fh0gaF\":[\"Waste factors of 5–15% are common; patterned carpet can need more for matching. Apply waste after you trust net area. Converting units does not replace waste judgment.\"],\"FiEaL3\":[\"我们可能会显示第三方提供的广告，包括 Google AdSense。这些合作伙伴可能会使用 cookie 或类似技术来展示相关广告，但须遵守您的同意选择和我们的隐私政策。我们不控制第三方广告的内容，也不对其行为负责。\"],\"FkodHJ\":[\"微米和微米一样吗\"],\"Fm5IVm\":[\"一兆米 (Mm) 等于一百万米（1,000 公里）。它对于行星尺度的距离很有用。\"],\"Ft4_7k\":[\"更喜欢以平方米为基础进行换算。英亩 → 平方米 → 公顷是透明且易于审计的。仅最后舍入到法律或农艺背景所需的精度。标题报告和 GIS 图层应在文件名或图层元数据中命名单位，以便下载保持明确。\"],\"FtpbJk\":[\"Dividing by 28 or 30 casually for sales copy is fine; for chargeable shipping volume use the precise factor. Do not convert litres of fuel directly to engine displacement in cubic inches without the right chain. Chest freezer “litres” are usually internal volume, same idea as ft³ capacity.\"],\"FtrmVo\":[\"导航、跑步和骑自行车以公里或英里为单位，具体取决于国家/地区。配速（分钟/公里与分钟/英里）是一种相互转换，人们在比赛压力下会犯错——在比赛开始前进行转换，而不是在间歇期中进行转换。\"],\"FuV6GZ\":[\"是的，距离和速度共享相同的长度单位（公里/小时和英里/小时）。仔细转换；在高速公路上，小错误很重要。\"],\"FvnUXm\":[\"When a US telehealth portal rejects a weight, check whether it expects lb and you typed kg (or the reverse). Unit mismatch looks like physiologically impossible input.\"],\"FwOFRr\":[\"行之有效的行业模式\"],\"FxCqni\":[\"华氏度\"],\"G-NV0Y\":[\"Carpet and flooring are sold by area—square metres or square feet—not by a single length. The reliable workflow is: measure length and width in one unit → multiply for area → convert area if the seller uses another unit → add waste → round up to pack coverage.\"],\"G6yWBM\":[\"地板报价需要面积（平方米或平方英尺），而不是单一长度。如果您将房间长度从米转换为英尺，但在相乘之前忘记以相同的方式转换宽​​度，则面积将因长度比例因子（而不是其平方）而出现错误，并且对于材料订单而言仍然是灾难性的。\"],\"GBcBVU\":[\"公制单位是如何组织的\"],\"GI4ARo\":[\"一平方分米 (dm²) 等于 0.01 平方米。它位于公制面积阶梯中的厘米和米平方之间。\"],\"GMvNL5\":[\"For ordinary duration conversions between day, hour, minute, and second as defined here, yes—1 day = 24 hours. Calendar date arithmetic and leap seconds are separate problems.\"],\"GN2514\":[\"Using 1.6 as a permanent factor is fine for rough estimates but drifts on long routes; prefer 1.609344 for odometer math. Do not confuse nautical miles (1.852 km) with statute/international miles. Speed limits in km/h are not the same numbers as mph after conversion.\"],\"GN8M4d\":[\"A Julian year equals exactly 365.25 mean solar days (31,557,600 seconds). Astronomy uses the Julian year as a fixed long-duration time unit.\"],\"GO6Qpp\":[\"一立方微米 (μm3) 等于 10⁻18 立方米。细胞生物学和微粒研究通常以这种方式报告体积。\"],\"GSr0rF\":[\"打开菜单\"],\"GYEDYg\":[\"土地面积换算一目了然：英亩、公顷、平方米和平方公里——以及测量历史中的确切因素和陷阱。\"],\"Ge7-Dm\":[\"A laptop listed as 35.6 cm wide is 14 inches (35.6 ÷ 2.54). A European jeans waist of 81 cm is about 31.9 inches—close enough to pick a US size 32, then confirm the brand’s size chart.\"],\"Gfkeis\":[\"Using 30 L per ft³ is a rough estimate (~6% high). Shipping “dimensional weight” in ft³ is not the same as liquid litres of capacity—confirm whether the spec is internal volume. Natural gas ccf is hundred cubic feet of gas, not liquid litres.\"],\"Ggv1Zo\":[\"常见问题解答：\",[\"tFrom\"],\"至\",[\"tTo\"]],\"GiEH4u\":[\"How many grams are in an ounce?\"],\"GiSGSO\":[\"在日常长度中，厘米经常出现，但科学家在技术绘图中通常更喜欢使用毫米或米。使用符合当地惯例并保持数字可读的前缀。\"],\"Gid6Sb\":[\"切勿在未平方的情况下对面积使用线性英里到公里系数。面积换算与长度换算不同。 10% 的长度系数误差在平方后变成大约 21% 的面积误差——大到足以在租赁谈判中产生影响。\"],\"Gkj2vG\":[\"Third-party ads and links\"],\"GnRuu0\":[\"Some consoles let you display pace. Confirm whether that pace is per mile or per kilometre. A 6:00 pace sounds easy per mile and brutal per kilometre.\"],\"GoyGZ5\":[\"厘米\"],\"Gp92Y2\":[\"肘节是一种基于前臂的古代长度单位，此处标准化为 0.4572 米。它出现在历史建筑和圣经学术中。\"],\"GpEDw7\":[\"光学显微镜分辨率的讨论模糊了微米和纳米尺度，具体取决于技术。将单位与仪器有意义的精度相匹配。将仪器的 12.345 µm 报告为 0.2 µm，在从毫米转换后会产生错误的置信度。\"],\"GpGrm4\":[\"A 2,500 L bright tank is 25 hL on a production schedule. Milk intake of 12,000 L in a morning is 120 hL for a co-op report.\"],\"GqMz0I\":[\"定义比例的固定点\"],\"GrBwfT\":[\"该网站基于 TanStack Start 和 React 19 构建，针对您键入时的即时加载和实时结果进行了优化。\"],\"GsWptO\":[\"从英尺和英寸转换为公制时，先将整个高度转换为英寸，然后转换为厘米，最后四舍五入一次。分别对每个步骤进行四舍五入可能会产生您未测量的厘米。\"],\"GtE1iJ\":[\"Converting metric and US training plans\"],\"GuJItQ\":[\"Using 30 g per ounce is a rough kitchen shortcut (~6% high). Fluid ounces measure volume, not weight—do not convert fl oz with this mass pair. Troy ounces for silver and gold differ from avoirdupois ounces.\"],\"GzLnft\":[\"A Gregorian mean year is 365.2425 days—close but not identical to 365.25. Calendar age in birthdays is not Julian-year duration. Leap-second tables affect civil time, not the Julian-year day count definition used here.\"],\"H34q0n\":[\"烘焙配方对液体比例很敏感。将 250 mL 公制杯更换为为 240 mL 美制杯编写的配方，可悄悄添加液体。蛋糕和面包可能仍然有效；马卡龙和层压面团可能不会原谅它。专业厨房通过称重几乎所有东西来避免歧义。\"],\"H44uN7\":[\"一平方英里约等于 2.59 平方公里。美国和英国的地理统计数据通常以平方英里表示大面积。\"],\"H7OUPr\":[\"Day\"],\"H87kj4\":[\"面积不是长度\"],\"HAYZTF\":[\"Trip computers may let you switch L/100 km ↔ mpg. After switching, reset averages; old samples mixed under another unit display still confuse humans even if the computer converted correctly.\"],\"HCBVZC\":[\"四舍五入、有效数字和显示\"],\"HEqFN-\":[\"A cup of flour can vary by tens of grams depending on scooping and humidity. A 120 g portion does not. Grams and ounces measure mass; cups measure volume. When a recipe lists weight, trust the scale and convert units—do not re-approximate with cups unless you accept variability.\"],\"HFxio6\":[\"Planetary fact sheets may list periods in days or in years—check the footnote. If a year is undefined, ask whether they mean 365.25 d, 365.2425 d, or Earth’s actual orbital period (which differs slightly from both).\"],\"HHeAbn\":[\"A 200 L chest freezer is about 7.06 ft³ on US retail tags. A 1000 L IBC tote is roughly 35.3 ft³ for warehouse slot planning.\"],\"HHu18M\":[\"使用配方作者假定的杯子标准，或将配方转换为毫升和克。公制杯 (250 mL) 和美制杯 (~240 mL) 不可互换用于精密烘焙。\"],\"HII3iR\":[\"A 5,000 m training interval is a 5 km workout. A 42,195 m race distance is the marathon’s 42.195 km official length.\"],\"HMCYfQ\":[\"一皮米 (pm) 等于 10⁻12 米。它通常用于化学中的原子半径和键长。\"],\"HRyxe7\":[\"堆场（国际）\"],\"HSp70r\":[\"如果两种单位选择具有同等的可读性，请选择一种能够最大限度地减少方程或机器转换步骤的单位。更少的转换意味着更少的机会反转因子或忘记平方面积比例。\"],\"HTgMtz\":[\"应力、压力、密度和流量组合单位。将每个基本尺寸转换为因数的正确幂。压力转换误差通常始于线性使用的长度或面积系数。\"],\"HaSyAZ\":[\"是的。 Units Converters 可供学生、专业人士和日常任务免费使用。结果仅供参考。\"],\"High-precision unit conversion for students and professionals. Convert hundreds of units instantly.\":[\"High-precision unit conversion for students and professionals. Convert hundreds of units instantly.\"],\"HjRGcU\":[\"Where time zones actually matter\"],\"HshOlm\":[\"Tide atlases and racing handicaps assume nautical miles and knots. Converting a race course to statute miles without converting the rating math breaks comparisons between seasons and fleets.\"],\"HzdxZ3\":[\"为什么使用我们的 \",[\"quantity\"],\" 转换器？\"],\"I2PMyS\":[\"负摄氏度温度在冬季气候中很常见。负开尔文对于普通热力学温度来说没有物理意义。如果转换器从有效输入路径产生负开尔文，则公式的实现是错误的。\"],\"I4MWpI\":[\"If your scale shows kg but your coach talks stone, keep training logs in kilograms and convert only for the coach’s summary. One source of truth beats dual editing every session.\"],\"I5tDdr\":[\"Pound (Avoirdupois)\"],\"I7lEIb\":[\"Packaged food in metric markets lists net weight in grams or kilograms; US labels use ounces and pounds. A 500 g block of cheese is about 1.10 lb; a 1 lb package is about 454 g. For recipes, prefer grams on a digital scale—volume cups vary by packing, but mass does not.\"],\"I9AUvo\":[\"为什么使用我们的 \",[\"tQuantity\"],\" 转换器？\"],\"IAabNJ\":[\"我们对精度的承诺\"],\"IB9sOh\":[\"一寻等于 1.8288 米（6 英尺）。水手们传统上用它来表示水深。\"],\"ID54oN\":[\"细菌大小、人体细胞直径和微加工通道通常以微米为单位。 7-8 µm 大小的红细胞是一个经典的教学示例。植物细胞和许多原生动物的厚度可达数十或数百微米，这就是生物学讲座在句子中间跳跃前缀​​的原因。\"],\"IDLKQN\":[\"为什么 1 平方公里等于 1 000 000 平方米？\"],\"IGLs5H\":[\"When do I add waste factor?\"],\"IHKGd9\":[\"37 km/h wind is 20 knots—common small-craft advisory territory depending on local rules. A ferry at 40 km/h is about 21.6 kn.\"],\"II2IKg\":[\"Convert Fahrenheit to Kelvin when US process specs (°F) feed equations that need absolute temperature—ideal gas work, thermal noise, or materials science. Convert °F→°C first, then add 273.15, or use K = (°F + 459.67) × 5/9.\"],\"IIEWyi\":[\"48 hours of ferment time is 2 days on a kitchen calendar. A 168-hour work stretch is 7 days—one full week of continuous hours.\"],\"IIV9CL\":[\"Treating linear metres of skirting like square metres of carpet. Treating roll width as area. Forgetting hallways. Using interior paint-area estimates (which subtract windows) for flooring (which usually should not).\"],\"IMhaKg\":[\"A week is exactly 7 days in these converters. Months and calendar years are not fixed-length in the same way—use dedicated month/year units when that is what you mean, not 30 × day guesses baked into hour math.\"],\"INLttC\":[\"A grain equals exactly 0.00006479891 kilograms. Historically based on a grain of cereal, it still appears in ammunition, archery, and precious-metal weighing.\"],\"IOHLeD\":[\"Pool chemicals and fertilizers often dose by mass per volume of water. Convert the pool volume to litres, convert product mass to grams, then apply the label—not the other way around.\"],\"IOXbAM\":[\"DIY 搁架、3D 打印和相框都受益于毫米，因为公差很严格，而且厘米的小数很容易出错。对于许多制造商来说，19 毫米的架子销孔比 1.9 厘米的销孔更清晰。\"],\"IOmGBB\":[\"How do I convert min/km to min/mile?\"],\"ISY-Yi\":[\"Convert between running pace (minutes per kilometre) and speed in km/h or mph, set treadmills correctly, and compare race paces across metric and US displays.\"],\"IUm2Di\":[\"9 metric teaspoons of cocoa is 3 metric tablespoons for a brownie batch. A ½ tsp salt pinch is 1/6 tablespoon—usually left as teaspoons for readability.\"],\"IVvE-e\":[\"µ 和 m 有什么区别？\"],\"IZeM_y\":[\"Convert acres to hectares for farmland, conservation land, and solar-farm footprints when US acreage must match metric agricultural stats. One hectare is 10,000 m²; one acre is 4,046.8564224 m², so 1 acre ≈ 0.404686 ha.\"],\"IeyIcS\":[\"单位选择无法修复不良的测量结果。它只能清楚地呈现测量结果。转换后如实说明不确定性和重要数字。将不确定的值转换为华而不实的微小单位并不会使测量更加精确。\"],\"IiYyf2\":[\"Using 8-hour “workdays” by accident when the context was continuous hours. 36 hours is 1.5 days, not 1 day 36 hours written carelessly. Keep UTC hour counts aligned if the day boundary matters legally.\"],\"IjdnEx\":[\"Practical conversion habits\"],\"IjrTUc\":[\"好的工程是将数字表示与您将用数字做出的决定相匹配。制造、医学和法定计量的单位转换需要小数或理性数学；天气小部件不会转换城市温度。如有疑问，请选择更严格的表示法 - 小数的性能成本通常小于静默往返错误的成本。\"],\"Ijyjkr\":[\"确定食谱的规模。转换为您烤箱的规模。如果需要，调整风扇。充分预热。用您将使用的架子上的烤箱温度计进行确认。\"],\"Ik5E9h\":[\"清晰浏览 SI 前缀（毫、厘、千、兆、纳等），以便您可以缩放长度、面积和体积，而不会忘记 10 的幂。\"],\"IkJbH4\":[\"An average month equals 30.436875 days (one-twelfth of a Julian year). It approximates the mean Gregorian calendar month for long-term conversions.\"],\"InyonT\":[\"为工作选择合适的单位\"],\"IoAuJG\":[\"正在发送...\"],\"Is9UbN\":[\"A ¼-20 tap drill often uses a 0.201″ hole, about 5.11 mm—handy when your metric drill set jumps in 0.1 mm steps. Plywood sold as ¾ inch is 19.05 mm; European 18 mm sheet is close but not identical for tight dados.\"],\"IuLd0Z\":[\"Pace is an inverse speed\"],\"Iw0UOq\":[\"Which year does a light-year use?\"],\"IzEkB5\":[\"No. One knot is about 1.15 statute miles per hour. Knots pair with nautical miles; mph pairs with statute (land) miles.\"],\"J1IXTw\":[\"Rounding to “1.5 km per mile” understates distance by about 7%. Mixing nautical miles into car navigation produces large errors. Pace (min/mile vs min/km) must be converted separately from pure distance—do not reuse the same shortcut without adjusting time.\"],\"J5LfsL\":[\"Free online unit converter for Length, Temperature, Area, and Volume. Get instant, high-precision results for metric and imperial units.\"],\"J5icM8\":[\"One US cup of water is 240 mL; two cups of broth in a soup is 480 mL. A metric cake that wants 250 mL milk is essentially one metric cup, not a level US cup.\"],\"J6ptGt\":[\"科学档案中的温度数据应使用什么单位？\"],\"JEmvHO\":[\"Airlines often market 23 kg as “50 lb,” but 23 kg is about 50.71 lb. Pack below the kilogram limit after converting with an exact factor, and leave a buffer for scale differences.\"],\"JH5zFD\":[\"当受众和标准发生冲突时，同时发布：主要单位用于合规性，次要单位用于本地清晰度，并附有明确的转换说明。双重标签胜过沉默的假设。使主要单位在视觉上占主导地位，以便读者知道如果舍入不同，哪个值获胜。\"],\"JHXQdU\":[\"在估算排水费的渗透表面时，请始终保持 m² 或 ft² 单位；切换中间电子表格是许可证数字出错的原因。\"],\"JJc0Lk\":[\"Digital kitchen scales often toggle between g and oz (and sometimes lb:oz). Learn your scale’s tare button and unit button before you cream butter. Switching units mid-recipe without zeroing is a common way to double salt.\"],\"JKSPe7\":[\"如果摄氏度是国际标准，为什么我们仍然使用华氏度？\"],\"JQqy6Y\":[\"与来自另一个国家或行业的同事一起审查一个样本输出。如果他们读错了，你的单位选择就会失败——即使数学是完美的。在第一批货物未通过进货检验之前，对设备的可用性测试听起来有些过分。\"],\"JRDMxI\":[\"一立方英尺约等于 28.3 升。暖通空调、航运和美国建筑通常以立方英尺为单位测量体积。\"],\"JT7-iP\":[\"走另一条路会成倍增加。 0.003 m = 3 mm = 3 000 µm = 3 000 000 nm。在前缀单位旁边写上科学记数法可以捕获滑动错误。在导出剥离单元元数据的 CSV 文件时，双重写入特别有用。\"],\"JTggU3\":[\"Updating one dimension after furniture plans change but forgetting to recompute area and reconvert. Build the habit: any geometry change triggers a full pass through the workflow.\"],\"J_hVSQ\":[[\"0\"]],\"JaIZlG\":[\"常见的转换错误\"],\"JaOjwB\":[\"1.2 kg of sugar for syrup is 1,200 g on a recipe card. A 0.025 kg spice purchase is 25 g—typical jar size.\"],\"Jequ1n\":[\"Response time:\"],\"JgyaEz\":[\"对于风扇烤箱我需要进行不同的转换吗？\"],\"Jjp531\":[\"当您的仪器、图纸或当地标准已经使用该单位时，请使用 \",[\"tFrom\"],\"。当您的协作者、法规或工具期望 \",[\"tQuantity\"],\" 的约定时，首选\",[\"tTo\"],\"。在清晰的边界处进行转换并标记每个数字。\"],\"Jq91sW\":[\"Exactly 365.25 days, defined as 31,557,600 seconds. That fixed length is why astronomy prefers it for duration math.\"],\"JrAEfM\":[\"Duration conversions that stay honest\"],\"JrHqjD\":[\"One relationship, three roles\"],\"JsRaBA\":[\"房地产清单随意将面积与建筑面积进行比较，但没有明确说明，这将土地足迹与居住空间混淆了。阅读调查定义。\"],\"K07l5q\":[\"Dividing by 1.6 (statute thinking) yields the wrong knot value. Gusts in km/h converted without noting “gust” vs sustained mislead seamanship decisions. GPS km/h over ground is not the same as speed through water in knots.\"],\"K26O7q\":[\"我们和我们的合作伙伴使用 cookie 来分析网站流量、个性化内容并提供相关广告（例如Google AdSense）。点击“接受全部”，即表示您同意我们使用 cookie，详情请参阅我们的<0>隐私政策</0>。您可以拒绝非必要的 cookie 并仍然使用转换器。\"],\"K2b08X\":[\"使用公里来表示米可以产生数千个单位的距离——通常是旅行、跑步路线和地理尺度。为建筑物、房间和短的室外路段保留仪表。\"],\"K4_ggM\":[\"Convert inches to millimetres when a US fractional drill size, sheet-metal gauge note, or 3D-print dimension must land on a metric CNC program or European fastener chart. Machinists and makers do this whenever CAM software expects mm. Multiply inches by 25.4 for an exact millimetre value.\"],\"K5MpCS\":[\"基本存储可确保您的语言和同意选择发挥作用。仅当您点击我们 cookie 横幅上的“全部接受”后，用于分析和广告的非必要 cookie 才会加载。您可以随时通过页脚中的“Cookie 设置”改变主意。\"],\"K6Vh90\":[\"关于 Units Converters\"],\"K7f7Ew\":[\"Same mass, different everyday labels\"],\"KDdKFc\":[\"双精度 (float64) 足以满足显示舍入后的许多日常转换，但当您需要位稳定的往返、法定计量或严格的自动化测试时，它并不能替代精确的小数因数。对于权威转换器，更喜欢小数或有理数。\"],\"KDw4GX\":[\"再试一次\"],\"KEEL4-\":[\"为这次旅行选择一个计划单位。将所有腿转换为该单位。增加缓冲，少走弯路。然后，如果需要，才将摘要转换为当地路标单位。\"],\"KEiMvb\":[\"先匹配数量，然后匹配单位\"],\"KGZLJU\":[\"步长和步行距离估计值通常混合米和分钟。计步器和手机可能会报告公里数，而您的思维导图则以街区或英里为单位。在已知路径上校准一次。\"],\"KI6QJZ\":[\"干燥与液体测量\"],\"KIjlk9\":[\"Use km/h ↔ mph converters for the speed side and kilometre ↔ mile for distance; apply the 60/pace bridge for the reciprocal relationship.\"],\"KJCno7\":[\"立方公里\"],\"KKMdB4\":[\"最后更新日期：2026 年 7 月 13 日\"],\"KNOYmB\":[\"Seconds, Minutes, and Hours: Precision That Matters\"],\"KU3oCa\":[\"Calibration and belt wear affect true speed slightly. Unit conversion assumes the console’s number is correct; performance testing may need an external check.\"],\"KUJ7qS\":[\"秒差距（视差秒）约为 3.26 光年，在专业天文学中是首选，因为它与视差测量紧密相关。调查论文可能会报告宇宙距离的兆秒差距。\"],\"KY0PLM\":[\"Our kilogram ↔ pound converter pages include common luggage and body-weight tables so you can sanity-check a result in seconds before you argue with a check-in agent or a spreadsheet.\"],\"KYESmC\":[\"人们如何实际使用毫米、厘米、米、公里、英寸、英尺和英里，以及如何为家庭、旅行和 DIY 选择合适的单位。\"],\"KYgd7M\":[\"一光年测量距离\"],\"KYs_tX\":[\"Convert square kilometres to square miles for country size, wildfire perimeters, and city area comparisons in international news. Geographers and emergency management briefings use both. One square mile is 2.589988110336 km².\"],\"KZsVok\":[\"Ignoring local daylight-saving transitions when you need wall-clock hours across a spring-forward night (23-hour civil day). Sidereal days differ slightly from solar days—irrelevant for parcel delivery, relevant for astronomy. “Business days” are not 24-hour multiples.\"],\"KdKXh4\":[\"1 ngström 等于 0.1 纳米（100 皮米）。将 ångströms 乘以 0.1 即可得到纳米。\"],\"Kfx-3R\":[\"A metric carat equals exactly 0.0002 kilograms (200 milligrams). Jewellers use carats to express the mass of gemstones such as diamonds.\"],\"Kh9Y3o\":[\"Centimetre per second\"],\"Ki1FlF\":[\"A 40-acre parcel is about 16.2 hectares—common quarter-quarter section talk in metric reports. A 5-acre hobby farm is roughly 2.02 ha for EU subsidy forms.\"],\"KnLaXP\":[\"立方纳米\"],\"KnvYE8\":[\"立方百米\"],\"KoOxS5\":[\"如果您接受 cookie，我们可能会使用 PostHog (posthog.com) 来了解人们如何使用 Units Converters，例如哪些页面受欢迎、大致区域以及基本设备或浏览器信息。 PostHog 代表我们处理这些数据，以便我们改进网站。当您拒绝 cookie 时，分析功能将被禁用。了解更多信息<0>PostHog 的隐私政策</0>。\"],\"Kopxec\":[\"立方十米\"],\"KrqAV3\":[\"为什么网上商店拒绝我的身高？\"],\"KsOw0Z\":[\"SI 总是正确的选择吗？\"],\"KxbM14\":[\"Convert days to weeks for long training blocks, visa stays, and content calendars when a day count must become week language. Divide days by 7. Athletes periodizing plans and PMs phasing releases use this.\"],\"KyK9gJ\":[\"体积涵盖容量和三维空间——厨房中的升、建筑中的立方米以及精细的科学单位。当食谱混合杯子和毫升时请小心转换。\"],\"L-VeS4\":[\"Metre per second\"],\"L7Ysq_\":[\"Learn why astronomy uses a Julian year of 365.25 days, how that differs from Gregorian calendar years, and when to convert days and years with each definition.\"],\"L8cWHH\":[\"Mach is a ratio to local speed of sound, not a fixed SI-style speed unit like knots or km/h. This converter set focuses on absolute speed units; use performance charts for Mach.\"],\"LAw-mP\":[\"在便利贴上写下 °C 和 °F，以供您重复使用的家庭食谱。双标签可防止周末争吵和烧焦托盘。\"],\"LBKpMd\":[\"下面您将找到常见 <0>\",[\"tFrom\"],\"</0> 到 <1>\",[\"tTo\"],\"</1> 值的快速参考表，以及任何可用的公式，因此您可以一目了然地比较结果，而无需重新输入每个金额。\"],\"LDQTXo\":[\"关于Units Converters|我们的使命和技术\"],\"LIMr6t\":[\"通常是由于中间舍入、历史上不同的脚定义或浮点显示模式。就确切因素、单一转换路径和共享舍入政策达成一致。\"],\"LKhkZX\":[\"任何转换之前的第一个问题是：我要测量什么物理量？然后才选择单位。数量错误使单位错误相形见绌。\"],\"LMqmDO\":[\"Understand L/100 km vs mpg thinking through speed, distance, and volume—convert trip length and pace correctly before you compare car efficiency figures.\"],\"LN3JSA\":[\"公制与美制产品表\"],\"LNBguy\":[\"If the question is “how long,” use second/minute/hour/day converters. If the question is “what time is it there,” use zone conversion. If the question is both—“how long until 09:00 in another city”—convert the target instant, then subtract from now as a duration.\"],\"LPJ1TE\":[\"US retailers quote ft²; many international and commercial specs use m². Keep a project sheet with both columns. Convert the net area, then apply waste in your working unit, then convert again only if packaging demands it.\"],\"LSLt5W\":[\"牛顿温标 (°N) 由艾萨克·牛顿设计。它将水的冰点定为 0 °N，沸点定为 33 °N。\"],\"LSorPc\":[\"保持前导数字可读\"],\"LWnof8\":[\"为什么加工商列出单杯单位？\"],\"LYljkI\":[\"Treadmill buttons and silent unit switches\"],\"LZPLTP\":[\"21 days of meal prep is 3 weeks. A 10-day antibiotic leftover discussion is about 1.43 weeks—usually left in days for clarity.\"],\"LaTAoV\":[\"皮米\"],\"LcET2C\":[\"隐私政策\"],\"Ldr5MD\":[\"Mistakes that empty the truck\"],\"LhMjLm\":[\"Time\"],\"LhRT5N\":[\"在美国较早的书籍中，糖果阶段和肉类熟度经常以华氏度引用，而在其他地方则以摄氏度引用。以与转换烤箱设定点相同的方式转换目标探头温度，然后使用校准温度计进行验证。\"],\"Lj2TEf\":[\"Dividing by 1,000 (thinking like metres→kilometres) makes the plot 10× too large in hectares. A hectare is 100 m × 100 m, not 1,000 m × 1,000 m. Keep building footprint m² separate from whole-parcel hectares in reports.\"],\"Lkvtx4\":[\"风扇（对流）与传统风扇\"],\"LwL41_\":[\"Subtracting 32 after scaling instead of before reverses the formula. Body-temperature shortcuts (“subtract 30, halve”) are rough; 98.6 °F is 37 °C exactly in the usual teaching pair, but real readings vary. Freezing is 32 °F, not 0 °F—do not map 0 °F to 0 °C.\"],\"LwP5Y5\":[\"摄氏度、华氏度和开尔文解释\"],\"M168bP\":[\"立方分米\"],\"M4KE2C\":[\"覆盖物和表土按体积（立方米或升）出售，但以选定的深度分布在面积（平方米）上。体积=面积×深度，长度单位一致。将几英尺的深度与平方米的床混合在一起是一种维度的混搭。\"],\"M76E5N\":[\"平方英尺\"],\"MDjDOw\":[\"Forgetting three zeros turns a 5,000 m run into “5 m.” Elevation gain in metres is not the same as horizontal distance in kilometres—do not divide elevation by 1,000 and call it a trail length. Keep scientific notation (1.5e4 m) straight when pasting from spreadsheets.\"],\"MG3-ZM\":[\"一立方米等于 1,000 升。这个 SI 关系是精确的，是度量池数学最简洁的桥梁。\"],\"MGeKne\":[\"Use centimetres to feet for body height, fabric length, and small room clearances written in cm on clothing or furniture sites but discussed in feet. Parents tracking child height and interior designers switching between EU and US catalogs use this. There are 30.48 cm in one international foot.\"],\"MHl0mQ\":[\"摄氏度和开尔文的大小相同。这就是为什么将摄氏度转换为开尔文是加法：T(K) = t(°C) + 273.15。华氏度更小：一华氏度是摄氏度的 5/9。\"],\"MJ55BJ\":[\"一公顷 (ha) 等于 10,000 平方米（100 英亩）。全球农业和土地管理报告的田地面积以公顷为单位。\"],\"MPmdf0\":[\"汤匙（公制）\"],\"MQXnn-\":[\"滴\"],\"MUQdT7\":[\"使用面积转换器（或乘以精确的平方米到平方英尺系数）。不要将米转换为英尺，也不要忘记对比例进行平方。\"],\"MXhvVh\":[\"十升\"],\"MYhaIK\":[\"为了简单起见，许多工具都会选择一个通用的定义——通常是美制杯或公制杯。当您需要明确的结果时，请阅读该工具的文档并首选基于升的测量值。\"],\"MbaNs0\":[\"Convert light-years to kilometres when popular science distances (nearby stars, galaxy separations) must become a terrestrial kilometre scale for comparison or calculation. Planetarium scripts and astronomy outreach use this pair. One Julian light-year is about 9.4607×10¹² km.\"],\"MbfgGR\":[\"Prefer whole grams for home baking. Tenths of a gram help for yeast or salt in small loaves if your scale resolves them. Converting 0.25 oz of yeast to grams (about 7.1 g) is clearer than leaving fractional ounces on a sticky note.\"],\"Mk46TY\":[\"Water boiling at 100 °C is 373.15 K in steam-table lookups. A lab bath at −40 °C is 233.15 K—below the freezing point of mercury, relevant for some thermometer discussions.\"],\"MkR0Sw\":[\"回顾时间和我们所看到的\"],\"MlE27Y\":[\"Gym plates in metric gyms are often 1.25, 2.5, 5, 10, 15, and 20 kg. US customary gyms use 2.5, 5, 10, 25, 35, and 45 lb plates. A “20 kg plate” is about 44.1 lb—not a 45 lb plate. When following a program written in the other system, convert working weights, then choose the nearest plate combination and log what you actually lifted.\"],\"Mpzx-l\":[\"Convert square inches to square centimetres for packaging labels, gasket cross-sections, and sheet sticker sizes when US print specs meet metric manufacturing. Multiply in² by 6.4516 exactly (since 1 in = 2.54 cm).\"],\"My0Q3W\":[\"A 1.5 L soft drink is 1,500 mL for calorie apps that expect millilitres. Mixing 0.25 L of stock means 250 mL on a kitchen measuring jug.\"],\"N5JSCo\":[\"Exactly 1.852 km/h, because the international nautical mile is exactly 1,852 metres and a knot is one nautical mile per hour.\"],\"N7wd8d\":[\"对于食品储藏室的主食来说，重量胜过任何品脱的定义。一品脱蓝莓和一品脱米饭是市场惯例，而不是实验室数量。\"],\"NC2AI2\":[\"长度\"],\"NCSre5\":[\"Questions about the product, accuracy reports, or partnerships can be sent through our Contact page. We aim to reply within two business days.\"],\"NIu6uZ\":[\"Convert metres per second to kilometres per hour for weather winds, physics problems, and athletics when SI base speed must become everyday road units. Multiply m/s by 3.6 exactly. Meteorology and school labs share this pair.\"],\"NL39Lv\":[\"Orbital periods, pulsar timing educational examples, and stellar age order-of-magnitude charts often prefer a fixed year so plots do not depend on calendar reform history. Simulation timesteps labeled in years usually mean this fixed unit unless stated otherwise.\"],\"NMPfUh\":[\"Is density a unit you can convert like kilometres?\"],\"NPlROR\":[\"保留一张小参考卡：US gal ≈ 3.785 L；英制加仑 ≈ 4.546 L；公制杯 = 250 mL；美国法定杯子 = 240 毫升。这四个数字可以防止大多数厨房灾难。\"],\"NPq2gb\":[[\"fromLabel\"],\" 至 \",[\"toLabel\"]],\"NSKeEf\":[\"Exactly 14 avoirdupois pounds. One stone is also exactly 6.35029318 kilograms via the international pound.\"],\"NZsHs1\":[\"<0>科学等级：</0> 包括玻尔、Ångström和秒差距等稀有单位。\"],\"NgkOcN\":[\"本隐私政策目前以英文提供。如有疑问，请联系 voyagertecnologias@gmail.com。\"],\"NjLlsq\":[\"Wind shear of the mental kind\"],\"NmFWqV\":[\"专为日常和科学用途而设计\"],\"NnGSWC\":[\"Waste, pattern match, and roll width\"],\"Nngtz6\":[\"Convert km/h to m/s for drag equations, ballistic apps, and lab write-ups that need SI base units. Divide km/h by 3.6. Engineering fluid notes and school physics prefer m/s.\"],\"No-Vxm\":[\"人们混淆这些词是因为日常语言很松散。我们说一个房间有 20 平方米，一个游泳池可以容纳 50,000 升，一块田地有 2 英亩，然后要求转换器在这些数字之间跳转，而不检查尺寸。\"],\"NoA-sZ\":[\"摄氏度和华氏度是日常间隔尺度：相同的度数测量温差，但选择它们的零点是为了方便人类。开尔文是绝对热力学标度：零开尔文是绝对零，此时分子运​​动达到理论最小值。\"],\"Nq1fZ8\":[\"Sliding the decimal nine places the wrong way (×10⁹ instead of ×10⁻⁹) is the classic error. Do not confuse nm with µm (micrometres)—1,000 nm = 1 µm. Ångströms (0.1 nm) are yet another scale; convert Å→nm first if needed.\"],\"Nrg13g\":[\"方码\"],\"Nu4oKW\":[\"描述\"],\"Nz6P6E\":[\"Convert into the unit the carrier’s rate card uses for chargeable weight, then compare actual and dimensional weight in that same unit.\"],\"O2S2Tn\":[\"If the text mentions light-years, astronomical constants, or SI-style durations, interpret “year” as Julian unless another convention is stated. If the text mentions birthdays, tax years, or history timelines, use calendar rules.\"],\"O4C-EF\":[\"英语国家重复使用品脱、夸脱和加仑等单词来表示液体计量单位，然后以不同的方式对它们进行标准化。美国液体加仑为 231 立方英寸（即 3.785 411 784 升）。一英制加仑为 4.546 09 L。这大约是 20% 的差异，大到足以破坏稀释数学和饮料产量规划。\"],\"O4_gQW\":[\"单位转换指南 | Units Converters\"],\"OB2sQ-\":[\"烹饪体积换算：杯子、升和勺子\"],\"OCsIdb\":[\"转换就是乘以一\"],\"OHrgxR\":[\"无论您是将身高换算为表格、将房间面积换算为地板、将烤箱温度换算为配方，还是将池体积换算为化学品，Units Converters 都会为您提供清晰的结果以及上下文 — 单位描述、工作示例以及解释数字背后系统的指南。\"],\"OJLklK\":[\"Is 12.5 stone the same as 12 st 5 lb?\"],\"OJaUnH\":[\"Metric tonnes appear on freight, not parcels. One metric tonne is 1,000 kg (about 2,204.62 lb). Do not confuse it with a US ton (short ton) or UK long ton when reading ocean quotes.\"],\"OMSKkw\":[\"建筑师和室内设计师根据当地规范和软件默认值选择米或英尺。天花板高度接近 2.4 m（约 8 英尺）是常见的住宅标准。将海外家具尺寸导入本地平面图时请小心转换。\"],\"OOBbxV\":[\"引号可能包括浪费、模式匹配或不同的舍入。首先比较同一单位的净面积，然后讨论附加项目。\"],\"OOgS84\":[\"Hours, minutes, seconds, days, and weeks convert among themselves as pure spans: 1 h = 60 min = 3,600 s; 1 d = 24 h; 1 wk = 7 d. Those factors do not care whether you are in Tokyo or Toronto.\"],\"OPOKGZ\":[\"保留泳池数据卡\"],\"OTifQT\":[\"一英里等于多少公里？\"],\"OU1qS8\":[\"威廉·汤姆森（开尔文勋爵）提出了绝对热力学温度。开尔文从绝对零开始，并使用与摄氏度相同的度数。气体行为和统计力学方程更喜欢绝对尺度，因为比率和绝对值表现得很干净，没有任意偏移。\"],\"OUVAnT\":[\"Pace and speed link time to length (min/km, km/h). Convert the time portion with time units, convert the length portion with length units, then recombine. Changing only one side breaks the rate.\"],\"OXtWeT\":[\"知识产权\"],\"OY86E0\":[\"Using 2.2 as if it were exact for legal or shipping work. It is a handy approximation, not the definition. Multiplying by 2.2 and also adding a “safety pound” without knowing which scale unit you started from compounds error.\"],\"OaYVBV\":[\"一光分钟是光一分钟传播的距离，大约1800万公里。日地光时间大约为八光分钟。\"],\"ObatIZ\":[\"Contract law and finance use calendar or business-day conventions. Scientific converters do not replace those legal definitions.\"],\"Oc5anK\":[\"一旦您确定了杯子的定义，杯子中列出的库存、葡萄酒和牛奶就会通过简单的比例因子转换为升。减少会改变浓度，但不会改变换算数学：减少一半的 500 毫升仍然是关于剩余内容的体积声明。\"],\"Ocfc0k\":[\"公亩\"],\"OfxjPc\":[\"连贯系统为每个数量选择一个基础。对于长度，SI 使用米。英尺、英里、纳米和光年都可以表示为米的倍数。对于面积，相关SI单位是平方米；体积，立方米。升很方便，但仍然通过立方米来定义。\"],\"Oi5xN4\":[\"Forgetting the leftover pounds after whole stone (11 st 4 lb ≠ 11.4 st in the casual sense people speak). Using 6 kg per stone is rough. Stone is not used for freight—do not put stone on a bill of lading.\"],\"OjzTFj\":[\"Set the instrument cluster and phone navigation to the local unit. Convert any handwritten pace notes from home. Recalculate ETA with distance and average speed in one system. Recheck the first three posted limits against your display.\"],\"OpPtVE\":[\"No. Convert lengths into one system first, or convert the finished area with an area converter. Mixed units in the product L × W are invalid.\"],\"OrotT6\":[\"Convert m/s to mph when SI sensor logs, drone telemetry, or physics results must be explained in US customary road units. Multiply m/s by about 2.23694. Research papers often leave speed in m/s until the public summary.\"],\"Otkaib\":[\"一块木板（木板测量面积）大约等于 0.00774 平方米，即一英寸乘一英尺木板的表面积。木材行业使用相关的委员会措施。\"],\"Ovv7QR\":[\"我们是谁\"],\"OwOFA9\":[\"占地 2.5 英亩的业余农场约为 1.01 公顷或约 10 117 平方米。 40公顷的果园面积为0.4平方公里，约98.8英亩。这些大概有助于阅读国际列表。\"],\"P0Yqo4\":[\"Ground speed from GNSS is also often shown in knots in cockpit devices. A car-oriented app on a tablet may default to mph; switch units so your ETAs match sectional-chart thinking in nautical miles.\"],\"P2WxBN\":[\"粗略比较、游戏、数据可视化和许多科学模拟都可以容忍浮动误差，因为模型的不确定性使表示误差相形见绌。关键是了解你的耐受力。如果一毫米很重要，那么浮标就需要纪律或更换。\"],\"P2tpOX\":[\"地点：\"],\"P6r3Wv\":[\"开尔文 (K) 是热力学温度的 SI 基本单位。绝对零为 0 K；水的三相点定义为 273.16 K 附近。\"],\"PHCamF\":[\"How do I convert mph to km/h quickly?\"],\"PHahRE\":[\"温度会出现偏移：摄氏度和华氏度是仿射标度，而不是纯粹的比率。将 20 °C 转换为华氏度并不是简单地乘以 1.8；您必须应用正确的偏移量。长度、面积和体积转换几乎总是纯比例因子——温度是常见的例外。\"],\"PKNAUK\":[\"The conventional light-year uses the Julian year: the distance light travels in vacuum in 365.25 days of 86,400 seconds each.\"],\"PKojqY\":[\"剂量取决于体积\"],\"PKuW0V\":[\"Countries that use metric post body weight and baggage limits in kilograms. US gyms, some airlines’ US-facing pages, and older medical charts still speak in pounds. If you travel, train, or shop across those systems, convert once into a single “home unit,” then keep every note in that unit until you must publish the other.\"],\"PMm8O1\":[\"Convert minutes to seconds for workout intervals, exposure times, and PLC timers when coaches or cameras speak in minutes but devices count seconds. Multiply minutes by 60. HIIT clocks and lab protocols share this pair.\"],\"PMyP81\":[\"同意首选项将保留在您的浏览器中，直到您清除网站数据或更改它们。仅在响应和改进服务所需的时间内保留反馈消息。分析和广告保留遵循每个提供商的政策。\"],\"PN32f0\":[\"这些条款的变更\"],\"PO5-UO\":[\"我们的面积中心和平方米↔平方英尺转换器页面包括常见房间尺寸的表格，因此您可以快速检查承包商报价。\"],\"PX7ryq\":[\"什么时候应该使用公里而不是米？\"],\"PYUG3T\":[\"Broadloom rolls have fixed widths. Installers compute cuts from room dimensions and roll width—not from area alone. Still, purchasing starts from credible total area so the quote’s square footage matches your sketch.\"],\"PZilhx\":[\"符号很重要：m 表示毫，M 表示兆。当你的意思是毫米时，写成“Mm”是一场三个数量级的灾难。教导初级人员在信任 CAD 导出之前仔细阅读符号。\"],\"PZtSIm\":[\"Accuracy, liability, and use limitations for Units Converters conversion tools and educational guides.\"],\"PbQ5rS\":[\"数据存储也使用兆和千兆，但二进制倍数（mebi、gibi）使该域变得复杂。不要将二进制前缀混淆引入到物理单位转换中——米仍然是十进制。\"],\"PbVtIn\":[\"Assuming 1 ft ≈ 0.3 m is rough; over a 100 ft span the error is about 0.5 m. Ceiling fans and door kits sold in feet can fail metric rough openings if you round aggressively. Distinguish nautical miles and statute miles from feet before converting long distances.\"],\"PfKowa\":[\"如果表格仅接受两位小数的米，则 175 cm 变为 1.75 m。尽可能保留厘米值作为权威测量值。\"],\"PfUo8Q\":[\"Multiplying by 10 is a rough rule that undershoots by ~7%. Converting only one side’s metres to feet then squaring is correct; converting the area with a length factor (×3.28) without squaring is wrong. Balcony and interior areas are often priced differently—convert each zone separately if needed.\"],\"Pj1TgM\":[\"精确因素与测量因素\"],\"PjwxLc\":[\"When an overseas seller lists m² and your contractor thinks in ft², send both totals. Dual reporting catches silent conversion errors faster than arguing about a single number.\"],\"PnJZV8\":[\"天文单位 (au) 是地球与太阳的平均距离，正好是 149,597,870,700 米。它是太阳系距离的标准尺度。\"],\"PoJ1RI\":[\"Keep a paper trail: density value + source + temperature, mass with unit, volume with unit, then the computed third quantity. Unitless triangles are how lab notebooks go wrong.\"],\"PqJDOq\":[\"Weeks remain 7 days. Converting weeks to Julian years is just weeks → days → Julian years. There is no special “Julian week.”\"],\"PrUagd\":[\"What is dimensional weight?\"],\"Ps1Jhc\":[\"典型的共价键长度约为一到两埃。 X 射线晶体学论文通常以埃斯特伦为单位报告晶格参数。转换为纳米即偏移 ×0.1：1.54 Å = 0.154 nm。转换为皮米乘以 100：1.54 Å = 154 pm — 有时在量子化学输出中更受欢迎。\"],\"PtHTOZ\":[\"Gram\"],\"PtYBBn\":[\"Use square miles to square kilometres when US state or county areas must appear in metric atlases and climate datasets. Multiply sq mi by about 2.58999. Journalists localizing US stories for global readers need this pair.\"],\"Pz9b-x\":[\"US cups and fluid ounces are volumes, not masses. A “cup of flour” cannot enter mass = density × volume until you know flour’s bulk density—and that bulk density varies with packing. Prefer weighing flour.\"],\"Q-Aal_\":[\"最佳实践：测量一个系统中的两侧，相乘以获得该系统中的面积，然后使用面积转换器转换面积。不要仅转换一侧。\"],\"Q3pF29\":[\"温度转换是仿射的，因为为了方便而选择了零。长度单位很少需要偏移；温度几乎总是适用于摄氏度和华氏度。\"],\"Q3tCRg\":[\"Units Converters is operated by <0>\",[\"0\"],\"</0>, based in \",[\"1\"],\". We'd love to hear from you.\"],\"Q4wA-D\":[\"A cubic inch equals about 16.4 millilitres.在美国，发动机排量长期以来一直以立方英寸为单位进行宣传。\"],\"Q6flYH\":[\"公制长度从米开始。前缀乘以或除以十：公里 (1 000 m)、厘米 (0.01 m)、毫米 (0.001 m)。面积使用平方米和平方公里；土地通常使用公顷（10 000 平方米）。体积以升（正好是 0.001 立方米）和较小的厨房度量单位（例如杯子和立方厘米）为中心。\"],\"QAcHa7\":[\"If you convert boat speed into km/h but leave chart legs in nautical miles—or worse, statute miles—your ETA will be wrong. Keep the chain consistent: nautical miles with knots, kilometres with km/h, statute miles with mph.\"],\"QD8opX\":[\"木板\"],\"QEt68F\":[\"纳米\"],\"QF4ciC\":[\"Speed links distance and time—km/h and mph on roads, knots at sea and in the air, and metres per second in science. Convert carefully so trip planning, forecasts, and instrument displays stay consistent.\"],\"QFlLNW\":[\"Using 1.5 ft/s per mph is close; precision work wants 22/15. Free-fall “fps” tables are not vehicle mph conversions—context matters. Do not confuse ft/s with ft/min used in some conveyor specs.\"],\"QKAJhy\":[\"Converting inches to cm then forgetting to square (×2.54 instead of ×6.4516) understates area by a factor of 2.54. Screen sizes in inches are usually diagonals, not areas—do not convert a “27-inch” monitor as 27 in². Paper “lb” weights are not areas.\"],\"QMJWbW\":[\"烘焙时我应该使用哪个杯子？\"],\"QOJxDQ\":[\"Dividing by 3.0 or by 60 (thinking minutes) breaks the result. Car crash Δv in km/h must become m/s before kinetic-energy formulas in joules. Steady cruise in km/h converts cleanly; gust factors are separate meteorology.\"],\"QS9w41\":[\"仅适用于设计可以容忍的软转换。对于精确配合，乘以 25.4 后保留必要的小数，并根据保护公差带的记录规则进行舍入。\"],\"QSK5SE\":[\"Round durations in the unit you publish. If you report minutes, compute from exact seconds first, then round minutes. Rounding each unit field separately can create impossible times like 2 h 60 min.\"],\"QUbbvz\":[\"转换科学长度单位时，优先使用明确的科学记数法和笔记本中的前缀单位：2.5 µm = 2.5 × 10⁻⁶ m。双重写入可捕获转录错误。\"],\"QX5f4l\":[\"The second (s) is the SI base unit of time. It is defined by the cesium atomic clock transition and underpins all other time units here.\"],\"QYOcKt\":[\"未找到指南\"],\"QZADww\":[\"A typical pattern is: dimensional weight = (L × W × H) / divisor, with L, W, H in centimetres or inches and the result in kilograms or pounds matching the divisor’s definition. Divisors differ by air vs ground and by carrier. Always use the divisor printed for your service level.\"],\"QaYB_2\":[\"Knots as the aviation default\"],\"QjOhRB\":[\"Use our hour ↔ minute ↔ second pages for the span half of the problem; keep a trustworthy world-clock for the label half.\"],\"QkUxaa\":[\"GPS apps on phones may default to mph based on locale even on a boat. Switch the app to knots or nautical miles when navigating on water so the display matches charts.\"],\"QtH51n\":[\"风扇辅助烤箱通常需要比传统食谱假设的更低的设定点。许多面包师在改用风扇时温度会降低约 20 °C（大约 25–40 °F）——请查看烤箱手册。\"],\"QwoePw\":[\"单位转换重复乘除这些值。将英寸与毫米相互转换，或将升与立方米相互转换，您可能会看到 2.9999999997，而不是 3。物理转换系数是准确的；计算机表示则不然。\"],\"Qxm3lS\":[\"The Julian year is a unit of time duration, not a calendar system. Saying “4 Julian years” means a specific span of seconds. Saying “the year 2026” names a civil date range. Mixing those meanings breaks orbital periods, age estimates, and light-travel explanations.\"],\"R-n0xD\":[\"7,200 seconds of encode time is 2 hours. A 540-second kilometer split talk converts to 0.15 hours only if you truly need hours—minutes are usually clearer.\"],\"R10pPW\":[\"演算示例\"],\"R2KkO0\":[\"A nanosecond (ns) equals one billionth of a second (10⁻⁹ s). Computer clock cycles and light travel over short distances are measured in nanoseconds.\"],\"R7wYzY\":[\"Is higher mpg always better than lower L/100 km?\"],\"RAk7sB\":[\"转换前的清单\"],\"RCH8pJ\":[\"A milligram (mg) equals one millionth of a kilogram (10⁻⁶ kg). Medicine doses and laboratory samples are often measured in milligrams.\"],\"RGQ9me\":[\"Split L-shaped rooms into rectangles. Measure closets if carpet continues inside. Note doorways and transitions where material stops. For stairs, treat treads and risers with the installer’s method—stair carpet is often estimated separately from floor area.\"],\"RHBcKc\":[\"A week equals 604,800 seconds, or seven days. Work schedules, media cycles, and planning horizons commonly use weeks.\"],\"RK2Vg6\":[\"立方英寸\"],\"RMFRZ8\":[\"A 750 mL wine bottle is 0.75 L. A 5 mL medicine teaspoon is 0.005 L—useful when a protocol lists litres only.\"],\"RMa0EI\":[\"One stone equals exactly 14 avoirdupois pounds. Using the international pound, 1 stone = 6.35029318 kg. UK everyday speech still describes adult body weight in stone and pounds (“11 stone 4”), even though medical records increasingly prefer kilograms.\"],\"RPdunI\":[\"世界上大部分地区的高速公路距离以公里为单位。美国（以及其他一些国家）仍然依赖里程。导航应用程序通常会进行本地化，但印刷指南、比赛号码布和租车仪表板可能不符合您的直觉。\"],\"RQl72i\":[\"当您在单位列表中看到牛顿力旁边的牛顿温度时，请仔细阅读数量标签 - 名称冲突是历史事故。好的转换器首先按数量进行分组，因此温度牛顿永远不会与力牛顿并列，从而导致点击错误的工具。\"],\"RUGtUF\":[\"日常实践中几乎没有什么。它主要出现在历史讨论和综合转换器中。使用摄氏度或开尔文进行新的科学工作。\"],\"RUrWRo\":[\"Converting stone and pounds to kilograms\"],\"RVVJog\":[\"不同国家/地区的道路标志不尽相同\"],\"RVZWrs\":[\"1 m³ = 1,000 L = 1,000,000 mL. Those metric relationships are exact. Convert volume into the unit that matches your density’s denominator before multiplying.\"],\"RWLG6K\":[\"返回首页\"],\"RZdPcg\":[\"Not reliably. Decimal stone means fraction of 14 lb (12.5 st = 12 st 7 lb). Spoken “twelve stone five” means 12 st 5 lb. Prefer explicit stone and pounds.\"],\"Rb2iDn\":[\"尽快将区域单位转换为升（或毫升）。以SI友好的体积工作，然后转换回输出所需的器具或法定单位。往返升数是防止美国/英国名称冲突的最便宜的保险。\"],\"Rig0Vc\":[\"转换 \",[\"translatedUnits\"],\" 等。\"],\"RkEk3w\":[\"What a stone is\"],\"RoafuO\":[\"Send feedback\"],\"RqLaw8\":[\"ell 是一种历史上的布料长度，此处标准化为 1.143 米。裁缝师曾经用它来确定布料的长度。\"],\"RrnUMj\":[\"Convert stone to kilograms when a UK weight mention must enter a metric BMI calculator, racing form, or EU medical record. Multiply stone by 6.35029318. Include any extra pounds by converting them to kg and adding.\"],\"Rzra-p\":[\"Weigh ingredients in grams and ounces, convert between metric and US kitchen units, and know when mass beats cup volume for baking accuracy.\"],\"S5kgXQ\":[\"倾斜地板的平均深度通常为（浅 + 深）/2。如果有建筑商的竣工图，请确认——猜测深度是通常的误差源。\"],\"SBhuQI\":[\"为了精确，放弃估计。使用转换器或精确因子，然后舍入到任务的容差。估计橱柜的展示量就可以了；估计镜头焦距可能不是。\"],\"SCRBEj\":[\"当一张表中的值跨越较宽范围时，科学记数法会补充前缀。列内的一致性比每行巧妙的前缀切换更重要。当单位标记没有每行都改变时，读者比较数字的速度会更快。\"],\"SDu1SG\":[[\"tTo\"],\"是\",[\"tQuantity\"],\"的单位，用于测量和换算工作。\"],\"SEOydL\":[\"Using 5-day workweeks when the context was calendar weeks. Pregnancy “weeks” still use 7-day weeks, but trimester boundaries are medical conventions on top. Do not mix fortnight (2 weeks) without doubling.\"],\"SI83fF\":[\"一立方十米 (dam³) 等于 1,000 立方米。大型土木工程和水量可能会使用此 SI 倍数。\"],\"SLzScS\":[\"然后以两种比例练习面积和体积，以确保平方和立方系数是自动的。大多数残留错误是缺少幂，而不是缺少前缀名称。\"],\"SNZhsc\":[\"Luggage and airline limits\"],\"SNeon4\":[\"Convert square metres to hectares for gardens, solar arrays, and small farms when a site survey in m² must match agricultural hectare language. Divide m² by 10,000. Planners jump from building footprints to plot scale with this pair.\"],\"SOcVZh\":[\"A 250 g coffee bag is about 8.82 oz—near a common 8 oz retail size after rounding. A 28 g protein snack is essentially 1 oz.\"],\"SSePFE\":[\"一泽米 (zm) 等于 10⁻²1 米。该 SI 单位描述了远小于原子的亚原子尺度长度。\"],\"SUKeRV\":[\"Helpful tools\"],\"SUnXE4\":[\"一立方毫米 (mm³) 等于一微升。医学和工程将其用于小体积固体或液体。\"],\"S_C6kV\":[\"液体、还原和替代\"],\"Sg5qt0\":[\"mpg and L/100 km conceptual bridge\"],\"SorZ2H\":[\"速度和简单性：\"],\"SyvevJ\":[\"前缀是十的幂\"],\"T-FuEI\":[\"Moving the decimal three places left instead of right understates dose. Purity percentages apply to mass—convert units first, then apply purity. Moisture loss can change gram readings on a balance without changing the labeled mg of active ingredient.\"],\"T2IREz\":[\"在 Units Converters，我们的使命是提供网络上最准确、可靠且易于使用的转换工具。无论您是解决物理问题的学生、从事全球项目的工程师，还是只是尝试遵循食谱的人，我们都确保您的测量准确。\"],\"T2IycL\":[\"为什么生物学家在同一次谈话中说微米和纳米？\"],\"T70EAD\":[\"根据您居住的地方，您可能有权访问、更正、删除或限制对您的个人数据的处理，并有权反对某些处理或撤回同意。要行使这些权利，请发送电子邮件至<0>voyagertecnologias@gmail.com</0>。您还可以随时拒绝非必要的 cookie。\"],\"TAKEyg\":[\"Use our stone ↔ kilogram and stone ↔ pound pages when you need exact splits instead of guessing leftover pounds.\"],\"TDZWi9\":[\"操作、保护和改进转换器和导轨\"],\"TF71gP\":[\"实用的转换策略\"],\"TG9Hex\":[\"5 英尺 10 英寸等于多少厘米？\"],\"THAiYG\":[\"Convert knots to km/h for marine and aviation contexts when instruments show knots but coastal forecasts or metric pilots want km/h. One knot is one nautical mile per hour = 1.852 km/h exactly. Charts and AIS traffic use knots; phones often show km/h.\"],\"THO4uc\":[\"使用转换器作为规模健身房\"],\"THeuWL\":[\"汤匙和茶匙也有所不同。公制汤匙通常为 15 毫升，公制茶匙通常为 5 毫升，每汤匙三茶匙。抽屉里的旧器具可能不符合这些标准——如果精度很重要，请用量杯校准一次。\"],\"THk9v_\":[\"光时\"],\"TIIXcn\":[\"我可以将平方米换算成升吗？\"],\"TIoOUm\":[\"Gym programs written in pounds need working weights in pounds. Convert body weight only if the program indexes loads to body weight; otherwise convert the prescribed plate weights, not your nickname weight in stone.\"],\"TKPBkZ\":[\"细菌的尺寸通常约为一微米。人体细胞通常有数十微米。人的头发可能有 50-100 微米宽。这些标志帮助学生检查转换后的值是否荒谬。\"],\"TMETeO\":[\"工程转换精度\"],\"TOYKlq\":[\"厘升\"],\"TO_q5m\":[\"向供应商导出的 PLM 必须在文件中注明单位，而不仅仅是在电子邮件中。不明确的 CSV 列很可能会成为废票。\"],\"TOn9Ys\":[\"英亩英寸\"],\"TQX3Zv\":[\"When sharing driving shifts with someone from another country, call out both units for the first hour (“90 km/h, about 56 mph”). Shared speech prevents one driver from “correcting” the other into a ticket.\"],\"TSw1bH\":[\"如何将 \",[\"tFrom\"],\" 转换为 \",[\"tTo\"]],\"TVgTux\":[\"将 \",[\"tFrom\"],\" 转换为 \",[\"tTo\"],\" 会损失精度吗？\"],\"T_A0L1\":[\"Convert knots, miles per hour, kilometres per hour, and metres per second for aviation and meteorology—without confusing airspeed types or nautical vs statute miles.\"],\"TbASKl\":[\"为聚会增加食谱会放大体积误差。将主配方转换为克和毫升，按纯数字进行缩放，然后仅当您的客人坚持看到熟悉的器具时才转换回杯子。\"],\"Tcrwd4\":[\"350 °F 的美国饼干食谱与 180 °C 的欧洲食谱并不相同，即使这些温度是预期的转换对。作家轮流，烤箱运行热或冷，风扇模式改变热传递。\"],\"Tf4hTi\":[\"原子直径约为 0.1 nm (1 Å)。小分子跨度为几纳米。许多病毒的尺寸为数十至数百纳米。可见光的波长为数百纳米——将光学与纳米语言联系起来。\"],\"TfYIF0\":[\"Large commercial spaces sometimes mention acres for campuses, not for a single room. One acre is 4,046.8564224 m². Do not use acre converters for a bedroom—use m²/ft².\"],\"ThjD5u\":[\"越野赛可能会宣传“10K”（公里），而美国的训练计划则以英里为单位。转换一次比赛距离并以您喜欢的单位重建配速。\"],\"Tkn2qr\":[\"我们和我们的合作伙伴使用 Cookie 来分析 PostHog 的网站流量、个性化内容并提供相关广告（例如 Google AdSense）。点击“接受全部”，即表示您同意我们使用 cookie，详情请参阅我们的<0>隐私政策</0>。您可以拒绝非必要的 cookie 并仍然使用转换器。\"],\"Tm6UVw\":[\"千兆位\"],\"TvYt-n\":[\"Label outputs: “duration 2 h 15 min” vs “09:00 JST.” Clear nouns prevent Slack threads from inventing physics.\"],\"TxJfTd\":[\"教学与交流量表\"],\"Tz6ERu\":[\"Foot per second is rare in aviation ops but shows up in some engineering notes. Convert via m/s or mph using a speed converter rather than inventing factors mid-briefing.\"],\"U01G6K\":[\"风扇（对流）烤箱可能需要独立于单位转换进行温度调整。阅读您的设备手册；正确的摄氏度↔华氏度转换仍然无法解决风扇与传统风扇的不匹配问题。\"],\"U52Xlg\":[\"Heart-rate or power targets are independent of unit labels, but the treadmill prescription you programmed is not. Log the unit you actually used.\"],\"U6AfMQ\":[\"When a US recipe says “ounces” for solids, it usually means weight ounces. When it says “fluid ounces” or uses cup marks on a jug, it means volume. Read the word “fluid” carefully.\"],\"U6h7Kn\":[\"Use centimetres to inches when you read a metric product size—screen diagonal, waist measurement, or furniture width—and need the inch figure printed on US packaging or clothing tags. Tailors, online shoppers, and DIY buyers hit this daily. One inch is exactly 2.54 cm, so the conversion is a fixed scale factor with no temperature or material correction.\"],\"UCytWe\":[\"Cookie 设置\"],\"UDdLoM\":[\"Convert metric teaspoons to tablespoons to simplify long spoon counts in cooking and home remedies. Divide teaspoons by 3 when using the metric 5 mL / 15 mL pair. Cake recipes with many small leavening doses benefit from consolidating to tablespoons.\"],\"UGMFzJ\":[\"Use duration converters for spans. Use time-zone tools or explicit UTC offsets for wall-clock labels. This guide trains you to pick the right tool.\"],\"UHep-4\":[\"身高、家具和房间大小是人们最能感受到差异的地方。粗糙的精神锚有助于：1 m ≈ 3.28 ft； 30 厘米 ≈ 1 英尺； 1.6 公里 ≈ 1 英里。对于精密工作（门间隙、CNC 库存、3D 打印），请使用精确系数，而不是内存。\"],\"ULqYGL\":[\"Convert cubic feet to litres for fridge interiors, grow-tent volumes, and compressed-air receiver sizing when US appliance specs meet metric lab or aquarium gear. One cubic foot is about 28.3168 L.\"],\"ULwqUx\":[\"十次方视频和宇宙尺度图形之所以有效，是因为它们以视觉方式行走前缀阶梯。将它们与实际的转换练习配对，以便学生可以计算，而不仅仅是观看。\"],\"UNBdiw\":[\"NHS-style contexts may accept stones and pounds or kilograms depending on the form. Enter exactly the format requested. If it wants kilograms, convert fully; do not type stone into a kg box.\"],\"UO9JCS\":[\"It depends on the country. In most of the world, highway “100” means 100 km/h (about 62 mph). In the United States, “100” would be mph if used—always read local unit conventions.\"],\"UPaWyO\":[\"立方米 (m³) 是 SI 导出的体积单位。全世界的科学、工业和公用事业都将其视为基本体积单位。\"],\"USuKtG\":[\"面积 (a) 等于 100 平方米。它是传统的公制土地单位，是更常见的公顷的基础。\"],\"UU2L0x\":[\"每个量表的日常直觉\"],\"UWdTnl\":[\"肘节\"],\"U_ShX5\":[\"一板英尺是指 1 英尺 × 1 英尺 × 1 英寸的木材体积，约 2.36 升。软木和硬木交易按板英尺定价木材。\"],\"Uc3hYo\":[\"在许多公制烹饪标准中，是的：每汤匙 15 毫升，每茶匙 5 毫升。古董勺子和一些地方用具有所不同，因此如果您需要一致性，请在壶中测量一次。\"],\"UhV2qN\":[\"一英亩英寸是指一英亩一英寸深的体积，约 102.8 立方米。灌溉规划通常使用英亩英寸。\"],\"UivcOF\":[\"一光年 (ly) 是光在儒略年中传播的距离，约为 9.46 万亿公里。它是最熟悉的星际距离单位。\"],\"UkCnks\":[\"英里（国际）\"],\"UkoBlY\":[\"将光年转换为公里会产生巨大的整数。在报告中更喜欢使用科学记数法。如果您需要与目录值一致，请检查转换器的光年是否与儒略年定义相符。与外展的宇宙距离相比，年份定义的不匹配很小，但当您将两个目录与​​许多重要数字进行协调时，这一点就很重要。\"],\"UltkWC\":[\"Convert metres to kilometres for race distances, hiking elevation gain written in metres of trail length, and city planning where short SI lengths become map-scale distances. Sensors and GPS traces often store metres; reports prefer kilometres. Divide metres by 1,000.\"],\"Uo19sX\":[\"一立方百米 (hm³) 等于一百万立方米。水库容量和河流流量通常以 hm³ 为单位。\"],\"Uxl_dU\":[\"<0>即时结果：</0>键入时实时转换。\"],\"V4t9Ir\":[\"Convert millilitres to cups when a European recipe lists mL but your scoop set is cups only. Divide by your cup size (often 240 or 250 mL). Home bakers scaling drink and batter volumes use this daily.\"],\"V5Tvw0\":[\"A 500 L rain barrel is 0.5 m³. A small pool holding 25,000 L is 25 m³ for chemical dosing charts that use grams per m³.\"],\"V5YFZA\":[\"一立方厘米（cm³ 或 cc）等于一毫升。医学和发动机排量常用这个名称。\"],\"V8BCPQ\":[\"GD&T 框架和基准方案在逻辑上与单位无关，但在数字上与单位相关。连贯地更新整个特征控制框架集。\"],\"V8FT3D\":[\"Gym treadmills may default to mph in the US and km/h elsewhere. Hitting “10” intending 10 km/h on an mph treadmill is an all-out sprint (~16 km/h). Check the unit indicator every time you start a belt on travel.\"],\"VBmYgh\":[\"<0>\",[\"tFrom\"],\"</0> 和 <1>\",[\"tTo\"],\"</1> 之间的精确转换首先以 \",[\"tQuantity\"],\" 基本单位表示源值，然后将该基值转换为 \",[\"tTo\"],\"。对于一对一检查：1 \",[\"0\"],\" 等于 \",[\"oneToOne\"],\" \",[\"1\"],\"。\"],\"VFTGk_\":[\"日常生活中的温度通常为摄氏度；科学和工程经常使用开尔文，它与摄氏度具有相同的度数，但从绝对零开始。日常尺度和科学尺度的分离本身就是公制世界的一种习惯。\"],\"VHl_vm\":[\"值得信赖的转换器的实用规则\"],\"VIqLb7\":[\"A kilometre per hour (km/h) equals one kilometre of travel in one hour, or exactly 1/3.6 metres per second. Road signs worldwide display vehicle speed in km/h.\"],\"VJwMZF\":[\"本政策的变更\"],\"VKWvvx\":[\"重新检查壁橱和走廊区域；它们很容易被忽略，而且排序不足也会带来痛苦。如果饰面材料继续进入其中，则包括壁龛。\"],\"VNGnij\":[\"Convert minutes to hours for payroll, flight duration summaries, and battery-life claims when the raw timer is in minutes. Divide minutes by 60. Timesheets and travel itineraries prefer fractional or HH:MM hours.\"],\"VOckpV\":[\"How do I convert knots to km/h?\"],\"VP4uYe\":[\"Convert seconds, minutes, hours, and days without off-by-sixty errors, choose appropriate precision for sports and science, and keep timestamps consistent.\"],\"VPh8EE\":[\"Units Converters是一款面向大众的教育工具。我们不会故意收集 13 岁以下（或您所在地区的同等年龄）儿童的个人信息。如果您认为儿童提供了数据，请联系我们，我们将删除该数据。\"],\"VPrFdY\":[\"Use kilometre ↔ mile and km/h ↔ mph pages to clean trip data, and litre ↔ cubic metre when bulk fuel deliveries show up in m³. Apply a dedicated L/100 km ↔ mpg formula when you need the economy number itself.\"],\"VXw9AH\":[\"兆米\"],\"VYUQn1\":[\"当计划混合单位时，请将图形转换为工具显示的单位。美国的卷尺通常显示英寸；许多公制卷尺显示厘米和毫米。双刻度磁带有帮助，但仍然需要注意您读取的边缘。\"],\"VbArEP\":[\"这些服务条款管辖您对 Units Converters 的使用。通过访问或使用本网站，您同意这些条款。\"],\"Vfv6_l\":[\"牛顿温标（不要与力单位混淆）是一个历史温标，有时仍列在转换器中。它很少在现代实验室工作中使用，但它提醒我们，在摄氏温度和开尔文统治科学之前，许多尺度曾经相互竞争。\"],\"VlmgF-\":[\"对于小比例的面积和体积，请记住正方形和立方体。一平方微米与一平方毫米的关系不是 1 000，而是 1 000² = 10⁶。当缺少该功率时，微流体体积计算会严重失败。\"],\"VwehPU\":[\"今天使用的牛顿温标是什么？\"],\"Vxf_Bz\":[\"Tire speed ratings and placards may list km/h even on US cars. Convert before comparing to your planned cruise speed in mph. The rating is a limit, not a suggestion to drive that fast.\"],\"VyfrRh\":[\"油漆覆盖面积为面积；涂料采购是按量计算的。您需要墙壁面积、涂层数量和覆盖率（平方米每升）才能找到升。如果没有覆盖数据，直接将墙平方米换算成升是没有意义的。\"],\"W-eFzo\":[\"<0>面积：</0>平方米、英亩、公顷和谷仓。\"],\"W4Zked\":[\"Airspeed is a speed—with extra labels\"],\"W59184\":[\"该指南不存在或可能已移动。\"],\"W7S3Hm\":[\"Does cubic metres equal shipping weight?\"],\"WA7PCY\":[\"对于绝对热力学数据，更喜欢开尔文，对于许多实验数据集，更喜欢带有明确标签的摄氏度。切勿未标记温度数字。\"],\"WBkzOv\":[\"更喜欢通过基本单位进行转换，而不是通过许多中间习惯单位进行转换。每一次不必要的跳跃都是抓住错误因素或过早回合的另一个机会。\"],\"WD9Tp-\":[\"二进制浮点数不能准确地表示许多小数因数。每次乘法或除法都会增加微小的舍入误差。即使转换因子在概念上是准确的，通过浮点的往返转换通常也无法恢复原始位。\"],\"WFyvQB\":[\"太阳能发电场和运动场的比较通常在一篇文章中引用公顷，在另一篇文章中引用英亩。在争论哪个网站更大之前先进行转换。\"],\"WHjBY8\":[\"毫米尺加工和产品设计。米统治着建筑和人类运动。连接地标的阶梯使 SI 前缀感觉像地方，而不是琐事。\"],\"WHnM4j\":[\"Convert litres to hectolitres for brewery KPIs, dairy intakes, and bulk wine contracts that report in hL. Divide litres by 100. Trade statistics and cooperative milk collections often prefer hectolitres.\"],\"WJkwxx\":[\"长度测量距离——从材料科学中的纳米到天文学中的光年。使用此中心探索日常和科学长度单位，然后打开任何对进行高精度转换。\"],\"WKFLlL\":[\"Meeting invites, flight itineraries, and “call me at 3 pm” messages need zone labels (CET, EST, UTC+9, etc.). Ambiguous “3 pm” is social debt. Ambiguous duration (“in 3 hours”) is relative to “now” and still needs a shared understanding of the starting instant.\"],\"WKHqM-\":[\"Weight\"],\"WLBBw6\":[\"导出单位（压力、密度、流量）应尽可能来自一致的基础系统。相干性减少了方程中转换因子的数量。\"],\"WY1BnO\":[\"Should I convert stone or pounds for a metric form?\"],\"W_4OFG\":[\"2 metric tablespoons of olive oil equal 6 metric teaspoons—handy when you only have a 5 mL spoon. A recipe calling for 1½ tbsp yeast is 4.5 tsp.\"],\"W_qbAO\":[\"Batch scaling: convert everything to grams, multiply by the scale factor, then convert back to ounces only if your audience insists. Scaling in mixed units invites rounding drift.\"],\"Wa3fck\":[\"Grams and Ounces on a Kitchen Scale\"],\"WfKhnj\":[\"Adding 50% (×1.5) understates true km/h. Aircraft indicated airspeed in knots is not mph—convert knots separately. Treadmill mph to km/h is the same factor as road speed.\"],\"WgkOAz\":[\"A 6-week physiotherapy program is 42 days. A 2-week vacation hold is 14 days of uninterrupted leave if using calendar days.\"],\"WhFxj8\":[\"华氏温标随着仪器贸易而传播，并仍然根植于美国的天气文化和一些工业实践中。它的度数比摄氏度小，对于日常天气谈论来说感觉更细致。这种文化影响力就是双尺度预测对国际受众仍然有用的原因。\"],\"WlBf88\":[\"一平方公里不是 10³ 平方米，而是 (10³)² = 10⁶ 平方米。一立方厘米等于 (10⁻²)³ = 10⁻⁶ 立方米。忘记对前缀幂进行平方或立方是典型的 SI 缩放错误。\"],\"WmSRQz\":[\"不平等的公差和配合（H7/g6 风格的思维，即使历史上以英寸表示）需要特别小心。转换定义配合的限制尺寸，而不仅仅是单个中间值。\"],\"Wnp9Ov\":[\"Use our gram ↔ ounce and kilogram ↔ pound converters to rebuild a US recipe into metric mise en place before the oven preheats.\"],\"WtPE23\":[\"在杯子旁边公布毫升。将升与加仑一起发布。与失败的批次和愤怒的评论相比，双重标签是便宜的。\"],\"WtrXiU\":[\"Using 4 teaspoons per tablespoon (an older US folk rule for some ingredients) breaks metric recipes. Liquid medicines may use a “teaspoon” marking that is not exactly 5 mL—prefer the mL scale on the syringe. Salt and spices packed tightly change mass a lot even when volume conversion is perfect.\"],\"WvwI2N\":[\"我们的免费在线转换器是在公制和英制系统之间切换的最快方式。节省复杂数学的时间，并为学校、实验室工作或建筑项目获得可靠的转换。\"],\"WxMd7u\":[\"This site’s converters handle the building blocks—kilometres vs miles, litres vs other volumes, km/h vs mph for trip pace. Use them to sanitize inputs, then apply a proper economy formula or a dedicated economy calculator when comparing L/100 km to mpg.\"],\"WxgxzV\":[\"Why doesn’t this guide use Mach?\"],\"WzwMp2\":[\"Convert kilograms to stone for body weight in the UK and Ireland, where stone remains common in conversation and some medical contexts. One stone is 14 avoirdupois pounds, exactly 6.35029318 kg. Athletes and clinics still quote stone and pounds together.\"],\"X-Ka-p\":[\"A 750 g loaf is 0.75 kg. Buying 2,500 g of flour is a 2.5 kg bag—standard supermarket sizing.\"],\"X0e445\":[\"阅读 Units Converters 的服务条款，包括使用免责声明、知识产权、广告、PostHog 分析和责任限制。\"],\"X36JoS\":[\"广告\"],\"X5k61m\":[\"清晰地解释了光年作为长度单位的含义——它与米的关系、天文学为何使用它以及它与天文单位和秒差距的比较。\"],\"X7ADLJ\":[\"Convert Kelvin to Celsius when a datasheet, blackbody formula, or cryogenics note lists K but you need everyday Celsius for baths, freezers, or weather context. Subtract 273.15. Space and semiconductor docs often stay in K until the last step.\"],\"X7ej7z\":[\"对于教育太阳系和邻近恒星问题，简单的光行距离是合适且明确的。为已经涵盖扩展空间度量的课程保留宇宙学距离测量的细微差别；过早引入它常常会混淆光年长度的核心教训。\"],\"XApVRd\":[\"Use the feedback form further down this page to describe an issue, suggestion, or question. We'll get back to you as soon as possible.\"],\"XCAO54\":[\"Irregular bays: approximate with rectangles and triangles, sum areas in one unit, then convert once. Rounding each polygon before summing can leave you short by a square metre you will notice at the seam.\"],\"XD51Kk\":[\"Julian Year vs Calendar Year\"],\"XFAKr4\":[\"如果您构建一个计算器 UI，请显示足够的精度以供使用，但不要显示过多的数字，以免浮动噪声看起来像信号。通过浮点数转换后显示十二位小数的长度工具正在宣传其表示错误。\"],\"XGP_rY\":[\"Google AdSense\"],\"XH9-3w\":[\"Aviation: airspeed in knots\"],\"XIG4FZ\":[\"Parcel shops and post offices price by weight tiers. Crossing a tier by 50 g because you mixed oz and g is an expensive lesson. Keep the shipping label’s unit visible while you pack: if the rate card is in kilograms, convert ounces to grams or kilograms before you seal the box.\"],\"XJ9IEG\":[\"Can I convert mpg by flipping the number?\"],\"XJaAmA\":[\"当项目规模发生变化时重新审视选择：以毫米为单位的原型可能会变成以米为单位的场地规划，而无需任何人更新电子表格标题。标题很重要。为长项目建立一页单位登记册，列出数量、权威单位、显示单位和转换所有者，以便更改留下审计线索。\"],\"XKamta\":[\"Average speed on a road trip is far below the posted limit. Use a realistic average (including fuel stops) in one unit system. Convert the posted limit separately when you want to know “how fast am I allowed to go,” not “how fast will I average.”\"],\"XKo6WE\":[\"为学生、工程师、厨师以及任何需要转换单位而无需事后猜测数学的人提供实用、原创的解释。\"],\"XRHIH3\":[\"实践中出现浮点错误的地方\"],\"XWP4R4\":[\"泽米特\"],\"XY2X9o\":[\"Multiplying by 3.0 or forgetting 3.6 leaves wind speeds looking too calm. Swimming and current speeds in m/s look tiny next to km/h—expect large-looking km/h numbers. Do not mix per-second pace clocks with this without converting time bases.\"],\"XaDs5F\":[\"土地面积仍经常使用英亩（约 4 047 平方米）。平面图可能会将平方英尺与公制房间尺寸混合在一起。这种混合在跨越新旧图纸的翻新中很常见 - 在切割材料之前，始终将整个图纸集转换为一个系统。\"],\"Xap8Hr\":[\"Planck长度和其他极端单位\"],\"XedTWK\":[\"Package net weight may show grams and ounces together. Serving sizes sometimes mix mL and g. Convert only within the same quantity type. Calories per ounce change when you confuse weight ounces with fluid ounces of a drink.\"],\"XmGuwW\":[\"家庭烹饪融合了传统。美国食谱依赖杯子和勺子；许多欧洲和专业糕点食谱更喜欢克和毫升。杯子是体积，而不是重量，因此即使杯子相同，一杯过筛的面粉和一杯包装红糖的质量也不同。\"],\"XmONrS\":[\"一个谷仓 (b) 等于 10⁻²⁸ 平方米。粒子物理学家将其用作核和粒子相互作用截面的方便单位。\"],\"XpHBGy\":[\"Use knot ↔ km/h and m/s ↔ km/h tools to translate forecasts and stories, then return to knots for cockpit flows if that is your training standard.\"],\"Xqls_6\":[\"Convert kilograms to grams for baking percentages, supplement scoops, and chemistry stock solutions when the bulk bag is in kg but the formula lists grams. Multiply kg by 1,000. Baker’s percentages become easier in grams.\"],\"XskNVQ\":[\"您实际需要的公式\"],\"Xt1R7n\":[\"体积涵盖了容量和三维空间——厨房里的升，建筑和水池里的立方米，以及精细的科学单位。当配方或化学图表混合杯、毫升和立方米时，请小心转换。\"],\"XtXXfW\":[\"Economy combines volume and distance\"],\"Xtt-ms\":[\"Rule of thumb planning: time (hours) ≈ distance / speed when units match. Nautical miles with knots; kilometres with km/h; statute miles with mph. Crossing those streams is the main arithmetic failure in amateur flight planning.\"],\"Xu4jEX\":[\"A kiln note of 1800 °F is about 1255 K—useful when a ceramics paper cites peak temperature in kelvin. Room temperature ~70 °F is roughly 294 K for electronics thermal margins.\"],\"Xv57vu\":[\"从纳米向上的里程碑\"],\"XvOxd6\":[\"Label every number: “72.1 kg (11 st 4 lb).” Dual labels prevent the 11.4 disaster.\"],\"XvfqE9\":[\"Metres per second appear in scientific wind data and some European forecasts: 1 m/s = 3.6 km/h ≈ 1.94384 kt. A “10 m/s wind” is about 19.4 kt—not 10 kt.\"],\"XvxBAn\":[\"0 K 与−273.15 °C 相同吗？\"],\"XwHg-N\":[\"厨房和陆地上的体积和面积\"],\"Y-SutJ\":[\"将 \",[\"tFrom\"],\" 转换为 \",[\"tTo\"],\" |精确的\",[\"tQuantity\"],\"转换器\"],\"Y1DI3m\":[\"化学品包装和 SDS 文件应明确注明升或立方米。如果出现加仑，请查找美国标签和英制标签。在稀释计算中出现错误会带来安全隐患，特别是对于浓缩液而言，20% 的体积误差并不是表面现象。\"],\"Y1Xhts\":[\"Speed, distance, and why pace shows up\"],\"Y5XbW2\":[\"转换英亩、公顷和平方米\"],\"YA1fYO\":[\"首先转换为基本 SI 单位，然后转换为目标前缀。这种两步走的习惯可以防止你在疲劳时陷入混乱的心理小数点移动。\"],\"YANIWB\":[\"光学和纳米技术中的纳米\"],\"YAz6UJ\":[\"Volume units at the pump\"],\"YCLtFa\":[\"Train timetables that cross borders print local times per station. Differences require zone-aware subtraction; the resulting travel time is a duration you can convert to minutes for comparisons.\"],\"YE8Pkt\":[\"遵守法律义务\"],\"YF5RAs\":[\"公里\"],\"YFMgyy\":[\"Convert Fahrenheit to Celsius for European recipes, lab protocols, and weather comparisons when the source is US customary. Fever checks and pool heaters also flip between scales. Use °C = (°F − 32) × 5/9.\"],\"YHE0TT\":[\"茶匙中的酒精和提取物看起来微不足道，直到您为人群调制鸡尾酒或调味品。转换为毫升，称量，然后用壶或注射器分装以确保一致性。\"],\"YHivUp\":[\"We may also use contextual networks such as Media.net, and optional affiliate links (for example Amazon Associates) on guide pages. Affiliate partners may set cookies when you follow those links. See our Disclaimer for commission disclosure. These partners only load after you accept cookies where consent is required.\"],\"YILUJE\":[\"Planck 长度（~1.6 × 10⁻3⁵ m）是基本常数的理论尺度，而不是实验室量尺。转换器可能会将其包含在教育目的中；它不适用于加工零件。将任何测量到 Planck 长度的实际主张视为对单位作用的误解。\"],\"YIjZh5\":[\"专业转换器在后台执行相同的代数运算。它们将每个单位存储为相对于基本单位的比例（有时是偏移量），然后转换输入→基本→输出。了解这种模式可以让每个转换器变得不那么神秘。\"],\"YJR-DR\":[\"单位是如何定义的\"],\"YLKekz\":[\"国际码正好等于 0.9144 米（3 英尺）。它常见于织物、运动场和美国习惯尺寸。\"],\"YLrn-T\":[\"切勿在二进制浮点数上测试严格相等的转换器。在绝对或相对容差范围内进行比较，或者以规定的精度比较十进制字符串形式。首选使用已知精确对的黄金测试，例如 1 英寸 = 25.4 毫米。\"],\"YMilyE\":[\"从早期的测温仪到摄氏温度、华氏温度、开尔文温度和牛顿温度——温标是如何演变的以及为什么多种温标仍然出现在转换器中。\"],\"YO0ACR\":[\"为什么高度表格会导致如此多的错误\"],\"YOu4q0\":[\"大多数 CPU 以二进制浮点数 (IEEE 754) 存储非整数。在十进制中看起来很简单的分数（0.1、0.001、2.54）通常无法用二进制精确表示。存储的值是最接近的可表示的近似值，并且近似值的算术会累积微小的残差。\"],\"YPKA9a\":[\"The site is provided \\\"as is\\\" without warranties of any kind, express or implied. \",[\"0\"],\" does not guarantee uninterrupted availability, error-free pages, or suitability for a particular purpose. See our Terms of Service for full liability limits.\"],\"YQA630\":[\"Using 236.59 mL (US customary cup) vs 240 mL (US legal cup) vs 250 mL (metric cup) without matching the recipe’s origin. Thick batters measured in a liquid cup still need leveling technique. Do not convert mL of flour to cups and then to grams with a single universal factor.\"],\"YQHoDn\":[\"历史上的干品脱和夸脱添加了另一层与现代家庭烹饪很少相关但仍然存在于档案中的层。未经检查，请勿假设一品脱干品脱等于一品脱液体。\"],\"YR0sYg\":[\"一厘米 (cm) 等于 0.01 米。它是身体测量、服装和学校科学中最熟悉的公制单位之一。\"],\"YST1aG\":[\"世界上大多数人使用的温度尺度和测量单位。\"],\"YX3h2a\":[\"国际单位制 (SI) 中长度的基本单位。\"],\"YdoKWF\":[\"我们的升↔立方米页面包含参考表，可在您打开化学罐之前轻松进行快速健全性检查。\"],\"YecQDf\":[\"有效数字应反映最不精确的输入，而不是计算器的显示。精确到毫米的卷尺并不能证明将转换后的英寸值报告为小数点后六位。\"],\"Yg-ssR\":[\"nm → µm：除以 1 000。 µm → mm：除以 1 000。mm → m：除以 1 000。每个步骤都是十的三个数量级。 nm → m：除以 10⁹（或乘以 10⁻⁹）。练习这些轮班，直到它们在考试或轮班压力下自动发生。\"],\"YgbpQ6\":[\"一跃米 (ym) 等于 10⁻²⁴ 米。它是一个 SI 长度前缀，用于粒子和核物理背景中的极小距离。\"],\"YmJ6sD\":[\"一公制茶匙等于 5 毫升。烹饪食谱将其用于小量液体和粉末的量取。\"],\"YmsuYf\":[\"国际食谱通常将公制体积与摄氏度烤箱配对，而美国食谱则将杯子与华氏度配对。使用适当的仿射公式转换温度；不要将烤箱设置视为体积因素。\"],\"YnThcK\":[\"Use yards to feet for American football, fabric spreads, and garden bed lengths when the quote is in yards but the tape measure reads feet. Three international feet make one yard exactly. Contractors pacing a site in yards often switch to feet for cut accuracy.\"],\"Yp8yB4\":[[\"0\"],\" 至 \",[\"1\"]],\"YrH-Uw\":[\"移液器、微米（工具）和纳米分辨率阶段都要求您将前缀含义与工具名称分开。英语使用微米作为工具和单位拼写变体——上下文可以防止混淆。\"],\"YvLaWs\":[\"课堂和沟通技巧\"],\"YxzxC0\":[\"US friends and apps expect a single pound figure. Convert UK stone-and-pounds to total pounds before sharing. 11 st 4 lb = 158 lb, not “11.4 lb.” That error is an order of magnitude wrong and alarms health apps.\"],\"Yy6PSV\":[\"Density is a derived quantity (mass per volume). You convert its mass and volume parts into consistent units; you do not treat density as a simple length-style unit on this site.\"],\"YyM7nn\":[\"面积测量表面积：房间以平方米或平方英尺为单位，土地以公顷和英亩为单位。选择下面的起始单位，然后转换为任何其他面积单位，无需舍入漂移。地板和土地单元指南与这些工具完美搭配。\"],\"YyOvgd\":[\"校准证书本身使用单位——请阅读它们。在公制 CMM 程序中，以英寸为单位设置的量块不小心转换为毫米是一种过程风险。\"],\"YziFbt\":[\"确定作者假设的杯子和勺子标准。将所有体积转换为毫升。尽可能将干成分转换为克。规模。仅转换回您实际使用的工具。\"],\"Z-2qls\":[\"数据保留\"],\"Z0G7sT\":[\"我们的托管和合作伙伴可能会在您所在国家/地区以外的国家/地区处理数据。如有需要，我们会依赖这些提供商提供的适当保障措施。\"],\"Z0za9b\":[\"大多数在线转换器都存在舍入误差，因为它们使用标准浮点运算。我们的工具是使用 <0>Decimal.js</0> 构建的，这是一个用于任意精度十进制算术的库。这意味着当您转换单位时，您可以获得数学上完美的结果，而不会出现其他工具中常见的“0.000000000004”工件。\"],\"Z2EPvT\":[\"公制汤匙总是 15 毫升吗？\"],\"Z2oISo\":[\"Spices in pinches stay volumetric by nature. Convert spice weights only for large commercial batches.\"],\"Z3J4ir\":[\"当受众或法规跨系统分裂时，就会出现双重标签。避免已经共享一个系统的专业文档变得混乱——清晰的单一单元标签更好。\"],\"Z477h6\":[\"Record fuel volume added and distance driven in consistent units. Convert miles → kilometres (× 1.609344) if your odometer and pump disagree across a border rental. Convert gallons → litres if the receipt and the car computer disagree.\"],\"Z5mL6k\":[\"食品标签制度在法律上对杯子和份量的定义可能与祖母的量杯不同。遵守包装规定；遵循经过测试的食谱进行烹饪。当两者在产品开发厨房中发生冲突时，应保留单独的规格表，而不是强制使用一个模糊的杯子列。\"],\"Z7mHoI\":[\"燃油经济性使问题进一步复杂化：L/100 公里与每加仑英里数的关系颠倒了体积和长度的思维。在比较不同市场的汽车时，通过全维度分析而不是记忆的近似系数进行转换。\"],\"Z9CT1Q\":[\"Looking for a physical tool that matches this guide? Search Amazon for related measuring equipment. We may earn a commission at no extra cost to you.\"],\"Z9_zXG\":[\"开尔文\"],\"ZAGGpv\":[\"从受众和标准入手\"],\"ZC-5dI\":[\"十米\"],\"ZCGBkz\":[\"For civil history—“how many calendar years between these two dates?”—use calendar arithmetic or a mean Gregorian year if you only need an approximation. For converting a physics duration labeled as Julian years, divide or multiply with 365.25 days per Julian year.\"],\"ZCr-px\":[\"如果你正在学习这两个系统，请用你能看到的长度进行练习——桌子宽度、行走速度、牛奶盒体积——这样数字就固定下来了。流畅性胜过记住在压力下不会使用的长表格。在内存中保留一个精确的锚点（每英寸 25.4 毫米），并在精度很重要时导出其余锚点。\"],\"ZKbrdx\":[\"<0>长度：</0>纳米到光年和Planck长度。\"],\"ZOiTtE\":[\"巨型、千兆和大规模措施\"],\"ZQ7HqJ\":[\"Keep a single sticky note on the dash for the first day abroad: “limits are km/h” or “limits are mph,” plus two anchor conversions you actually saw on the route.\"],\"ZQyX5Z\":[\"提交反馈\"],\"ZR5WG6\":[\"哈勃长度是与哈勃常数相关的宇宙学距离尺度，约为 10²⁶ 米，与可观测宇宙的大小相当。\"],\"ZTiCle\":[\"为什么要通过基本单位而不是直接因子进行转换？\"],\"ZU3Tsr\":[\"Confusion starts when people subtract clock faces in local labels without converting both instants to a common timeline. 22:00 in Paris to 08:00 next day in New York is not “10 hours” of subtraction on the printed numbers alone—you must interpret zones and dates.\"],\"ZXmZ3y\":[\"Grams, kilograms, and milligrams\"],\"ZbRlst\":[\"Students sometimes convert a wind of 15 kt to “15 mph” by changing the label without changing the number. That understates wind. Always run the factor.\"],\"ZcqHCH\":[\"Convert hours to days for project timelines, drug half-life discussions, and SLA windows when engineering logs hours but managers want days. Divide hours by 24. Incident postmortems often make this switch for readability.\"],\"ZdYW_Q\":[\"一升 (L) 等于 0.001 立方米。它是饮料、燃料和家用液体的日常公制单位。\"],\"Zdx59c\":[\"Linking speed to distance and time\"],\"ZfFcAX\":[\"信息共享\"],\"Zk5s7v\":[\"一泽米 (Zm) 等于 10²1 米。它是用于宇宙距离讨论的 SI 极值。\"],\"ZlDKKP\":[\"更喜欢重量。面粉堆积密度的变化足以改变面包屑并膨胀。如果您只有杯子，请使用一致的方法（通常是勺子和水平仪）并接受更多的批次差异。\"],\"ZlwDi6\":[\"分析\"],\"ZnNRL9\":[\"可见光的波长大约为 400–700 nm。将激光指定为 532 nm 比 5.32 × 10⁻⁷ m 更清晰。薄膜涂层和衍射问题自然存在于纳米级。只看过科学计数法的学生在转换为纳米时经常会错误地计算零——并排练习这两种形式。\"],\"ZoK1ii\":[\"Tip: knots pair with nautical miles; mph pairs with statute miles. Convert road signs before matching the number. Check whether a treadmill shows km/h or mph before you trust a “10.”\"],\"Zp9qhp\":[\"Clocks label moments; durations measure spans\"],\"Zq12B2\":[\"Decide your coaching unit (min/km or min/mile). Convert the session into treadmill speed in the console’s unit. After the run, convert back to pace for the training log so weeks stay comparable.\"],\"ZqDero\":[\"轻分钟\"],\"ZqGv10\":[\"根据米的 SI 定义，真空中的光速恰好为 299 792 458 m/s。儒略年是 365.25 天，即 86 400 秒。将速度乘以该时间间隔即可得到天文学中使用的光年长度。\"],\"ZstIvO\":[\"Integer division that drops the remainder hides overtime seconds—keep a decimal or a seconds remainder. Leap seconds affect UTC civil time rarely and do not change everyday workout math. Do not convert seconds of arc (angles) with a time converter.\"],\"ZwDOLi\":[\"以升和立方米为单位记录体积（如果当地供应商使用加仑，则以加仑为单位）。如果水位发生显着变化或改造，请更新该卡。\"],\"ZxHSV2\":[\"平方公里\"],\"Zz1yNB\":[\"一立方英里约等于 4.17 立方公里。含水层或冰盖等大型自然特征可以用立方英里来描述。\"],\"_1PTQU\":[\"Wind reports in marine forecasts often use knots. A “20-knot wind” is about 37 km/h or 23 mph. Small-craft advice thresholds are written in knots in many countries; convert only after you understand the category boundaries.\"],\"_5hjoq\":[\"Using 0.1 m² per sq ft overstates area. Office “usable” vs “rentable” sq ft still convert with the same factor—definitions differ, units do not. Do not convert linear feet of baseboard as if they were square feet.\"],\"_798Yd\":[\"Highway efficiency depends on speed. Comparing a US road trip logged in mph with a European test cycle talked about in km/h needs speed conversion so you compare similar driving, not just similar labels.\"],\"_7YLdO\":[\"国际英寸正好等于 25.4 毫米。它仍然是美国习惯系统中的主要长度单位。\"],\"_8v4gg\":[\"在冰箱上放一张小卡片，上面写着您最常用的对：杯子↔毫升，汤匙↔毫升，黄油棒↔克（如果您所在国家/地区相关）。习惯胜过中击打猎。\"],\"_AG8g3\":[\"5 英尺 10 英寸总计 70 英寸。一国际英寸为 2.54 厘米，因此 70 × 2.54 = 177.8 厘米。根据表格规则进行舍入。\"],\"_EVpXF\":[\"Units Converters 可以在厘米、米、英尺和英寸之间移动，并具有精确的系数。当您需要对常见成人身高进行快速健全性检查时，请使用每对页面上的工作示例。\"],\"_GYo86\":[\"Fluid ounces measure volume, not mass. “8 fl oz of milk” is not the same measurement type as “8 oz of flour” by weight. Thick syrups and flour cannot be swapped between fl oz and oz without density.\"],\"_GzALU\":[\"Planck 长度\"],\"_I5kek\":[\"全部指南\"],\"_JuTsa\":[\"Half-stone changes (7 lb ≈ 3.2 kg) are common in fitness talk. Convert the change the same way you convert absolute weight.\"],\"_LMkMS\":[\"全部接受\"],\"_LnHMO\":[\"Assuming a yard is “about a metre” leaves you short on material. Cubic yards of mulch or concrete are volume, not length—do not run them through a length converter. Keep fractions of a yard (½ yd) as 0.5 before multiplying by 0.9144.\"],\"_S1r77\":[\"The Gregorian calendar’s mean year is 365.2425 days (97 leap days per 400 years). That is about 0.0075 days (roughly 11 minutes) shorter than 365.25. Over one year the difference is tiny for casual talk; over millennia or precise ephemerides it accumulates.\"],\"_Ti6Zc\":[\"微升\"],\"_TxE4G\":[\"每国际英寸正好 25.4 毫米。使用该系数进行技术工作，而不是旧的大约 25 毫米的经验法则。\"],\"_URfYe\":[\"Content on this site — including converters, tables, guides, and examples — is general information only. It is not legal, medical, financial, safety, or engineering advice. If your use case involves health, regulated products, structural design, or legal compliance, consult a qualified professional.\"],\"_W-19G\":[\"1 µm 等于 1 000 nm 吗？\"],\"_cF7Rs\":[\"体积\"],\"_hBRwC\":[\"为您的工作选择一个规模\"],\"_jQctM\":[\"到\"],\"_nJAQe\":[\"良好的测量首先要选择一个让数字舒适的单位。家具组装以毫米或英寸为单位。房间布局以米或英尺为单位。公路旅行以公里或英里为单位。使用公里来描述螺距会导致小数点变得尴尬；在公路旅行中使用毫米会迫使使用巨大的整数。舒适度是一种可用性特征，而不是外观偏好。\"],\"_siJPA\":[\"硬转换和软转换有什么区别？\"],\"_tLS2h\":[\"Science and some vehicle test reports use metres per second. 1 m/s = 3.6 km/h exactly. That bridge is handy: convert m/s → km/h by multiplying by 3.6, then to mph if needed. Crash-test and physics problems almost never want mph as an intermediate.\"],\"_tNHZe\":[\"US mpg usually means US gallons; UK historical mpg used imperial gallons. Always note which gallon. Metric countries lean on L/100 km or km/L.\"],\"_tTlsI\":[\"在比较转换器输出时，最后一位微小的差异通常来自舍入策略，而不是来自不同的物理常数。检查两个工具是否使用国际英寸、相同的英亩定义和相同的显示精度。\"],\"_uNC6p\":[\"要拆分总英寸值：将英尺除以 12，并将余数用作英寸。标记两个数字。当您的意思是 5 英尺 9 英寸时，切勿写“5.9 英尺”——它们是不同的高度。\"],\"_wcYGD\":[\"Convert body weight, luggage, and grocery labels between kilograms and pounds with exact factors, mental shortcuts, and habits that prevent airport and gym mistakes.\"],\"_zPIYx\":[\"记录数据集使用的比例。在与现代摄氏系列进行比较之前，历史天气记录可能需要气象站元数据甚至尺度重建。\"],\"a-49Cg\":[\"Stone\"],\"a0_sdV\":[\"Interstate rest stops every 50 miles are about 80.5 km apart. A 26.2-mile training long run is essentially a full marathon distance in kilometres (about 42.2 km).\"],\"a13Epg\":[[\"tFrom\"],\"是\",[\"tQuantity\"],\"的单位，用于测量和换算工作。\"],\"a3pVqb\":[\"常见问题\"],\"a9FhRh\":[\"面积和体积需要平方或立方长度因子。如果 1 m = 100 cm，则 1 m2 = 10 000 cm2，1 m3 = 1 000 000 cm3。忘记对系数进行平方或立方是工程作业和 DIY 材料估算中最常见的转换错误之一。\"],\"a9gM7C\":[\"Align chart distance units with speed units before ETA math. Verify tablet app unit settings before navigation practice.\"],\"a9tQsz\":[\"Convert the full value you know. If you know stone and pounds, combine them (or convert via kilograms) so leftover pounds are not dropped. Forms that want kg should receive a single kilogram number.\"],\"aCRZNA\":[\"浏览该类别中的所有单位\"],\"aDMgNB\":[\"Decide the authoritative measurement (what the scale showed) and its unit. Convert to the destination unit with an exact factor. Round once for display according to the context—whole pounds for casual speech, one decimal for luggage, more for lab work.\"],\"aFqNBm\":[\"转换系数的平方和立方\"],\"aFynR0\":[\"单位为\",[\"0\"],\"。\"],\"aIolGk\":[\"一立方纳米 (nm³) 等于 10⁻²⁷ 立方米。它描述了纳米科学中的分子尺度体积。\"],\"aM9XSi\":[\"A 10-foot shipping container width constraint is 3.048 m—container specs are often written both ways. A 6 ft person is 1.83 m, the figure hospitals and passport forms outside the US usually expect.\"],\"aNO7cW\":[\"宇宙学中存在不同的距离度量（同移距离、光度距离、角直径距离）。从红移到光年的随意转换器嵌入了宇宙学模型假设。将流行的单数转换视为深空天体的近似值。\"],\"aNhKFf\":[\"A microsecond (µs) equals one millionth of a second (10⁻⁶ s). High-speed electronics and scientific instrumentation resolve events in microseconds.\"],\"aOCjZ7\":[\"When you redesign packaging, re-measure and re-convert. A 2 cm reduction on one side changes volume by a percent equal to that side’s relative change—worth calculating before you order 10,000 cartons.\"],\"aOkLxr\":[\"发布数据时，请注明每个表格和绘图轴中的比例。如果双刻度轴都是根据一个主数据集计算的，那么双刻度轴非常适合公共通信。\"],\"aQtyFH\":[\"接受条款\"],\"aR_j-p\":[\"我应该输入以米为单位的高度还是以厘米为单位的高度？\"],\"aSlQH1\":[\"Carriers care about two constraints: how heavy a parcel is, and how much space it occupies on a truck or aircraft. Actual (scale) weight is what a calibrated scale reads in kilograms or pounds. Dimensional weight—also called volumetric weight—is a billing weight computed from the package’s outer dimensions using the carrier’s divisor formula.\"],\"aVVsip\":[\"选择系统并安全转换\"],\"aVyHck\":[\"平方厘米\"],\"aakJC9\":[\"一公顷是一个边长为 100 m 的正方形，很容易在公制地图上可视化。一国际英亩等于 4 046.856 422 4 平方米，通过国际码和英尺定义。对于大多数改造工作，这个确切的定义取代了旧的区域面积。当历史文献中提到的英亩没有几何形状时，请将营销四舍五入视为近似值，直到调查确认它们为止。\"],\"abg1wm\":[\"Carry-on limits are often lower and sometimes stated only in kilograms. Soft bags compress; hard cases do not. Weigh the packed bag, not the empty shell plus a guess. If you own a scale in pounds only, convert the limit first, write both numbers on a sticky note in the bag, and re-check after last-minute additions (duty-free bottles are a classic overage).\"],\"acQncn\":[\"所有 \",[\"tQuantity\"],\" 单位\"],\"adCNaD\":[\"Mile per hour\"],\"agaux1\":[\"对于定义的比例因子，物理关系是精确的。可以改变的是您显示的位数。 Units Converters保持内部运算精确；仅对您需要的输出进行一次舍入。\"],\"airbJ5\":[\"将精确的法律因子存储为小数或有理数，而不是仓促键入的二进制浮点数。以尽可能少的步骤转换输入 → 基础 → 输出。仅在针对人类进行格式化时进行舍入，并记录舍入模式。\"],\"ajla6x\":[\"在现代摄氏温标中，0°C 是水的冰点，100°C 是标准大气压下的沸点——这是有用的锚点，尽管精确计量学现在通过绝对热力学方法和纯物质的固定点来定义尺度。\"],\"alomXo\":[\"Rough intuition: more miles per gallon means fewer litres per 100 km. Exact conversion needs both the mile–kilometre factor and the gallon–litre factor for the correct gallon. Do not invert the number alone (mpg → 1/mpg) and call it L/100 km.\"],\"azzH-3\":[\"您唯一需要的单位转换器\"],\"b1htTh\":[\"<0>移动设备友好：</0>针对在任何设备上使用进行了优化。\"],\"b1vl0n\":[\"平方英寸\"],\"b3gZE4\":[\"Why did 10 on the treadmill feel impossibly fast?\"],\"b6nemW\":[\"定点数学将所有内容缩放到最小刻度的整数计数（纳米、微升或千分之一英寸）。整数运算在溢出之前都是精确的。它适用于具有明确测量量的领域。\"],\"b75dby\":[\"我可以像温度读数一样转换温度变化吗？\"],\"b7JOy7\":[\"英寻\"],\"b7j6GI\":[\"Units Converters\"],\"b8oEnC\":[\"You almost always pay on the greater of actual weight and dimensional weight. A box of pillows can be light on the scale and expensive on the invoice because volume weight wins. A small dense part can be heavy and tiny—actual weight wins. Unit conversion mistakes on either side change which number wins.\"],\"b8qt5E\":[\"温标简史\"],\"bA8xzL\":[\"Ounce (Avoirdupois)\"],\"bBc2Im\":[\"光年是时间单位吗？\"],\"bC8VeG\":[\"挑选长度、面积、体积和温度单位的实用决策指南，使数字可读、符合标准且不易误解。\"],\"bEttEG\":[\"Foot per second\"],\"bEu4-i\":[\"提示：为了烘焙准确性，尽可能以克为单位称量原料，而不是转换杯子体积。对于水池和水箱，在转换为升之前先确认几何形状。\"],\"bJliMa\":[\"Why do pilots and sailors prefer knots?\"],\"bQ1on8\":[\"在项目注释中记录因素来源（国际英亩、当地法规）。将来你将不记得你输入了哪个常量。如果客户提供了旧测量英尺制度中的英亩数，请在任何人根据软转换的公顷数设计围栏之前在同一张注释中标记这一点。\"],\"bQPqVr\":[\"If your warehouse stores dimensions in millimetres and the carrier wants centimetres, divide each side by 10 before multiplying—or convert after computing mm³ into cm³ carefully. Keep a single spreadsheet column unit and validate with a known sample box.\"],\"bU8uH1\":[\"不直接。升测量体积。您需要深度或厚度才能将面积转换为体积，然后将立方米转换为升 (1 m3 = 1 000 L)。\"],\"bZOK_f\":[\"圆铣刀\"],\"b_5xND\":[\"皮升\"],\"baKgzz\":[\"您的权利\"],\"bb1zDx\":[\"How many km/h is one knot?\"],\"beqMSh\":[\"Dividing by 1.5 is a rough estimate. River currents quoted in ft/s can look slow in mph—0–5 mph still matters for boats. Chronograph “fps” for airsoft vs firearms differ in magnitude; convert the number you actually measured.\"],\"bhMg6o\":[\"英制和美国习惯单位如何工作\"],\"bkkcq9\":[\"换算面积时，将长度系数平方。转换体积时，将其立方。 1 m = 100 cm 意味着 1 m2 = 10 000 cm2，1 m3 = 1 000 000 cm3。在此示例中，将线性因子应用于面积值会欠转换 ×100。\"],\"blMdOu\":[\"对于运动员和儿童，请定期重新测量，而不是永远转换旧值。即使单位系统保持不变，生长和姿势也会改变真实长度。\"],\"bnEMkn\":[\"转换器 UI 应分隔数量选项卡：长度、面积、体积、温度。跨数量转换选项会导致无意义的结果。如果您构建工具，请禁用不可能的对。\"],\"bnSOB9\":[\"ISO-8601 durations (PT1H30M) encode units explicitly. When APIs return raw seconds, document that contract. Silent disagreement between “seconds since start” and “minutes since start” is a frequent integration bug.\"],\"bpWxqN\":[\"Dashcams and OBD apps may log SI units internally and display your preference. When exporting a CSV for insurance or coaching, note the unit column. A silent m/s vs km/h swap makes you look ten times too slow or too fast.\"],\"brSuoe\":[\"英亩\"],\"bsT5BU\":[\"科学长度单位：Ångström、纳米、微米等\"],\"bxtojs\":[\"为什么厨房的体积感觉不一致\"],\"byMUK0\":[\"How is m/s related to km/h?\"],\"c1xWvb\":[\"双边公差和单位变化\"],\"c4_Sw-\":[\"暴露单个杯子单元的转换器应记录他们实施的杯子。用户值得这个脚注。如果您发布配方软件，请在内部以毫升为单位存储体积并本地化显示单位 - 不要存储不明确的杯子计数，就好像它们是通用常量一样。\"],\"c9aRYL\":[\"Weather, tires, and “feels like” speed\"],\"cAqE9n\":[\"这取决于哪个杯子。现代美国常见的营养标签法定杯子为 240 毫升。公制杯通常为 250 毫升。检查配方的来源，当准确性很重要时，更喜欢毫升测量。\"],\"cBtQp6\":[\"When in doubt, store seconds as integers (or milliseconds as integers) and format for humans at the edge. Integer bases avoid decimal-hour ambiguity entirely.\"],\"cGKcEV\":[\"连锁转换会加剧麻烦。每一步都带有二进制浮点数的英里→码→英尺→英寸→毫米→米比具有高精度系数的单英里→米转换要差。每跳都会重新舍入中间值。\"],\"cI0Ewh\":[\"一微米 (μm) 或微米等于 10⁻⁶ 米。生物学家用它来测量细胞大小；工程师用它来实现精细的制造公差。\"],\"cI6T12\":[\"数量不同，尺寸不同\"],\"cJ39x1\":[\"Measuring the box before you convert\"],\"cJ6qxU\":[\"Helicopter and ultralight communities sometimes speak mph in certain countries. Check the unit column on every performance table—especially when PDFs were scanned from mixed sources.\"],\"cKU2eT\":[\"华氏度将水的冰点设置为 32 °F，将水的沸点设置为 212 °F，因此这些点与 100 摄氏度之间存在 180 华氏度。 180/100 的比率恰好是 9/5，它出现在每个转换公式中。\"],\"cMpQRw\":[\"Convert millilitres (named Millimetre in this volume set) to litres for medicine cups, cocktail jiggers, and lab aliquots when labels use mL but dosing math wants litres. Divide millilitres by 1,000. Pharmacies and home brewing share this scale jump.\"],\"cMqnGa\":[\"An avoirdupois pound (lb) equals exactly 0.45359237 kilograms. It is the primary customary mass unit in the United States for body weight and commerce.\"],\"cNSioH\":[\"Flour’s bulk density is not water’s, and it changes with packing. Weigh flour in grams instead of trusting a water-based volume bridge.\"],\"cRdYDc\":[[\"0\"],\"面板\"],\"cSrZwS\":[\"停止将平方米与立方米混合。了解面积和体积之间的尺寸差异以及因混淆它们而产生的转换错误。\"],\"cWk5T0\":[\"Two numbers decide the invoice\"],\"cdkPWA\":[\"If mass is in kilograms, volume should be in cubic metres for SI density (kg/m³), or you may use g and cm³ (numerically equal to kg/L for the same substance). Mixing lb with litres without converting produces a density nobody else can use.\"],\"cg88uL\":[\"温标描述了物体的热度或冷度。摄氏温度和华氏温度主导着日常生活；开尔文是SI科学标度。使用精确的公式（而不是浮点快捷方式）在它们之间进行转换，并阅读每对页面上的常见问题解答。\"],\"cgJ3FK\":[\"立方米\"],\"cl4XpH\":[\"安全的转换习惯：尽可能通过SI基本单位进行转换（米、立方米、平方米），使用精确的法定系数（每英寸25.4毫米），并且仅在末尾舍入以进行显示。中间舍入是指小错误在经过几个步骤后变得昂贵。\"],\"cvG2i2\":[\"了解 Units Converters 如何收集和使用数据，包括 cookie 和 Google AdSense 广告。\"],\"cz1upw\":[\"一公顷约为 2.471 英亩。一英亩约等于 0.4047 公顷。\"],\"czpqzK\":[\"形状很重要：矩形、圆形和自由形状的池需要不同的几何估计。在您信任几何体积之后（而不是之前）转换单位。\"],\"d1Xi-y\":[\"我们不会出售您的个人信息。我们根据适当的协议与帮助我们运行网站的服务提供商（托管、表单电子邮件传送、分析以及 Google 等广告合作伙伴）共享数据。如果法律要求，我们可能会披露信息。\"],\"d3ukLV\":[\"我们和我们的合作伙伴使用 cookie 来分析网站流量、个性化内容并提供相关广告（例如 Google AdSense）。点击“接受全部”，即表示您同意我们使用 cookie，详情请参阅我们的<0>隐私政策</0>。\"],\"d5rA60\":[\"US pounds-only world\"],\"d7-Br2\":[\"玻尔半径 (a₀) 是氢原子基态下原子核与电子之间最可能的距离，约为 5.29 × 10-11 米。\"],\"dB4b_F\":[\"升\"],\"dBf9Sn\":[\"Using 100 seconds per minute is a decimal-time fantasy, not civil time. Decimal minutes (1.5 min) are 90 s, not 1 min 5 s. Pace notation 4:30 per km is minutes:seconds, already partly in seconds—parse before converting whole minutes only.\"],\"dEnNWn\":[\"Pilots talk about indicated airspeed (IAS), calibrated airspeed (CAS), true airspeed (TAS), and ground speed (GS). Those labels describe corrections for instrument error, altitude, and wind. Unit conversion (knots vs km/h) is separate: convert only after you know which airspeed type you are quoting.\"],\"dI2cXa\":[\"单位转换器、公制转换、英制到公制、长度转换器、温度转换器、面积转换器、体积转换器、科学计算器\"],\"dKXfGq\":[\"圆英寸是直径为一英寸的圆的面积，约为 0.785 平方英寸。电线和管道尺寸历来使用圆形测量。\"],\"dKdn_s\":[\"Convert days to Julian years when mission elapsed time, fossil age approximations, or simulation ticks in days should become year-scale figures using 365.25 d/yr. Divide days by 365.25. Astrophysics notebooks use this for tidy axes.\"],\"dLJTrx\":[\"Metres per second sometimes appear in research or metric-only instrument logs: 1 kn = 1.852 km/h = 0.514444… m/s. Prefer knots in operational marine/aviation communication unless a local procedure says otherwise.\"],\"dQPsJ-\":[\"国际团队应在启动文件中选择项目单位系统。项目中期的改造费用昂贵。在该决策中包括固件默认值、CAD 模板和供应商门户，而不仅仅是报告文本。\"],\"dVSJWu\":[\"If a density table uses g/cm³ and your volume is litres, remember 1 g/cm³ = 1 kg/L numerically for the same density value—still convert volume carefully (1 L = 1,000 cm³).\"],\"dWSM6x\":[\"2 hours of battery life claimed is 7,200 seconds of runtime budget. A 0.25-hour quiz is 900 seconds on an auto-submit timer.\"],\"dZF4X_\":[\"Do not treat weight-on-Earth vs mass distinctions here unless you are in an engineering mechanics context. Kitchen and shipping “weight” numbers plug into the triangle as mass values for practical purposes.\"],\"dcK-nG\":[\"Using ÷2.54 on an area value is wrong—that is a length factor. Skin lesion charts sometimes mix mm² and cm²; convert to one unit before switching to in². Do not confuse cm² with cc (cm³) used for volume.\"],\"de1NrB\":[\"使用摄氏度表示天气、烹饪和大多数国际工程交流。在当地实践和设备展示需要时使用华氏度。将开尔文用于科学方程、低温学以及绝对温度重要的任何环境。\"],\"df6Djb\":[\"Convert Celsius to Kelvin for science, gas laws, and color-temperature adjacent physics where absolute temperature is required. Chemistry labs and meteorology (potential temperature) use Kelvin. Add 273.15; the degree size matches Celsius.\"],\"dhq85t\":[\"Related length conversion: 1 international nautical mile = 1.852 km ≈ 1.15078 statute miles. If you convert speed but not distance—or the reverse—you invent a fake average speed.\"],\"dqUoQp\":[\"相关 \",[\"tQuantity\"],\" 兑换\"],\"drESMY\":[\"单位换算指南\"],\"dv9Spr\":[\"泳池化学标签假设您知道水量。如果您的注释上写的是加仑，但标签上写的是升——或者您的制造商引用的是立方米——您必须在乘以每体积剂量之前进行转换。\"],\"dyD1rw\":[\"Convert Julian years to days for astronomy, orbital periods, and light-travel teaching when a Julian year (exactly 365.25 days) is the definition in play. This matches the year length used in the light-year definition. Science writing prefers Julian years over vague “calendar years” for long spans.\"],\"e-mG_L\":[\"SI 前缀解释：从 Nano 到 Giga 及以上\"],\"e3-eZf\":[\"Convert inches to centimetres when a US tape measure, pipe schedule, or monitor size must match metric drawings, European furniture specs, or metric drill bits. Builders working from mixed plans and anyone ordering parts across regions use this constantly. The international inch is locked at 25.4 mm, so the centimetre result is exact.\"],\"e6-eIU\":[\"加工：毫米或英寸，两者都不具有权威性。民用土地：公顷或英亩加上占地面积平方米。化学成分：升和毫升，散装罐的单位为立方米。天体物理学：AU、秒差距、光年，具体取决于尺度。每个领域都已经解决了可读性问题——借用这些规范而不是发明一个私有系统。\"],\"e80Hl_\":[\"250 毫升的公制杯相当于四分之一升。按照惯例烹饪算术，十六个美式汤匙相当于一个美式杯，但在转换公制配方时要对照毫升进行验证。如有疑问，请先将所有内容转换为毫升，然后再转换回您拥有的器具。\"],\"e8G42j\":[\"120 mL of oil is ½ US cup (240 mL cup). A 15 mL vanilla note is 1 tablespoon, not a full cup—sanity-check small millilitre amounts before calling them cups.\"],\"e9VwqZ\":[\"物料清单长度可能是公制的，而包装体积是升的，运输重量是公斤的——仍然保持每个数量的转换隔离和标记。\"],\"eL51xG\":[\"确定数量。检查法律和合同要求。选择一个可读的幅度单位。确认观众认识它。通过具有精确系数的基本单位进行转换。循环显示一次。标记每个数字。如果您无法明确地标记图表轴，则单位选择尚未完成。\"],\"eLY2Y5\":[\"Large industrial batches may use metric tonnes (1 t = 1,000 kg) and cubic metres. Convert tonne → kg if your density table is in kg/m³.\"],\"eOYIJH\":[\"Boating: SOG, STW, and wind\"],\"eRwJXO\":[\"为什么使用我们的转换器？\"],\"eV62_R\":[[\"tQuantity\"],\" 转换器中心 | Units Converters\"],\"eXoNed\":[\"一升为 1 000 毫升，等于 1 000 立方厘米。该标识将配方语言与实验室语言联系起来：250 毫升的原料等于 250 立方厘米。一立方米等于 1000 升——适用于餐饮罐，不适用于蛋糕糊。\"],\"eZRsLU\":[\"测量一个简单的矩形水池\"],\"eZxOi9\":[\"Metronomes, frame rates, and sample rates link time to counts (beats per minute, frames per second). Convert the time unit first, then compute rates. Swapping BPM math with raw seconds without conversion produces unusable tempos.\"],\"e__Puw\":[\"730.5 days is 2 Julian years. A 10,000-day time series spans about 27.38 Julian years—handy for long climate annotations.\"],\"ea8fHF\":[\"从正确的摄氏度 ↔ 华氏度转换开始，然后根据烤箱的行为进行调整。烤箱温度计比网站上的第三位有效数字更有价值。\"],\"ebZquV\":[\"A gale at 20 m/s is 72 km/h. A sprinter near 10 m/s peaks around 36 km/h—useful when comparing to traffic speeds.\"],\"eh2HDo\":[\"Convert mph to km/h when US speed limits, bike computers, or sports radar guns must match metric signage and telemetry. Multiply mph by 1.609344. Touring cyclists and fleet managers localize reports this way.\"],\"ejVYRQ\":[\"从\"],\"ekpC3S\":[\"Trip math before economy math\"],\"emKkbf\":[\"Jet lag feelings track circadian clocks, not unit converters. Still, computing elapsed awake time uses duration units: hours since last sleep, minutes of layover.\"],\"enzGAL\":[\"Questions\"],\"eo96cV\":[\"10 stone is 63.5 kg. Someone at 13 st 7 lb is 13.5 stone ≈ 85.7 kg for a metric hospital chart.\"],\"euU_DG\":[\"由于光速在 SI 内是精确的，一旦年份约定确定，光年就会继承与米的精确关系。转换器应记录他们使用的年份定义；儒略年是常见的天文选择。\"],\"ezuV_5\":[\"Useful pairs to memorize for signs: 30 mph ≈ 48 km/h (urban); 50 mph ≈ 80 km/h; 60 mph ≈ 97 km/h; 70 mph ≈ 113 km/h; 80 mph ≈ 129 km/h. In the other direction: 50 km/h ≈ 31 mph; 80 km/h ≈ 50 mph; 100 km/h ≈ 62 mph; 120 km/h ≈ 75 mph; 130 km/h ≈ 81 mph.\"],\"ezxlLH\":[\"工程师应如何在不破坏公差的情况下转换单位——有效数字、精确系数、叠加和保持零件配合的文档习惯。\"],\"f0Z0HY\":[\"Convert mph to m/s for simulations, crash reconstruction inputs, and metric scientific models fed by US speed limits or radar guns. Divide mph by about 2.23694. Automotive research bridging NHTSA and SI tools needs this.\"],\"f0e0UX\":[\"提示：为了烘焙准确性，尽可能以克为单位称量原料，而不是转换杯子体积。\"],\"f25ZCJ\":[\"国际英尺正好等于 0.3048 米（12 英寸）。广泛应用于建筑、航空高度、美国日常测量等领域。\"],\"f7Spk7\":[\"Fossil and geological “millions of years” are long durations; the difference between Gregorian mean and Julian year is negligible next to dating uncertainty. Still, be consistent inside one paper or dataset.\"],\"fBIotp\":[\"Daylight saving shifts change civil labels by an hour on specific dates. The underlying duration of a movie does not become 59 minutes because DST started—though a civil midnight-to-midnight “day” can be 23 or 25 hours on transition dates.\"],\"fBeKh6\":[\"玻尔半径和相关原子单位出现在量子化学中。与 SI 友好表中的实验键长进行比较时，转换为米或皮米。如果您需要精确的再现性，请记录您的软件包假定的 CODATA 或软件默认玻尔半径。\"],\"fCtyuo\":[\"一十米（水坝）等于 10 米。它是一个 SI 倍数，偶尔用于测量和田径距离。\"],\"fD7PDR\":[\"温度添加偏移量：摄氏度 ↔ 开尔文使用 273.15。该常量也是二进制浮点数的近似十进制值。仿射转换特别敏感，因为添加不精确的偏移量会改变每个结果。\"],\"fOjnj0\":[\"Convert weeks to days for training plans, rental periods, and sprint schedules when coaches or leases say weeks but calendars show days. Multiply weeks by 7. Habit trackers and agile boards use this constantly.\"],\"fP8lzd\":[\"A 100 km/h highway limit is about 62 mph. A city 50 km/h zone is roughly 31 mph—close to many US 30 mph neighborhood limits.\"],\"fULs1C\":[\"健全性检查的规​​模：一块 0.2 英亩的郊区住宅地块是数百平方米，而不是数百公顷。列出的国家公园面积为 2,000 公顷，相当于数十平方公里——如果您的电子表格显示为 2,000 平方公里，那么您的数字就减少了一百。\"],\"fZ8nJ9\":[\"A minute equals 60 seconds. Everyday schedules, cooking, and sports use minutes as a convenient subdivision of the hour.\"],\"fdBctX\":[\"实用清单\"],\"fdf92S\":[\"每次转换都会通过使用Decimal.js算术精心定义的基本单位，因此作业、食谱、实验笔记和工程估计保持稳定，而不是因二进制浮点数学而漂移。选择一个类别，选择两个单位，然后阅读每页上的公式、表格和常见问题解答。\"],\"fizNPv\":[\"A reliable conversion workflow\"],\"fl0tsC\":[\"Mental anchors help day to day: 1 kg ≈ 2.2 lb; 5 kg ≈ 11 lb; 10 kg ≈ 22 lb; 20 kg ≈ 44 lb; 100 g ≈ 3.5 oz. Use anchors for sanity checks, then confirm important values with an exact conversion.\"],\"fpVPOq\":[\"一个杯子有多少毫升？\"],\"fpxm8o\":[\"英制加仑比美制加仑大多少？\"],\"fqw_2W\":[\"Rounding and reporting\"],\"frDzBE\":[\"一光日是光一天传播的距离，大约26万亿米。它连接着太阳系和附近的星际尺度。\"],\"g3AHNj\":[\"浏览化学、物理和材料科学中使用的埃姆、纳米、微米、皮米和相关科学长度单位。\"],\"g4ayGx\":[\"道路距离比物理更能说明民族习惯。大多数国家都以公里为单位；美国发布里程。跑步和骑行训练计划通常将 5K（公制品牌）与英里配速混合在一起。在比较锻炼或 GPS 导出时有意进行转换。\"],\"g5VCEs\":[\"皮升 (pL) 等于 10⁻12 升。微流体和喷墨打印可处理这种规模的体积。\"],\"g7fX22\":[\"您将遇到的土地面积单位\"],\"g7fndJ\":[\"Print or note dual totals for shared family recipes: “butter 113 g (4 oz).” Dual labels prevent weekend arguments and burnt cookies.\"],\"gBWzjf\":[\"Measure rooms, convert square metres and square feet, add waste, and order carpet or flooring without mixing length and area units.\"],\"gHnfdT\":[\"Water and many thin liquids have density near 1 g/mL, so millilitres and grams are roughly interchangeable for rough work. Oils, honey, and packed brown sugar are not. When accuracy matters, weigh.\"],\"gKEKVa\":[\"A 5-yard pass play covers 15 feet of field. Buying 4 yards of landscape fabric means 12 feet of linear run along a bed edge.\"],\"gQtgDe\":[\"热门 \",[\"tQuantity\"],\" 换算\"],\"gSCAaI\":[\"查看全部指南\"],\"gdLQsW\":[\"Stone appears in UK everyday speech (for example, 11 st 4 lb). If a form wants kilograms, convert the full stone-and-pounds value to pounds first, then to kilograms—or use a stone↔kilogram converter and add the leftover pounds carefully. Never paste “11.4” into a kilogram field when you meant 11 stone 4 pounds.\"],\"ggFmaC\":[\"Example: 2.5 L of a liquid with density 0.92 kg/L → mass = 2.5 × 0.92 = 2.3 kg. Convert to pounds only after: ≈ 5.07 lb.\"],\"gh-m_2\":[\"Density links mass and volume: density = mass / volume, mass = density × volume, volume = mass / density. Unit converters do not invent density for you—they make the mass and volume numbers consistent so the triangle arithmetic works.\"],\"giAfa6\":[\"Groceries, parcels, and kitchen intuition\"],\"glPh7x\":[\"Should I bake in grams or ounces?\"],\"gmK2O-\":[\"如何将房间的平方米换算为平方英尺？\"],\"gq0a46\":[\"将光年与年混淆会导致错误的年龄与距离的心理模型。 1亿光年外的星系不一定有1亿年的历史；我们看到的就是光线离开时的样子，这是一个不同的说法。\"],\"gs16X8\":[\"用清晰的上标或纯文本的 ASCII m^2 和 m^3 书写 m² 和 m³。数字旁边的 m 表示立方米，稍后会被误读。\"],\"gvQcOB\":[\"关于公制与英制、温标、SI前缀、烹饪转换等的原创解释。\"],\"gvz5ri\":[\"Example: 11 st 4 lb → (11 × 14) + 4 = 158 lb → about 71.67 kg. Round for the form’s rules (often whole kilograms in casual contexts, one decimal in clinics).\"],\"gw4hS2\":[\"摄氏度\"],\"gwLbLK\":[\"一立方分米 (dm³) 恰好等于一升。当强调体积为长度的立方时，国际单位制文本通常更喜欢这个名称。\"],\"h-EBW5\":[\"Is a Julian year the same as a leap year?\"],\"h0OSCv\":[\"Convert Celsius to Fahrenheit for cooking, weather apps, and HVAC setpoints when a recipe or forecast is metric but your oven or thermostat shows °F. Travelers and home bakers cross this daily. Use °F = °C × 9/5 + 32, not a simple scale factor.\"],\"h3fxEC\":[\"秒差距\"],\"h77AWn\":[\"两个系统，一个物理世界\"],\"h8z3Rj\":[\"哈勃长度\"],\"hBe0Mj\":[\"无错误前缀转换的习惯\"],\"hCu72k\":[\"该对使用相对于 \",[\"tQuantity\"],\" 基本单位的固定比例因子。计算器将这些因素与 Decimal.js 一起应用，因此链式转换保持稳定。\"],\"hCvW19\":[\"国家杯的定义也不同。在现代营养标签背景下，美国常见的习惯杯为 240 毫升（历史上通常将 8 盎司液体视为 236.588 毫升）。一些国家的公制杯为 250 毫升。使用错误的杯子会改变水合作用和质地。\"],\"hD0xms\":[\"音量比较混乱。美式杯、品脱和加仑与历史上英国帝国单位不同。一美制液体加仑约为 3.785 L；一英制加仑约为 4.546 升。食谱中只说杯子而未指定国家/地区，可以默默地改变面糊的水合作用和蛋糕结构。\"],\"hGX3gp\":[\"这种取消就是量纲分析：以跟踪代数变量的方式跟踪单位。如果英寸没有抵消，那么这个因素就颠倒了。将转换视为查找数字并希望错过此检查的学生 - 该检查可以捕获大多数家庭作业和电子表格错误。\"],\"hGctJQ\":[\"Create a line per room: raw L, raw W, unit, net area, waste %, order area, seller unit. Sum order areas. Compare to the installer’s takeoff. Differences larger than a few percent deserve a phone call before payment.\"],\"hKH6A_\":[\"Travel examples\"],\"hKSyqj\":[\"转换系数是等于 1 的比率，它改变单位标签而不改变物理量。书写 1 in = 2.54 cm 表示分数 (2.54 cm)/(1 in) 等于 1。将测量值乘以该分数，英寸就会被抵消，剩下厘米。\"],\"hKrxe3\":[\"我总是乘法，还是有时除法？\"],\"hLExwt\":[\"练习将相同的长度转换为 nm、μm、mm 和 m，直到小数点移位感到无聊为止。无聊在这里就是能力。\"],\"hMv49D\":[\"Convert mph to feet per second for ballistics, amusement-ride specs, and US engineering notes that keep length in feet. Multiply mph by 1.46667 (since 88 ft/s = 60 mph). Sports biomechanics in customary units use this.\"],\"hOIH5p\":[\"Convert hectares to acres when metric land registries, vineyard sizes, or park plans must be explained to an audience that uses acres. Multiply hectares by about 2.47105. Forestry and agronomy papers often need this for US readers.\"],\"hP8AC9\":[\"百升\"],\"hQbTDO\":[\"Rental cars may display the other unit, or both. Learn how to switch the cluster before you leave the airport road. Navigation apps usually localize speed limits, but a paper map or temporary work-zone sign might not match your mental default.\"],\"hRyrHm\":[\"Dividing by 2,000 gives short tons, not metric tonnes. Mixing net and gross pounds before converting still yields the wrong tonne figure for duties. Very small pound amounts become awkward tonne decimals—prefer kilograms under about 100 lb.\"],\"hTrZPu\":[\"Google AdSense and other advertising\"],\"hWhfUF\":[\"废物因子应该在转换之前还是之后添加？\"],\"hWwfWE\":[\"英亩和公顷测量土地面积。英亩英尺测量一英亩一英尺深的水量——灌溉和水库单位。共享词“acre”会欺骗新手，让他们将它们视为可互换的。\"],\"hYTkFF\":[\"基本单位及其重要性\"],\"hZIEfv\":[\"是的——两者都是面积单位。一平方公里等于 100 公顷，即约 247.1 英亩。通过平方米或公顷换算可以使算术清晰。\"],\"hZeuel\":[\"Convert square metres to square feet for apartments, offices, and flooring quotes when the listing is metric but US buyers think in sq ft. Real-estate portals and rug shops use this constantly. Multiply m² by about 10.7639.\"],\"h_RCCg\":[\"不要在没有明确切换数量的情况下将光年转换为秒并称之为时间。长度转换器应将结果标记为距离。如果您需要光行时间，请在距离除以光速后以年、日或秒为单位明确说明时间。\"],\"hcPFJ8\":[\"A time zone changes how we label the same instant (“15:00 UTC” vs “11:00 EDT”). A duration unit measures how much time elapses between two instants (3 hours, 180 minutes). Converting 3 hours to minutes never requires a time zone. Scheduling a call across zones never changes how long 3 hours lasts.\"],\"hdfyXd\":[\"Convert using Year (Julian) ↔ Day when you need transparent second-based duration. Document the choice in your notebook: “years mean Julian years (365.25 d).”\"],\"hgiis4\":[\"值得记住的确切关系\"],\"hi0pyt\":[\"不同的结构具有不同的尺度。细胞可以以微米为单位讨论，而膜、孔或波长可以以纳米为单位讨论。它们之间以 1 000 为因数进行转换。\"],\"hjFCpL\":[\"美国习惯的泳池计算器可能会输出加仑。仅使用体积转换器将加仑转换为升；不要将加仑视为升。\"],\"hlNybv\":[\"平方米和平方英尺通过米英尺系数的平方相关。这就是为什么同一房间的面积换算感觉比长度换算“更大”。\"],\"hn2nYh\":[\"Confusing mass with force in technical settings (lbf vs lb mass). Everyday baggage and body weight ignore that distinction; engineering specs may not. Read the symbol on the datasheet.\"],\"hpDhtW\":[\"面积与体积：常见错误以及如何避免它们\"],\"hr3apB\":[\"这个 \",[\"tFrom\"],\" 到 \",[\"tTo\"],\" 转换器免费吗？\"],\"hsK0za\":[\"A light-year is distance, not time—do not treat “4 years” as the converted value. Parsecs and astronomical units are different; convert ly→km, do not mix AU factors casually. Rounding to “9.5 trillion km” is fine for talk, not for precise ephemerides.\"],\"htIPPL\":[\"Adding leftover inches twice—once inside the feet field and again after converting—double-counts. Decimal feet (6.5 ft) become 78 inches, not 6 ft 5 in (which is 77 inches). Confirm whether the source already mixed feet and inches in one string.\"],\"htp0ic\":[\"织物和运动场历史上都使用码。按照国际定义，一码为 0.9144 m。当您使用国际单位时，这种精确性使得转换值得信赖。\"],\"huPTBE\":[\"在摄氏度和华氏度之间转换烤箱设置，了解风扇辅助调整，并保持食谱在各个地区的可靠性。\"],\"huSEaq\":[\"我什么时候应该更喜欢 \",[\"tFrom\"],\" 而不是 \",[\"tTo\"],\"？\"],\"hv1-eY\":[\"Treating litres and m³ as interchangeable off-by-1000 errors. Rainfall in mm over an area yields litres or m³ only after multiplying by surface area—do not convert mm rain as if it were litres. Keep oil barrels and US gallons out of this SI-only path unless converted first.\"],\"hw26PX\":[\"美国将国际英尺与地理空间背景下的测量英尺区分开来。在大地块上，每英尺的微小差异都是可以测量的。现代实践正在向国际足部靠拢，但旧的平台可能嵌入了测量足部的几何形状。\"],\"hxO7c9\":[\"Our mile ↔ kilometre guides cover distance; this guide focuses on the speed pair. You will often need both pages open when building an itinerary across borders.\"],\"i0qMbr\":[\"首页\"],\"i2oK0q\":[\"A 10 ha orchard is about 24.7 acres. A city park of 2.5 ha is roughly 6.2 acres—useful on bilingual trail signs.\"],\"i9kg_n\":[\"Last updated: 21 July 2026\"],\"iBcaae\":[\"Planning ETA when distance units also flip\"],\"iDGO1l\":[\"Disclaimer\"],\"iEnWPy\":[\"Kilograms and pounds both describe mass (weight under ordinary gravity). A suitcase that tips a scale at 23 kg is the same object whether a US tag says about 50.7 lb. The physics does not change; the number and the unit do. Confusion starts when people treat the numbers as interchangeable, round too early, or mix stone, pounds, and kilograms on one form.\"],\"iUyBUX\":[\"Dividing by 10 instead of 12 is a common mental slip. Leaving a remainder as a decimal foot (5.5 ft) is fine for calculation, but suppliers often want 5 ft 6 in—do not call 0.5 ft “5 inches.” Also, US survey feet differ slightly from the international foot; this converter uses the international definition.\"],\"iVMakV\":[\"以每加仑英里数为单位的燃油经济性数字取决于您所指的加仑数。将美国 mpg 标签与英国 mpg 数据进行比较（不换算加仑）会产生约 20% 的误导。跨境比较时首选 L/100 公里，然后仅在本地讲故事时进行转换。\"],\"i_EFha\":[\"Spreadsheets store datetimes as serial numbers in a timezone-agnostic cell unless you add conventions. Duration cells formatted as time may wrap at 24 hours. Prefer an integer “total minutes” column for long spans.\"],\"icHr4X\":[\"Cubic metres appear in industrial fuel gas, not petrol stations (1 m³ = 1,000 L). Convert bulk deliveries carefully before computing fleet economy.\"],\"ii0wT3\":[\"How do I convert min/km to km/h?\"],\"im\":[\"im\"],\"imSxXi\":[\"最后，将纸上的真实实验室值转换为仪器显示的单位。这种端到端的习惯正是专业工作所需要的。如果转换后的值低于仪器的分辨率，请更改测量计划 - 不要假装转换创建了可观察性。\"],\"irbsSh\":[\"Confusing this volume unit with length millimetres will derail DIY projects—here “Millimetre” means millilitre (mL). Dropping or adding three zeros is the usual arithmetic bug. Do not equate mL with grams unless density is 1 g/mL (true for water near room temperature, not for syrups or oils).\"],\"itztKm\":[\"许多计算器使用二进制浮点数，无法准确表示每个小数。我们的转换器使用任意精度的小数，因此长转换链保持稳定。微小的差异通常来自舍入显示，而不是来自不同的物理因素。\"],\"j22KL0\":[\"因为公斤前缀将基础长度乘以 1 000，而面积则乘以该因子的平方：1 000 × 1 000 = 1 000 000。面积和体积始终使用平方或立方前缀因子。\"],\"j4YCMy\":[\"食谱旅行；烤箱刻度盘不\"],\"j5HJId\":[\"糖果、肉类和探针温度\"],\"j7LB4c\":[\"残留烹饪意味着食物在取出后温度会升高。单位转换不会改变物理原理；时间和休息仍然很重要。\"],\"j7Qadg\":[\"隐私政策 | Units Converters\"],\"jCnKcR\":[\"我们的平台已完全翻译为英语、西班牙语、葡萄牙语、法语、德语、日语、中文、繁体中文、韩语、俄语、意大利语、印度尼西亚语、阿拉伯语、波兰语、荷兰语、土耳其语和印地语，为全球用户提供服务。\"],\"jD3OhI\":[\"They are not a substitute for certified metrology, calibrated instruments, or professional engineering sign-off. Always verify critical values against an authoritative standard for your industry before manufacturing, dosing, filing, or shipping decisions.\"],\"jDCGUq\":[\"平方分米\"],\"jFas-2\":[\"A 6 ft 1 in doorway rough opening is 185.4 cm—compare that to a 200 cm metric door slab with trim. A 5-foot Christmas tree is 152.4 cm for European height labels.\"],\"jFmHCW\":[\"安德斯·摄氏度提出了水的冰点和沸点之间的一百度范围。现代方向（0 表示冻结，100 表示沸腾）成为日常的公制温标。\"],\"jG0gYt\":[\"Some civil documents and metric-country outreach use km/h. Convert knots → km/h by multiplying by 1.852. Example: 90 kt ≈ 166.7 km/h. For mph, multiply knots by about 1.15078.\"],\"jIT08R\":[\"报告比仪器分辨率更精细的转换值是虚假精度。转换不应发明测量从未提供的数字。\"],\"jKwuBE\":[\"身高换算：英尺、英寸和厘米\"],\"jLnoAK\":[\"A 2 t palletized load is about 4,409 lb—check a forklift rated in pounds. A 0.5 t delivery is roughly 1,102 lb for a US pickup payload chart.\"],\"jMCjxK\":[\"遵循表格。如果两者都允许，则整数厘米通常比十进制米更不容易出错。\"],\"jN574V\":[\"数量选项卡\"],\"jPGJ22\":[\"Confusing metric tonnes with US short tons (2,000 lb) or UK long tons (2,240 lb). A “ton” in casual US speech is usually the short ton, ~9% lighter than a tonne. Crane limits may be in tons-force—confirm mass vs force.\"],\"jQG1ak\":[\"我们可能会使用 PostHog 收集匿名或假名的使用分析（例如查看的页面和基本设备信息），以便我们改进 Units Converters。分析 cookie 和相关处理仅在您接受非必要 cookie 后运行。详情请参阅我们的隐私政策。您可以随时通过页脚中的 Cookie 设置拒绝 Cookie。\"],\"jRla6K\":[\"室内米和英尺\"],\"jXStA4\":[\"使用准确的定义：1 英寸 = 25.4 毫米。以完全精度进行转换，然后舍入一次以进行绘图。多步骤电子表格中的中间舍入是供应商之间神秘的 0.01 毫米分歧的常见根源。如果可能，将转换单元格锁定为公式，而不是粘贴的值。\"],\"jY7wnv\":[\"Convert feet to centimetres for height charts, ski length, and doorway clearances when the measurement started on a US tape in feet and inches. Medical growth charts outside the US and online clothing filters often want centimetres. Multiply feet by 30.48.\"],\"jYRIYX\":[\"当部件在单元更改后未通过检查时，请在审核操作员之前审核转换。许多逃避都是计量性的，而不是动机性的。每当图纸更改单位系统时，请在首件检查时保留简短的转换验证优惠券。\"],\"jbG0D6\":[\"Actual weight: kilograms and pounds\"],\"jbq7j2\":[\"拒绝\"],\"jcIkoh\":[\"为什么来回转换会改变我的号码？\"],\"jcuMyh\":[\"One international avoirdupois pound equals exactly 0.45359237 kg by definition. That means 1 kg is about 2.2046226218 lb. For luggage and gym work, two or three decimal places on the conversion factor are enough; for legal trade and shipping manifests, use the exact factor and round only at the end.\"],\"jf9uJ_\":[\"我应该将英寸的毫米当量四舍五入到毫米吗？\"],\"jfC_xh\":[\"接触\"],\"jgY-wY\":[\"您所做的几乎每次测量都描述相同的物理量（距离、容量或表面），但标签因国家/地区和行业而异。公制（SI 及其日常表亲）以 10 的幂为单位构建单位。帝国和美国的习惯制度源于贸易、手工艺和土地实践，因此它们的比率是历史的而不是小数的。\"],\"jkLcBQ\":[\"Partial fill-ups and forgotten top-ups ruin the dataset faster than unit mistakes. Start economy tests from full-to-full when you can.\"],\"jlWgCH\":[\"回复联系和反馈消息\"],\"jp75Pk\":[\"Average speed = distance / time. Convert distance and speed into one system before judging whether a tank was “mostly highway.” A 70 mph cruise is about 113 km/h—not a European “70” zone.\"],\"jqxx6s\":[\"一眼望去九个数量级\"],\"js24hj\":[\"以声明的精度进行比较，使用十进制字符串相等，或断言绝对和相对容差。避免在几个算术步骤之后期望精确的二进制相等。\"],\"jt6Jb2\":[\"避免在没有标签的情况下将埃姆和纳米混合在同一列中。无声的单位变化是绘图错误的常见来源。\"],\"jtUEtX\":[\"日常长度：米、英尺和英里\"],\"jtoIN9\":[\"Year (Julian)\"],\"juCzXY\":[\"Convert avoirdupois ounces to grams for metric baking, lab sample limits, and nutrition labels when the US package speaks in ounces. Multiply oz by 28.349523125. Letter mail and spice jars often need grams for customs forms.\"],\"jwjswb\":[\"皮米和飞米出现在核和精密原子环境中。在它们之间进行选择是为了可读性和社区惯例，而不是不同的物理原理。\"],\"jzLhZN\":[\"Ångström\"],\"k03yoY\":[\"A number on a white sign means nothing until you know whether it is mph or km/h. Driving 100 in a 100 km/h zone is not the same as driving 100 in a 100 mph zone—the second case is roughly 161 km/h. Tourists who “just match the number” cause genuine danger.\"],\"k4oq1n\":[\"不。一英亩英尺是一个体积：覆盖一英亩至一英尺深的水体积。英亩仅测量面积。\"],\"k521Wm\":[\"Applying only the Celsius↔Fahrenheit transform to a Kelvin number without the absolute offset fails. Absolute zero is 0 K (−459.67 °F), not −273 °F. Keep significant figures: converting 300 K to 80.33 °F is more honest than “80 °F” for lab work.\"],\"k6pR01\":[\"精确性、不确定性和诚实性\"],\"k9wF1o\":[\"Software and spreadsheet pitfalls\"],\"kGqN6S\":[\"在公里和英里之间转换道路和步道距离，阅读不同国家的地图，并在没有单位混乱的情况下确定旅行的节奏。\"],\"kK4fmb\":[\"Use square feet to square metres for EU building permits, metric tile boxes, and international property comparisons when the plan started in US customary units. Architects exporting CAD from imperial templates need m². Divide sq ft by 10.7639, or multiply by 0.092903.\"],\"kKLZaC\":[\"在转换器中输入一个值。我们通过\",[\"tQuantity\"],\"基本单位与Decimal.js算术转换，然后将结果显示在\",[\"tTo\"],\"中。\"],\"kKadcT\":[\"混凝土板需要体积，而不仅仅是建筑面积。一块 0.1 m 厚的 10 m² 板相当于 1 m³ 混凝土（扣除浪费因素）。因为地板面积为 10 平方米而订购 10 立方米是一种昂贵的符号混淆。\"],\"kKqcNS\":[\"Density, Mass, and Volume: The Triangle\"],\"kLRjW4\":[\"Knot\"],\"kLY6ug\":[\"Common mistakes to avoid\"],\"kN2EC5\":[\"您可能乘以 0.3048 一次，而不是 0.3048 的平方（大约 0.0929）。面积换算必须乘以长度系数。\"],\"kNn4oH\":[\"更改转换器中的输入以检查作业、食谱、工程估算或实验笔记。结果会在您键入时更新，并保持完整的十进制精度，而不是二进制浮点漂移。\"],\"kS4T08\":[\"是的。一微米等于 1000 纳米。两者分别等于 10⁻⁶ m 和 10⁻⁹ m × 1 000。\"],\"kVZkMb\":[\"埃姆有多少纳米？\"],\"kW9R7H\":[\"Idle time burns fuel with zero distance, wrecking L/100 km. Duration units (hours of idle) explain the hit; speed converters do not erase it.\"],\"kYatTD\":[\"规划清单\"],\"kZNgFa\":[\"如何快速将\",[\"tFrom\"],\"转换为\",[\"tTo\"],\"？\"],\"k_M3_l\":[\"Practical guidance\"],\"kaDoU6\":[\"Calling 25 mm “one inch” is off by 1.6%—enough to mis-drill a clearance hole. Do not mix calliper readings in mm with nominal inch pipe sizes (½″ pipe is not 12.7 mm inside diameter). Leading zeros on drawings (0.5 mm vs 0.5 in) are easy to swap when copying values.\"],\"kb02-X\":[\"Réaumur、Rankine、Delisle 和其他人也在档案和专业工程领域留下了痕迹（Rankine 仍然以绝对华氏大小的比例出现在一些美国热力学教学中）。\"],\"kcla1l\":[\"Convert km/h to mph for road speed limits, car dashboards, and running pace talk when traveling between metric and US/UK customary roads. Divide km/h by 1.609344. Rental cars and GPS unit settings drive this daily.\"],\"kf6wCX\":[\"Kilometre per hour\"],\"kh62N-\":[\"医疗和工业警报必须使用正确的刻度以及正确的差异与绝对读数概念。恒温器设置错误 5 °F 与 5 °C 的安全裕度截然不同。\"],\"kkV0vn\":[\"一平方纳米 (nm2) 等于 10⁻18 平方米。它测量纳米技术和材料科学中的超小表面积。\"],\"ku__5b\":[\"Second\"],\"kv_z5g\":[\"Converting Julian years to days and hours\"],\"kyFZfG\":[\"Browse related tools on Amazon\"],\"l-mD0s\":[\"We aim to reply within 2 business days.\"],\"l4SV8N\":[\"平方毫米\"],\"l8CY95\":[\"Convert metric tablespoons to teaspoons when scaling dressings, baking powder, and medicine-style kitchen doses. In the metric set used here, 1 tablespoon = 3 teaspoons (15 mL vs 5 mL). Recipe scaling and substitution both need this.\"],\"l8lOET\":[\"Avoirdupois ounces are the everyday food ounce: 1 oz = 28.349523125 g exactly by the international pound definition. Troy ounces are for precious metals—ignore them in the kitchen.\"],\"l9wI00\":[\"Speed\"],\"lEpJBm\":[\"Airspeed Units Explained\"],\"lGyviH\":[\"L/100 km ≈ (litres used × 100) / kilometres driven. km/L ≈ kilometres / litres. Those formulas only work after unit cleanup.\"],\"lHqUuu\":[\"Workflow for a border-crossing day\"],\"lN0rk8\":[\"泽米特\"],\"lO2fPP\":[\"Writing “mL” on a value still in litres by habit (1 L ≠ 1 mL). Baby formula and concentrate ratios break if you convert volume but keep the powder mass wrong. Carbonated beverage “litres” on bottles are liquid volume, not dissolved-gas volume.\"],\"lO46mR\":[\"A 42.195 km marathon is 26.219 miles—the classic race distance. A 120 km drive is about 74.6 miles; at 8 L/100 km that trip burns roughly the same fuel as about 29.4 mpg over those miles.\"],\"lOb2gC\":[\"单位换算的工作原理：因子、基础和量纲分析\"],\"lPcBzK\":[\"有理算术将因子存储为整数的分数。如果 1 英寸 = 127/5000 米（因为 25.4 毫米 = 127/5000 米），乘法可以完全抵消。有理数对于纯尺度转换来说是理想的；偏移仍然需要仔细处理温度。\"],\"lQHX85\":[\"正好 1,000 升。立方米和升在日常公制体积中通过十的幂联系起来。\"],\"lR7zqG\":[\"在每个草图尺寸上写下单位。单纯的“12 × 15”在边界上是模糊的。首选“12 ft × 15 ft”或“3.66 m × 4.57 m”。\"],\"lS-JWL\":[\"未找到分类\"],\"lSDK4y\":[\"一光小时是光一小时传播的距离，约10.79亿公里。它的跨越距离与外行星轨道相当。\"],\"lSqMra\":[\"Convert litres to millilitres when a metric recipe, IV bag scale, or fuel additive dose starts in litres but syringes and measuring cups read mL. Multiply litres by 1,000. Clinical and culinary workflows both need this.\"],\"lXNujI\":[\"房间地板面积：平方米和平方英尺\"],\"lYWHq0\":[\"Units Converters is developed and maintained by <0>Voyager Tecnologias LTDA</0>, a Brazilian technology company. We are a small team passionate about building high-quality digital utilities that solve everyday problems with technical excellence.\"],\"lb2_mR\":[\"蜂蜜、糖浆和糖蜜都是粘稠的。它们紧贴在量杯上，因此重量或柔性硅胶杯可以提高准确性。在勺子上轻轻涂油可以帮助粘性转移，而不会改变体积。\"],\"lbPAS2\":[\"How do I convert room m² to ft² for carpet?\"],\"ldSUNW\":[\"英亩英尺是面积单位吗\"],\"lft-xy\":[\"总部设在巴西\"],\"lmGjUl\":[\"Can I order carpet from length × width in mixed units?\"],\"lnd6lS\":[\"从头开始重试\"],\"lqwHxU\":[\"运动场和球场都有标准化的尺寸——国际上通常以米为单位发布，即使球迷们仍然以码或英尺为单位。检查管理机构的规则集以了解确切的数字。\"],\"lstGkS\":[\"Gregorian mean year vs Julian year\"],\"luqVOM\":[\"Stone Weight: UK Speech vs US Scales\"],\"lv-5mm\":[\"综合类别\"],\"lzhCyk\":[\"No. Ground speed includes wind. You can convert either into km/h or mph, but they remain different physical quantities.\"],\"lzhjeI\":[\"在写作中，介绍一个不熟悉的小单位，进行一次SI比较：80 nm（0.08 µm）孔径。读者比裸露的纳米数字更好地记住了这种比较。重复图片标题中的比较，读者在时间压力下通常首先查看图片标题。\"],\"m1gvGN\":[\"Use kilogram/gram and litre/cubic metre converters to sanitize inputs; look up density from a material datasheet, not from wishful arithmetic.\"],\"m7z962\":[\"经典的DIY和园艺错误\"],\"m9jwyN\":[\"清晰的公式、定点和实用建议，用于在摄氏度、华氏度和开尔文之间进行转换，而无需混合偏移和比例因子。\"],\"mB2h1B\":[\"一吉米 (Gm) 等于十亿米。天文学家有时用它来测量太阳系内部的距离。\"],\"mB4cv6\":[\"To km/h: multiply knots by 1.852. To mph: multiply knots by 1.150779448 (approximately). Reverse: divide km/h by 1.852 to get knots. Use a converter when filing plans or writing procedures; use 1.85 as a glance factor only for casual talk.\"],\"mCPa7u\":[\"News may say “gusts of 80 mph” while METARs use knots. Re-convert from the authoritative METAR when briefing. Dual-unit sticky notes help in mixed classrooms.\"],\"mD6REY\":[\"请提供尽可能详细的信息...\"],\"mGW1fQ\":[\"立方毫米\"],\"mJN-IA\":[\"Before you convert anything, write down three facts: outer length, width, and height (with units), scale weight (with units), and the carrier’s dimensional divisor and rounding rules from the rate card you are using today—not a blog post from five years ago.\"],\"mM9lqj\":[\"Litres dominate most of the world. US pumps use US gallons (≈ 3.785 L). Confusing imperial gallons (≈ 4.546 L) with US gallons skews mpg badly.\"],\"mSSp5m\":[\"选择任何单位以打开转换器。您可以在下一个屏幕上更改目标单位。\"],\"mV4g_E\":[\"降雨量通常以集水区的深度（毫米）来讨论。雨量等于面积×深度。洪水规划依赖于这种关系；单位换算只是水文学中的一个步骤。\"],\"mWuBvQ\":[\"开尔文很少出现在消费者食谱上，但出现在烹饪科学文本中。了解 1 °C 变化等于 1 K 变化有助于阅读这些图表。\"],\"maGuXr\":[\"Write units on the sketch: “3.20 m × 4.10 m” or “10 ft 6 in × 13 ft 5 in.” Bare numbers cause expensive callbacks.\"],\"maasmB\":[\"Treating metres and yards as equal is a ~9% error—enough to short a fabric order. Do not confuse square metres with square yards when buying sod or carpet; convert area separately. Survey “yards” in older deeds may not match the international yard.\"],\"mfGHa3\":[\"一十升 (daL) 等于 10 升。饮料和农业散装液体有时使用十升。\"],\"mhNQVa\":[\"当二进制浮点仍然没问题时\"],\"miLeGg\":[\"350 °F 转换为约 177 °C，在家庭食谱中通常四舍五入为 180 °C。确认您的烤箱和食谱风格。\"],\"mj_Y0E\":[\"An avoirdupois ounce (oz) equals exactly 0.028349523125 kilograms, or one-sixteenth of a pound. Food packaging and postal scales commonly use ounces.\"],\"mm6uBX\":[\"明智地使用转换器\"],\"mmn5SI\":[\"Shipping Weight vs Volume Weight\"],\"mn1m80\":[\"比较光年、天文单位和秒差距\"],\"mnB7hj\":[\"日常技术工作中常见的前缀包括毫 (10⁻3)、厘 (10⁻2)、德西 (10⁻1)、德卡 (101)、百 (102) 和千 (103)。科学和工程添加了微米 (10⁻⁶)、纳米 (10⁻⁹)、皮 (10⁻12)、兆 (10⁶)、千兆 (10⁹) 等。\"],\"mnkrjr\":[\"约克托米特\"],\"mqI7zL\":[\"Almost never in everyday US forms or scales. Convert stone to pounds or kilograms when talking to US audiences or software.\"],\"mugzPe\":[\"将摄氏度乘以 1.8 而不加 32 将产生错误的华氏度读数。添加 273 而不是 273.15 会引入 0.15 K 偏差——对于天气影响可以忽略不计，对于仔细的实验​​室工作来说是不可接受的。\"],\"mwQa3n\":[\"Units Converters\",[\"0\"]],\"mzr5MT\":[\"一公顷有多少英亩？\"],\"n0xVX9\":[\"在国际上共享高度时，更喜欢厘米加上可选的英尺和英寸光泽度。双重标签可防止电子邮件和聊天中的无声单位假设。\"],\"n4OVTp\":[\"开尔文是用度数符号写的吗？\"],\"n4_i-l\":[\"Are fluid ounces the same as ounces on a scale?\"],\"n5xKCi\":[\"Operational aviation prefers knots worldwide for airspeeds and winds. Popular articles may convert to mph or km/h for readers. Meteorology sometimes uses metres per second for wind. Know your audience before you change the number.\"],\"n6b2Ae\":[\"现代华氏度是通过精确转换为摄氏度/开尔文来定义的，而不是通过华氏度最初的参考实验来定义的——计量学继续发展，但名称保留了下来。当你今天转换时，你使用的是现代定义，而不是重建十八世纪的盐水实验。\"],\"nA8gP-\":[\"平方微米\"],\"nAMgRH\":[\"One avoirdupois ounce is exactly 28.349523125 grams. For cooking estimates, many people use 28 g ≈ 1 oz.\"],\"nCUa6i\":[\"Conversion accuracy\"],\"nFYWRe\":[\"在制造业中，混合图纸是一种典型的故障模式：以毫米为单位设计的零件，以英寸为单位切割的夹具，以及悄悄超出预算的公差堆栈。为项目文件选择一个系统并仅在边界处进行转换。\"],\"nH0ra2\":[\"Convert milligrams to grams for medicine, caffeine content, and analytical chemistry when labels use mg but balances or protocols use grams. Divide mg by 1,000. Pharmacy math depends on this shift.\"],\"nImEQv\":[\"Grain\"],\"nKTa7y\":[\"我们找不到那些特定的单位。尝试我们的默认转换器。\"],\"nO5M1g\":[\"Our platform is fully translated into English, Spanish, and Portuguese to serve users worldwide.\"],\"nS4cHi\":[\"习惯高度：英尺和英寸\"],\"nSyIq6\":[\"Workflow worth repeating\"],\"nTCHv2\":[\"Writing 90 minutes as 1.90 hours is wrong—90/60 = 1.5 h. Movie runtimes in minutes convert cleanly; including trailers is a content choice, not a unit issue. Keep overtime rules (e.g. round to next 15 min) separate from pure conversion.\"],\"nWNuiZ\":[\"公制高度：厘米与米\"],\"nkGGs4\":[\"以升或立方米为单位估算游泳池体积，在单位之间进行转换，并根据与体积单位不一致的标签来添加化学品。\"],\"nn2wRS\":[\"A millisecond (ms) equals one thousandth of a second. Computing latency, photography shutter speeds, and sports timing often use milliseconds.\"],\"nnO6cY\":[\"高精度转换\"],\"nqMrU_\":[\"One kilogram equals about 2.2046226218 avoirdupois pounds. For quick estimates, use 2.2 lb per kg, then refine with an exact converter when limits are tight.\"],\"nr1Gem\":[\"By the Units Converters editorial team · \",[\"0\"]],\"nrZeXM\":[\"Medical and passport-adjacent forms\"],\"ntGXPK\":[\"提示：不要将地板平方米与油漆升数混淆——面积和体积是不同的数量类型。仅在单个系统中的长×宽后转换面积。\"],\"nu-obh\":[\"Speed through water (STW) and speed over ground (SOG) can differ because of current. Instruments may show knots for both. When you convert to km/h for a guest display, label which speed you converted—current-adjusted SOG is what gets you to the marina on time.\"],\"nuviZq\":[\"我应该以同样的方式转换速度限制吗？\"],\"nvyMN9\":[\"大麦粒是一种古老的英国长度单位，等于三分之一英寸。它在历史上支撑了鞋子尺码系统。\"],\"nwtY4N\":[\"出了点问题\"],\"nzwr2B\":[\"立方英寻\"],\"o-B_nB\":[\"Pages may show third-party advertisements (such as Google AdSense) or affiliate links after you consent to cookies where required. We do not control advertiser content. Affiliate relationships — if any — do not change our editorial duty to describe units and conversions accurately.\"],\"o-zndZ\":[\"Car stickers from different markets may already be converted—or may use different test cycles entirely. Unit conversion cannot fix a cycle mismatch (WLTP vs older cycles).\"],\"o0eWtS\":[\"Speed limits are unit limits\"],\"o3MK4I\":[\"Month (Average)\"],\"o8L3mE\":[\"对于公共通信，选择一个前缀，使前导数字保持在大约 0.1 到 999 之间。说 0.003 公里是合法的，但不友好；说 0.003 公里是合法的，但不友好； 3m更清晰。\"],\"o9BMZQ\":[\"Tile and plank sold in boxes list coverage area per box. Divide required area (with waste) by coverage per box in the same unit, then round up whole boxes.\"],\"oDIaEX\":[\"Carat\"],\"oDacDe\":[\"0.25 g of caffeine powder is 250 mg—matching many anhydrous caffeine capsule labels. A 1.5 g electrolyte packet is 1,500 mg of total salts before splitting components.\"],\"oE-H8K\":[\"温度\"],\"oGQWbj\":[\"Decimal hours vs hours and minutes\"],\"oGSy2V\":[\"Using ×2.2 is rough. Mixing m/s wind with mph storm reports without conversion makes Category talk inconsistent. Vertical speed in m/s (sink rate) is not the same conversation as horizontal mph.\"],\"oHNOBu\":[\"Convert nanometres to metres in optics, semiconductor process notes, and wavelength tables where light or film thickness is given in nm but equations expect metres (SI base). Physics homework and thin-film coating specs use this constantly. One nanometre is 10⁻⁹ m.\"],\"oIk5BZ\":[\"我应该按体积还是按重量换算面粉？\"],\"oLt41p\":[\"如果您只记得一个习惯，请记住这一点：使用完整的仿射公式转换读数；单独使用比例因子转换差异。在任何显示与协议文件不同比例的实验室烤箱或环境室附近打印该句子。\"],\"oM9mkO\":[\"For public schedules, whole minutes are usually enough. For lab notebooks, keep enough digits to match instrument resolution. Matching precision to purpose beats always showing six decimals.\"],\"oOMfxN\":[\"Flight-planning tools can switch display units. Before a cross-country lesson or sim session, verify the unit field. A silent switch from knots to mph changes every performance number you memorized.\"],\"oOvcbq\":[\"软件、PLM 和双重尺寸标注\"],\"oP7_xG\":[\"数量的平方和立方会使错误变得更严重。面积和体积会乘以长度比例，因此当您展开 (1+ε)ⁿ 时，长度上的微小相对误差相对于面积或体积而言会变得大两倍或三倍。\"],\"oPY_HN\":[\"平方米 (m²) 是 SI 导出的面积单位。全世界的财产列表、科学和工程都使用它作为基础面积单位。\"],\"oTk8W2\":[\"Shipping and cooking crossovers\"],\"oV7zz2\":[\"秒差距和光年哪个更大？\"],\"oXH11m\":[\"Group classes calling “level 8.0” without units are ambiguous across equipment. Ask “km/h or mph?” once and save the workout.\"],\"oYbVXt\":[\"始终遵循产品标签和当地法规。在线转换器帮助单位；它们不能取代商业泳池的水质测试或专业建议。\"],\"o_CECW\":[\"一光年是光在真空中在儒略年中传播的距离。尽管有“年”这个词，但它是一个长度单位，而不是时间单位。说一颗恒星距离我们 4 光年意味着它的光大约需要四年才能到达我们——而路径长度就是那么多光年。\"],\"o_Q5cU\":[[\"tQuantity\"],\"转换器\"],\"oaBQIn\":[\"比例模型会有所帮助：如果地球与太阳的距离为 1 厘米，那么一光年就变成了一个尴尬的大教室长度——这本身就说明了为什么天文学家需要大单位。\"],\"obIRob\":[\"When two people share numbers (coach and athlete, shipper and warehouse), agree on one unit for the shared log. Publish a dual label only at the interface (airport sign, product page), not inside every intermediate calculation.\"],\"ocU2yl\":[\"节省退货的字段提示\"],\"oe296U\":[\"Pilots quote indicated, calibrated, true, and ground speed—often in knots. Those types already differ by instrument and atmosphere effects; unit conversion is a separate step. Convert only when talking to audiences that expect km/h or mph, and name which airspeed type you mean.\"],\"oeEKDx\":[\"Use our second ↔ minute ↔ hour tools for clean steps, and keep a notepad line with units on every intermediate value when the calculation feeds payroll, dosing intervals, or race results.\"],\"oeiUr5\":[\"Tip: convert through kilograms when mixing metric and customary weight. Stone is 14 pounds—do not paste decimal stone into a kilogram form. Kitchen ounces are avoirdupois, not troy.\"],\"ofhKFN\":[\"Sanity-check with a dual display: show chargeable kilograms and pounds on the packing slip. Dual labels catch unit bugs when US and EU sites share one catalogue.\"],\"ofldSs\":[\"面积\"],\"ohh-Ad\":[\"SI 是正式的国际单位制。日常公制语言包括 SI 单位以及可与 SI 一起使用的方便单位，例如升和公顷。对于技术工作，首选 SI 基本单位和派生单位，并明确说明任何非 SI 公制单位。\"],\"ojeWyk\":[\"An M6 bolt shank is 6 mm across, about 0.236 inches—too large for a ¼″ (0.250 in) clearance if you need a snug fit, but fine for a ¼″ clearance hole with a little play. A 35 mm camera lens is roughly 1.38 inches in focal length naming conversations.\"],\"omr0Cf\":[\"使用我们的高精度 \",[\"tQuantity\"],\" 转换器轻松将 \",[\"tFrom\"],\" 转换为 \",[\"tTo\"],\"。为学生和工程师提供的免费在线工具。\"],\"oms5-c\":[\"一平方英尺约等于 0.0929 平方米。美国的房地产、地板和建筑通常使用平方英尺。\"],\"onzwZs\":[\"单元测试应明确包括面积和体积情况。仅靠线性测试无法发现缺失的功率。\"],\"oobEHZ\":[\"如果您跨境工作，或者遵循来自不同国家的配方、建筑计划和产品规格，您需要流畅的转换，而不是对某一系统的忠诚度。本指南的其余部分展示了每个系统的优点以及可以防止代价高昂的错误的转换习惯。\"],\"ovOn83\":[\"A brewery making 50 hL per batch produces 5,000 L—about 88 half-hectolitre kegs depending on keg size. A 2 hL fermenter is a 200 L vessel.\"],\"ozAMmJ\":[\"靶恩\"],\"p-HG8s\":[\"在平方米和平方英尺之间转换房间面积，以正确的方式添加浪费系数，并避免经典的长度×宽度单位混淆。\"],\"p0HoY9\":[\"A 8.5-foot counter run is 102 inches for a continuous laminate order. Someone 5.75 feet tall is 69 inches on a medical form that only accepts inches.\"],\"p1Dbpo\":[\"30 mph is about 13.4 m/s for a urban crash energy sketch. A 100 mph pitch (extreme) would be ~44.7 m/s—far above normal baseball, showing why unit checks matter.\"],\"p2DkbT\":[\"Treating acres and hectares as equal roughly doubles or halves land area in conversation. Survey acres (especially older deeds) can differ slightly from the international acre—confirm the jurisdiction. Do not convert acre-feet (volume of irrigation water) with an area converter.\"],\"p4X7mC\":[\"People often round 2.54 cm to “2.5 cm per inch,” which drifts by about 1.6% and shows up on long measurements. Another trap is mixing display inches (TV diagonals) with ruler inches without checking which system the seller used. Do not confuse centimetres with millimetres: 25.4 mm is one inch, not 25.4 cm.\"],\"p5SI6W\":[\"Many international economy limits sit at 23 kg (often marketed as 50 lb). That marketing round is slightly generous: 23 × 2.2046226218 ≈ 50.71 lb. If your home scale only shows pounds, do not pack to a flat 50 lb and assume you are safe—you may already be over. Convert the airline’s kilogram limit into pounds with a proper converter, then leave a buffer for scale disagreement between home and the check-in desk.\"],\"p9xoMn\":[\"Units Converters 由 <0>Voyager Tecnologias LTDA</0> 运营，总部位于巴西。我们很乐意听取您的意见。\"],\"pAQa1o\":[\"烤箱温度不是体积，但它们随着食谱的变化而变化\"],\"pDt01V\":[\"国际英寸定义如今已经标准化；日常身高换算可以将国际英寸视为精确值。尽管如此，还是要给单位贴上标签，这样软件进口商就不会猜测。\"],\"pFzToT\":[\"当报价在“单位说明”之后跳转时，询问以 m² 和 ft² 为单位的面积。透明的双重总计可以捕获无声的转换错误。\"],\"pGgN6u\":[\"Incline changes effort at the same belt speed. Converting km/h to mph does not adjust for grade. Keep incline notes beside speed/pace notes.\"],\"pH23TV\":[\"Multiplying by 2.5 instead of 2.54 understates every length. Surveyors and woodworkers also confuse decimal inches (3.25 in) with fractional inches (3¼ in) before converting—convert the decimal first. Screen “inches” are diagonal; do not treat them as width when comparing to a centimetre shelf opening.\"],\"pI6CGe\":[\"A 2,500 m² community garden is 0.25 ha. A 40,000 m² warehouse yard is 4 ha—handy for logistics land-use filings.\"],\"pInhXT\":[\"Runners quote pace as time per distance—minutes per kilometre or minutes per mile. Treadmills usually show speed in km/h or mph. They describe the same motion differently: pace = time / distance; speed = distance / time. Converting requires reciprocals, not a single multiply of the displayed number.\"],\"pLB71t\":[\"将高度视为长度转换问题，具有明确的目标格式。确定目的地是否需要单个公制值（厘米或米）或双惯用值对（英尺 + 英寸）。转换一次，然后格式化以供显示。\"],\"pYNZJY\":[\"毫米\"],\"pa79C2\":[\"链接转换而不丢失情节\"],\"paJWEM\":[\"Cookie 和类似技术\"],\"paWTJa\":[\"Using the statute-mile factor 1.609 instead of 1.852 understates maritime speed. Airspeed indicated in knots is not ground speed—wind correction is separate. Do not treat knot as a land mph synonym.\"],\"pa__Bp\":[\"一平方微米 (μm²) 等于 10^2 平方米。显微镜和微加工经常报告该单元中的区域。\"],\"pe2SHa\":[\"在常见的科学和工程用法中，是的：微米是微米 (10⁻⁶ m) 的非正式语言。在正式写作中更喜欢使用微米。\"],\"pe9kiJ\":[\"浏览所有\",[\"tQuantity\"],\"单位\"],\"peYsNy\":[\"废物因素和包装\"],\"pgqDUB\":[\"For privacy requests, conversion feedback, or partnership inquiries, email is the fastest channel. Include the page URL and locale if you are reporting a content issue.\"],\"phsQ55\":[\"未找到您要查找的页面，建议您返回首页。\"],\"pkDS7o\":[\"空气炸锅和烤箱具有不同的热质量。将他们的图表视为单独的；当食谱只列出一种比例时，仍然要小心地转换单位。\"],\"plPmpw\":[\"Treating 1.5 hours as 1 hour 50 minutes (decimal 0.5 ≠ 50). Flight “hours” in block time still convert with 60; time-zone offsets are a separate problem. Do not mix sexagesimal HMS strings without parsing each field.\"],\"pq--_D\":[\"Climb and descent rates use feet per minute—a vertical speed unit, not a horizontal airspeed unit. Do not convert fpm with knot converters.\"],\"ps03Ku\":[\"Tip: 1.30 hours is not 1 hour 30 minutes. Convert mixed h:mm:ss through total seconds, then format once. Julian years (365.25 days) are not calendar birthday years.\"],\"ps35j8\":[\"首先转换打印的温度，然后应用烤箱建议的风扇减少量。转换和风扇调整是单独的步骤。\"],\"ps9xJC\":[\"Practical rule of thumb\"],\"psJP6O\":[\"一公制汤匙等于 15 毫升。烹饪说明将其用于介质液体和调味品的测量。\"],\"puCv9T\":[\"90 km/h traffic is 25 m/s—handy for estimating stopping-distance thought experiments. A 18 km/h bike speed is 5 m/s.\"],\"q0xzNh\":[\"A 180 lb adult is about 81.6 kg on a metric chart. A 40 lb bag of dog food is roughly 18.1 kg for shelves labeled only in kilograms.\"],\"q1FqwM\":[\"轻旅行单位和天文单位位于日常前缀之外，但仍转换为米。前缀流畅度可帮助您合理检查以公里为单位的结果是否意外地以米为单位。\"],\"q4hj75\":[\"Is ground speed the same as airspeed?\"],\"q4rV31\":[\"Software libraries sometimes offer Julian century (36,525 days) for older astronomical formulas. That is 100 Julian years. Convert through days if your tool only exposes years and days.\"],\"q5GJGY\":[\"免费转换器免责声明\"],\"q5OjzF\":[\"将公里/小时与英里/小时混淆是一个安全问题，而不仅仅是一个数学问题。转换距离时，还要检查速度限制是否已转换。\"],\"q7xpqy\":[\"文化和基础设施惯性。一些国家的天气服务、恒温器和公众期望仍然以华氏度为基础。科学和大多数国家使用摄氏度或开尔文。\"],\"qAprmL\":[\"SI 前缀附加到单位名称上以乘以或除以 10 的幂。一公里是10立方米；一毫米等于 10⁻³ 米；一纳米等于 10⁻⁹ 米。学习前缀表后就可以解锁长度、质量和许多派生单位。\"],\"qIwLar\":[\"一米 (Ym) 等于 10²⁴ 米。它是最大的命名 SI 长度倍数之一。\"],\"qJb6G2\":[\"再试一次\"],\"qOTu7A\":[\"Knots Explained for Boats and Planes\"],\"qOfG9B\":[\"花园土壤、油漆和混凝土按体积或覆盖面积出售。将平方米的墙壁与升的油漆混淆，或将英亩的田地与立方米的覆盖物混淆，是面积与体积的错误，而不是公制与英制的错误。在转换单位之前，请先明确数量类型。\"],\"q_108C\":[\"A 500 mg pain tablet is 0.5 g of drug substance labeled strength. Caffeine at 80 mg in espresso is 0.08 g—useful when a lab protocol wants grams.\"],\"qgGxSI\":[\"英亩可以直接换算成平方公里吗？\"],\"qh4Woa\":[\"Convert cups to millilitres when baking and cooking across US/metric recipes. Cup sizes vary by country; this tool’s Cup unit maps to its configured cup definition—check which cup your recipe assumes (US legal cup is 240 mL; many metric recipes use 250 mL).\"],\"qm_29X\":[\"A 3-day courier promise is 72 hours if counted continuously. A 10-day medication course is 240 hours of coverage at face value.\"],\"qmv6Mo\":[\"Fuel economy answers “how much fuel per distance” (L/100 km) or “how much distance per fuel” (mpg). Those are inverse styles: lower L/100 km is better; higher mpg is better. You cannot convert them by treating the number like a simple length.\"],\"qrq8Wr\":[\"一公顷有多少平方米？\"],\"qsYV2G\":[\"电缆长度（国际）\"],\"qt41aL\":[\"这场历史竞争解释了为什么转换器仍然列出大多数人日常从未使用过的尺度：它们是科学文献记录的一部分，偶尔出现在较旧的文本中。当您知道档案中的陌生比例通常只是到开尔文的另一个仿射映射时，您就不会那么害怕了。\"],\"qwFZi1\":[\"Convert grams to avoirdupois ounces for coffee beans, mailers, and recipe scaling when kitchen scales show grams but US packaging lists ounces. One ounce is exactly 28.349523125 g. Portion control and postage brackets use this scale.\"],\"qzgYgD\":[\"最近的恒星例子（比邻星大约 4.25 光年）为米和公里转换练习提供了很好的解决问题。要求学生使用科学记数法计算相同的距离（以 AU 为单位）和以米为单位（以米为单位），然后解释为什么这两个答案都描述了一个物理距离。\"],\"r-bKrE\":[\"名称相同，卷数不同\"],\"r38boF\":[\"Convert British stone and pounds to kilograms and pounds, read UK body-weight phrases correctly, and avoid decimal-stone mistakes on forms.\"],\"r52K3T\":[\"Multiplying by 2 and adding 30 is a rough estimate only—off by several degrees for candy and meat temps. Forgetting the +32 offset after scaling is the most common algebra slip. Do not treat a 10 °C change as a 10 °F change; the degree sizes differ.\"],\"r8tcPz\":[\"品脱遵循加仑数：在两个系统中，八品脱对应一加仑，因此品脱的比例相同。旅行时点一品脱啤酒可以比教科书更快地教授计量知识。无论厨师是否注意到，酒吧玻璃器皿法规和标签法都对这些差异进行了编码。\"],\"rAEfTa\":[\"Affiliate disclosure: see our <0>Disclaimer</0>.\"],\"rBSwgf\":[\"如果罐头配方来自另一个国家，请仔细转换体积，并更喜欢在罐子系统中测试的更新配方——食品安全不仅仅取决于单位数学。\"],\"rBqDvA\":[\"Measure twice. Wall-to-wall carpet needs the clear floor span, not the exterior building footprint. Baseboards and undercut doors affect fitting but not the geometric area you start from.\"],\"rC2nQD\":[\"Converting only the whole feet and dropping leftover inches loses several centimetres. “Five foot two” must include the two inches (157.5 cm total), not 5 × 30.48 alone. Flooring sold per square foot still needs linear cm for cut lengths—do not mix area and length units.\"],\"rE-5lQ\":[\"服装和身体尺寸在国际上通常使用厘米，在美国通常使用英寸。图案起草可以将两者结合起来；仔细转换缝份，以便轻松计算保持一致。\"],\"rFVEj-\":[\"Convert metric tonnes to avoirdupois pounds for freight, scrap metal, and agricultural loads when SI shipping weight must meet US scale tickets. One tonne is 1,000 kg ≈ 2,204.62 lb. Logistics brokers quote both constantly.\"],\"rG5Q9u\":[\"Liquid nitrogen’s boiling point near 77 K is about −196 °C. A sensor rated to 233 K survives down to −40 °C, a common automotive electronics floor.\"],\"rIwk73\":[\"Common highway anchors\"],\"rMpfsQ\":[\"开尔文将绝对零锚定在 0 K。水的三相点和其他定义的固定点将开尔文与实验室实践联系起来。科学家们更喜欢用开尔文来表示状态方程、低温学和色温，因为比率和绝对值表现得很干净。\"],\"rMtVac\":[\"US recipes may list 8 oz of chocolate or 1 lb of butter. Remember 16 oz = 1 lb. Convert pounds to grams via ounces or use a kilogram ↔ pound converter for large amounts: 1 lb ≈ 453.592 g.\"],\"rRKjY3\":[\"Exactly 3,600 seconds: 60 seconds per minute times 60 minutes per hour.\"],\"r_FQ7i\":[\"Is a knot the same as a mph?\"],\"r_p7hp\":[\"A 2×4 stud is nominally 1.5 inches thick, which is 3.81 cm—useful when a metric drywall screw pack lists max material thickness in centimetres. A 55-inch TV diagonal is 139.7 cm for checking elevator and doorway clearance.\"],\"rbD1fJ\":[\"Measure outer L, W, H in one unit. Weigh on a trusted scale. Convert weight into the carrier’s billing unit. Compute dimensional weight with the correct divisor. Take the maximum. Add any oversize fees that ignore weight entirely.\"],\"rcBXzk\":[\"Units Converters |精密转换工具\"],\"rf4up8\":[\"标签、符号和 UI 陷阱\"],\"rjRk1f\":[\"Elapsed duration is not a clock time\"],\"rlJbvb\":[\"光秒\"],\"rm9u3o\":[\"一英亩英尺是指覆盖一英亩、深度一英尺的体积，约 1,233 立方米。水资源管理将其用于水库。\"],\"roUnmF\":[\"Incline, effort, and why units still matter\"],\"rrEWCV\":[\"70 mph on an interstate is about 113 km/h. A 6 mph walking pace is roughly 9.7 km/h for metric fitness watches.\"],\"rtSw51\":[\"英制体积：美国与英国测量值\"],\"ruvZmH\":[\"Convert miles per hour and kilometres per hour for foreign road signs, rental cars, and trip planning—plus the distance and time links that keep ETA math honest.\"],\"rxHnrf\":[\"将 \",[\"fromLabel\"],\" 转换为 \",[\"toLabel\"]],\"ryPNqA\":[\"平方公里适合地区和公园；公顷适合农场和森林；英亩适合美国地块；平方米适合建筑占地面积和小地块。选择使数字可读以供当前决策使用的单位，然后进行转换以进行比较，而不是相反。\"],\"rzZZTA\":[\"Those printed times are local. Zones and date changes hide the true duration. Use the airline’s block time or convert both instants to UTC before subtracting.\"],\"rzcesg\":[\"Adaptive cruise control and speed-limit assist features depend on map data units. If the car was configured for another market, verify the shown limit against roadside signs once, especially after firmware or language changes.\"],\"s-lIOg\":[\"确切因素和有效数字\"],\"s4NIvn\":[\"Use our knot ↔ km/h and knot ↔ mph pages for exact tables, and the nautical mile ↔ kilometre page when converting chart distances for mixed crews.\"],\"s73T7S\":[\"在软件和电子表格中，将列命名为 us_cup_mL 或 Imperial_pint_mL，而不是 cup 或 pint。不明确的列标题是等待发生的数据错误。\"],\"sAPueQ\":[\"分米\"],\"sBVCFu\":[\"许多计算器使用二进制浮点数。我们的转换器使用任意精度的小数，因此长转换链保持稳定。\"],\"sBywU8\":[\"对于普通通信，首选将值保持在 0.1 到 999 之间的单位。优选 12.5 km 而非 12 500 m 的道路距离；对于房间长度，首选 12.5 m 而不是 0.0125 km。可读的幅度是错误预防的一部分。\"],\"sDgNP3\":[\"对于温差，偏移会取消。升高 10 °C 意味着升高 10 K 和升高 18 °F。人们经常混淆转换读数和转换变化——室温 20 °C 是 68 °F，但升高 20 °C 是 36 °F，而不是 68 °F。\"],\"sFhneI\":[\"常见转换\"],\"sO4Syn\":[\"How many pounds are in a stone?\"],\"sOZcYX\":[\"ångström (Å) 等于 10⁻10 米，或 0.1 纳米。它广泛用于光谱学和晶体学中来表达原子尺度的长度。\"],\"sSrFJe\":[\"秒差距 (pc) 大约等于 3.26 光年。天文学家更喜欢它，因为它与恒星视差测量直接相关。\"],\"sThfcP\":[\"Exact kitchen factor: grams = ounces × 28.349523125. Ounces = grams ÷ 28.349523125. For mental checks, 30 g ≈ 1 oz is rough; 28 g ≈ 1 oz is better.\"],\"sW71Vp\":[\"符号μ（mu）表示微（10-6）。当用作前缀时，符号 m 表示毫 (10^3)​​。它们相差一千倍。\"],\"s_fkOd\":[\"早期的测温仪显示空气或液体受热膨胀，但缺乏共享的数字刻度。如果城市之间没有达成一致的固定点，阅读就无法通过信件或科学论文进行传播。再现性（而非便利性）推动仪器制造商走向共享参考点。\"],\"s_fxqz\":[\"70 kg is about 11 stone 0 lb (11.02 st). A fighter listed at 12 stone is 76.2 kg—useful when comparing to metric weight classes.\"],\"sev0AD\":[\"Time duration units run from seconds and minutes to hours, days, weeks, and Julian years. Use them for elapsed spans—not time-zone clock labels—and avoid decimal-hour mix-ups with hours-and-minutes notation.\"],\"sfgH-a\":[\"一国际海里正好等于 1,852 米。航空和海上导航使用它是因为它与地球纬度密切相关。\"],\"sj_xiq\":[\"Airline baggage is kilograms or pounds—not stone. Never put stone on a shipping label.\"],\"sjd0YY\":[\"Adding 273.15 directly to Fahrenheit skips the scale change and produces nonsense. Rankine (°R) is the Fahrenheit-sized absolute scale; do not label Rankine values as Kelvin. Oven setpoints in °F are not absolute temperatures for gas-law homework.\"],\"skqyeX\":[\"Integer weeks that discard remainder days hide partial weeks (10 days ≠ 1 week). ISO week numbers are a calendar system, not a pure duration conversion. Inclusive counting (“Monday to Friday”) can add an extra day if mishandled.\"],\"sltboY\":[\"A 4,400 lb machine is about 2.00 t for a metric bill of lading. A 500 lb crate is roughly 0.227 t (227 kg)—often better written in kilograms on the same form.\"],\"smJqvk\":[\"Imported goods may show only metric net weight. US cooks can convert g → oz for intuition, but baking is usually easier if you stay in grams once you own a metric scale.\"],\"snhup9\":[\"For passage planning: distance in nautical miles ÷ speed in knots = hours. That simple formula is why the unit exists. Change either unit without the other and the formula collapses.\"],\"sqjdpH\":[\"mph, km/h, and metres per second\"],\"sr0UJD\":[\"返回\"],\"sseGJ5\":[\"项目中期的混合系统是常见的错误来源。在清晰的边界处转换一次，在每个数字上标记单位，并尽可能将其余工作流程保留在单个系统中。\"],\"t-na-z\":[\"在计算的每一行写上单位。前缀错误隐藏在裸露的数字中。当前缀被视为单位标记的一部分时，维度分析仍然有效。\"],\"t1XjtI\":[\"您需要三个长度测量（或等效的几何形状）来获得体积，然后将该体积转换为化学图表的单位。\"],\"t8dlih\":[\"Trip time is distance divided by average speed—only when both use consistent length units. Mixing a 120 km leg with a 60 mph average without converting yields nonsense. Convert either all distances to miles and speeds to mph, or all to kilometres and km/h.\"],\"tC-cop\":[\"Foot per second appears in some US engineering contexts. For road trips you rarely need it; stick to mph and km/h unless a technical report forces the issue.\"],\"tCSlOi\":[\"Convert hours to minutes for parking tickets, roasting schedules, and billing increments when the quote is in hours but the clock works in minutes. Multiply hours by 60. Salons, ovens, and consultants use this constantly.\"],\"tG0Mm1\":[\"一微升 (µL) 等于百万分之一升。生物学和化学中的移液器通常分配微升体积。\"],\"tGMZ40\":[\"Can a day have other than 24 hours?\"],\"tMpml2\":[\"为什么我的计算器可能略有不同？\"],\"tPrmjP\":[\"Address:\"],\"tT9-B4\":[\"液体油、水、牛奶和汤料可以按体积干净地转换，因为它们可以填满杯子而不会产生空隙。干粉则不然。这就是面包烘焙师靠重量生存的原因。\"],\"tXV7b7\":[\"体积常常被低估，或者加仑被视为升。重新计算体积，仔细转换单位，并重新测试水。\"],\"tYuwiV\":[\"Convert metres to yards for American football field talk, fabric bolts, and gardening beds when the plan is metric but the store sells by the yard. Landscapers and sports fans cross this pair often. One metre is about 1.09361 international yards.\"],\"ta6_8E\":[\"旅行距离：公里和英里\"],\"tgGVmf\":[\"No warranty\"],\"tgMdom\":[\"Volumetric litres and cubic metres help warehouse planning (1 m³ = 1,000 L) but do not replace the carrier’s dimensional-weight formula. Use volume converters for storage and cube utilization; use the tariff formula for billing weight.\"],\"thkrj0\":[\"不规则房间：分成矩形，计算每个面积，然后求和。将总和转换一次。每个矩形的零散圆角可能会让你很短。\"],\"tmtrBa\":[\"Does the US use stone for body weight?\"],\"tnBPYh\":[\"用户反馈和行为\"],\"tnIuqS\":[\"在为公众写作时，请将光年与米或公里的科学记数法值配对一次，以便读者可以交叉检查星等。\"],\"trBkWx\":[\"有关这些服务条款的问题可发送至 <0>Voyager Tecnologias LTDA</0>，地址为 <1>voyagertecnologias@gmail.com</1>。\"],\"ttaqO2\":[\"为什么科学需要微小的长度单位\"],\"tthY0q\":[\"在缩放之前以原始产量测试关键配方。转换误差和缩放误差在塌陷的蛋糕中看起来是一样的——受控测试将它们分开。保留烘焙研发的换算日志：原始单位、假设的杯子标准、毫升值以及面粉和糖的称重确认。\"],\"tweYUH\":[\"Time Zones vs Duration Units\"],\"ty85rR\":[\"在上面的转换器中输入一个值。我们通过\",[\"tQuantity\"],\"基本单位与Decimal.js算术转换，然后将结果显示在\",[\"tTo\"],\"中。作为参考，1 \",[\"0\"],\" = \",[\"oneToOne\"],\" \",[\"1\"],\"。\"],\"tzmAt_\":[\"开尔文出现在物理、化学、天文学和照明领域。接近 2.7 K 的深空背景、接近 77 K 的液氮以及数千开尔文的炼钢温度在没有负值的情况下更容易推理。\"],\"u0I2ka\":[\"From m/s and race mathematics\"],\"u47PU6\":[\"Convert Kelvin to Fahrenheit for US engineering reviews when research papers quote absolute temperature but shop-floor instruments read °F. Aerospace and HVAC commissioning sometimes need this bridge. Use °F = K × 9/5 − 459.67.\"],\"uCFNKs\":[\"Everyday liquids often quote g/mL or kg/L. Water is about 1 g/mL near room temperature—handy, not magical. Oils and syrups differ; always use the density for the material and temperature you care about.\"],\"uCPKzy\":[\"对于统计过程控制，在数据库中保留一种内部单位系统并仅在表示边界处进行转换。反复转换存储的历史记录会降低数据质量并使跨工厂的能力研究变得复杂。\"],\"uD7uRR\":[\"只有在按照配方制定的情况下，少量的泡打粉、酵母和盐通常按勺量使用更安全，或者在严格烘焙时按 0.1 克刻度使用克数。微小的绝对误差是一茶匙内的大相对误差。\"],\"uLuey4\":[\"光年\"],\"uMnipN\":[\"仪器和分辨率\"],\"uOlg5g\":[\"我们收集的信息\"],\"uR6kEy\":[\"如果问题陈述混合了覆盖范围、深度和容量，请画一个小图表。一旦几何图形可见，许多作业和现场错误就会消失。\"],\"uUs1L4\":[\"Use millimetres to inches for precision hardware: bolt diameters, PCB hole spacing, camera sensor sizes, and machining tolerances. Engineering drawings in ISO countries list mm; US tooling and drill charts are often in inches. At this scale, the exact 25.4 mm per inch factor matters more than casual rounding.\"],\"u_xCOm\":[\"我应该转换我看到的每个测量值吗？\"],\"ubpaES\":[\"摄氏度到开尔文：K = °C + 273.15。开尔文到摄氏度：°C = K − 273.15。华氏度到开尔文的两步转换是最安全的：华氏度 → 摄氏度 → 开尔文，除非您仔细应用组合公式。\"],\"ueo-Bi\":[\"身高看起来很简单，直到表格要求填写英尺和英寸，而护照上列出的是厘米。人们很早就四舍五入，忘记了剩余的英寸，或者将小数英尺值粘贴到英寸字段中。这些错误会出现在服装订单、医疗图表和运动资格检查中。\"],\"ufpUZ8\":[\"正确的单位是您的受众已经使用的单位，以及您的监管机构、期刊或客户合同所要求的单位。工作现场没有人可以读取的完美 SI 选择仍然会导致错误。对于人类来说清晰性和对于审计员来说合规性都算作正确性。\"],\"uktD0z\":[\"Convert cubic metres to litres for bottled-water equivalents, fish stocking guides, and pump capacity when the engineering drawing uses m³. Multiply m³ by 1,000. Municipal water reports often flip between these for public communication.\"],\"ulGYbo\":[\"在法律允许的最大范围内，Voyager Tecnologias LTDA 及其运营商不对因您使用（或无法使用）Units Converters（包括依赖任何转换结果）而导致的任何间接、偶然、特殊、后果性或惩罚性损害，或任何数据、利润或业务损失承担责任。\"],\"upcWll\":[\"从纳米到米：了解尺度\"],\"upoTTm\":[\"阿托米特\"],\"urDKtY\":[\"科学转换的最佳实践\"],\"urQMcz\":[\"Convert km/h to knots when metric weather apps must match nautical instruments, sailing polars, or aviation METAR-style expectations. Divide km/h by 1.852. Harbor masters and student pilots do this when switching unit systems.\"],\"usyz3l\":[\"一光年有多少公里？\"],\"ut90L2\":[\"一英寸有多少毫米？\"],\"utb5FI\":[\"Should I convert days using 24 hours?\"],\"uugzJT\":[\"化学和晶体学中的 ångström\"],\"uvlVzR\":[\"Worked patterns\"],\"uyJsf6\":[\"关于\"],\"uz_-15\":[\"此处，公制杯的标准化容量为 250 毫升。烹饪食谱使用杯子来盛装日常液体和干燥物品。\"],\"v1Qdq2\":[\"如果您接受 cookie，我们可能会使用 PostHog 来了解人们如何使用 Units Converters（例如，哪些页面受欢迎）。当您拒绝 cookie 时，分析功能将被禁用。\"],\"v7Ohh6\":[\"Convert feet to inches when cut lists, sewing patterns, or height forms ask for a single inch total instead of feet-and-inches. Cabinetry screws, pipe runs, and printer paper clearance checks often need one number. Multiply feet by 12.\"],\"v7dGUo\":[\"茶匙（公制）\"],\"vCZf8l\":[\"Kilogram\"],\"vFTcJf\":[\"契约列出的英亩数可能精确到小数点后两位，而底层的边界几何形状则更精确或更精确。转换不能增加调查从未测量过的准确性。\"],\"vG79Hs\":[\"Plans written in min/km need min/mile for US races (or the reverse). Convert distance first (1 mile = 1.609344 km), then scale the pace time: min/mile ≈ min/km × 1.609344. Example: 5:00 /km ≈ 8:03 /mile.\"],\"vIvqTY\":[\"分区文档有时会在部分之间切换单位。为项目创建一页单位键，并将每个引用的数字转换为单个工作单位。\"],\"vK3Q2x\":[\"一厘升 (cL) 等于 10 毫升。欧洲的饮料包装通常以厘升为单位标注体积。\"],\"vKE6JE\":[\"指定为 10.00 ± 0.02 mm 的轴与在电话转换后四舍五入到小数点后三位后随意写入 0.394 不同。软转换可以在机器启动之前吃掉公差预算。废料箱里装满了随意改装的零件，而不是加工不良的零件。\"],\"vLc8Kh\":[\"Dividing by 1,000 gives cubic metres, not hectolitres (though 1 m³ = 10 hL). Small-batch homebrew in litres rarely needs hL—avoid forcing tiny numbers like 0.02 hL unless the form requires it. Keep temperature correction for beer volume separate from unit conversion.\"],\"vLwhXs\":[\"When scientists choose Julian years\"],\"vODdcK\":[\"一光秒是光在真空中一秒钟传播的距离，正好是 299,792,458 米。它有助于表达近地空间距离。\"],\"vOpNzS\":[\"Understand the knot as a speed unit tied to the nautical mile, convert knots to km/h and mph, and avoid mixing statute miles with nautical miles in navigation.\"],\"vPUFsW\":[\"在软件中，精确因子应尽可能存储为精确小数或有理数。 0.001 或 25.4 的二进制浮点近似值可能会产生微小的残差，当您来回转换时，这些残差看起来就像错误。\"],\"vQEfYA\":[\"Multiply metres per second by 3.6 to get kilometres per hour. Divide km/h by 3.6 to get m/s.\"],\"vTmcmH\":[\"牛顿\"],\"vUGw3w\":[\"A day equals 86,400 seconds (24 hours). Calendars and daily planning treat the mean solar day as the basic civil time unit.\"],\"vUy5Bv\":[\"公差无法在不小心的转换中幸存\"],\"vYtgK3\":[\"一立方米有多少升？\"],\"vZhDqN\":[\"玻尔\"],\"veYKqf\":[\"确定权威单位。谨慎选择硬转换或软转换。使用精确的因素。转换拟合极限。绕一圈。记录政策。通过进行/不进行的心理评估进行验证。\"],\"vln3eu\":[\"国际英里正好等于 1,609.344 米。它仍然是美国和英国的主要长途公路单位。\"],\"vn2owh\":[\"Unit conversion does not change stopping distance physics, but mixed mental models do. If you are used to thinking “60 mph needs X metres to stop,” rebuild that intuition in km/h before mountain descents abroad.\"],\"vvA23-\":[\"面粉、可可、磨碎的奶酪和切碎的坚果因包装的不同而有很大差异。权重可以消除这种差异。如果食谱仅列出杯子，请寻找该成分的可靠重量换算，并注意面粉是用勺子还是舀的。\"],\"vvWnbl\":[\"The light-year as a length unit is defined using the Julian year: distance light travels in vacuum in one Julian year. That is why astronomy documentation is careful about which year it means.\"],\"vvfhCy\":[\"一平方公里 (km²) 等于一百万平方米。地图和地理将其用于城市、地区和国家。\"],\"w4Xr1y\":[\"Right-sizing the carton often saves more money than negotiating a tiny rate discount. Empty space increases dimensional weight. Lightweight void fill can still lose if the box stays huge. Dense goods in a snug carton usually bill near actual weight.\"],\"w6E5Q_\":[\"对长度、体积和面积的公制和英制单位进行实用比较——每种系统何时获胜以及如何自信地在它们之间进行转换。\"],\"w6xq3D\":[\"90 minutes of parking is 1.5 hours on a meter that bills hourly. A 105-minute feature film is 1.75 hours.\"],\"w8aQU6\":[\"主要在美国使用的温标。\"],\"w9dmsB\":[\"英制长度使用英寸、英尺、码和英里，具有固定但非小数的比率：12 英寸等于英尺，3 英尺等于一码，1760 码等于一英里。国际定义现在将英寸固定为 25.4 毫米，因此一旦您使用国际英尺和英里（而不是旧的测量定义），则转换为米是准确的。\"],\"wB0ke9\":[\"Units Converters作为便利工具免费提供。转换结果仅用于一般信息和教育目的。它们<0>不是</0>旨在用于危及生命、医疗、安全、法律、财务或其他高风险决策。始终使用适当的专业标准或校准仪器验证关键测量结果。\"],\"wLoW7s\":[\"有关隐私的问题吗？发送电子邮件至<0>voyagertecnologias@gmail.com</0>或访问我们的<1>联系</1>页面。另请参阅我们的<2>服务条款</2>。\"],\"wM9pzC\":[\"平方英尺到平方米和立方英尺到立方米是常见的电子表格错误。有人将 0.3048 存储为名为 FT_TO_M 的常量，并将面积乘以它一次。正确的面积系数是 0.3048²。\"],\"wMgXFc\":[\"1 m² ≈ 10.7639 ft². 1 ft² ≈ 0.092903 m². Those factors are squares of the metre–foot length relationship. That is why a “10% longer room” is not a “10% larger carpet order” when you also change width.\"],\"wNAEQM\":[\"拉姆达 (λ) 是实验室体积单位，等于一微升 (10⁻⁶ L)。较早的生物化学文献仍然使用该名称。\"],\"wNXXnX\":[\"强调该单位回答的是多远，而不是持续多长时间。打个比方：三个小时的车程通过旅行约定描述了一段距离；这并不意味着目的地已经过去了三个小时。\"],\"wSn4cc\":[\"Method A: convert stone to pounds (× 14), add leftover pounds, convert total pounds to kilograms. Method B: convert stone to kilograms (× 6.35029318) and convert leftover pounds to kilograms (× 0.45359237), then add. Both match if you use exact factors.\"],\"wULskt\":[\"Convert avoirdupois pounds to metric tonnes for export documents, port tariffs, and metric axle-load rules when the weighbridge ticket is in pounds. Divide lb by about 2,204.62. Containerized cargo filings often need tonnes.\"],\"wV4T5U\":[\"A 2.25-hour seminar is 135 minutes. Slow-cooking for 8 hours is 480 minutes on a device that only accepts minutes.\"],\"wW5k8c\":[\"为什么我的 ft² 到 m² 转换看起来太小？\"],\"wZ0a6O\":[\"标准度之前\"],\"w_tlhZ\":[\"Identify the airspeed type (IAS/TAS/GS) and the unit. Convert the unit only. Keep type labels attached (“TAS 140 kt ≈ 259 km/h”).\"],\"wgavnZ\":[\"Example: 500 g of material at 0.8 g/mL → volume = 500 / 0.8 = 625 mL. Convert to litres (0.625 L) if the tank chart uses litres.\"],\"wgbExZ\":[\"在前缀之间移动就是移动小数点。 3.5 km = 3 500 m = 3 500 000 mm。通过明确写出幂：3.5 × 10³ m，避免将思维转变与计算器拼写错误混为一谈。\"],\"whKQ_H\":[\"一英制加仑约为 4.546 L，而美制液体加仑约为 3.785 L，大约大 20%。务必检查人物使用的加仑数。\"],\"whSPb4\":[\"摄氏度和华氏度包含相对于绝对零的偏移量，因此映射的形式为 y = ax + b，而不是单独的 y = ax。开尔文是绝对标度，在比较绝对温度时会按比例因子进行转换。\"],\"wiFqA4\":[\"Volume for shipping math is usually the rectangular product L × W × H, not the true geometric volume of an irregular shape. Carriers bill the rectangular cuboid. Convert that cuboid into the unit the divisor expects (often cm³ or in³), then apply the formula.\"],\"wmk4lB\":[\"Precision in sport and lab timing\"],\"wzAFc1\":[\"Nanosecond\"],\"wzLsq4\":[\"相关单位包括光秒、光分、光时和光日——对于太阳系尺度和通信延迟讨论很有用。\"],\"wzqqS-\":[\"主要特点\"],\"x0uKJ1\":[\"Cooking syrups: converting a recipe from “grams of honey” to tablespoons requires density (or a tested volumetric equivalent). Guessing from water’s density over-pours honey.\"],\"x0y4It\":[\"在您同意的情况下展示相关广告\"],\"x8zdoX\":[\"阅读Units Converters的服务条款，包括使用免责声明、知识产权、第三方广告和责任限制。\"],\"x9_MIj\":[\"International carriers usually quote chargeable weight in kilograms. US domestic services often speak in pounds. Convert scale readings with the exact pound–kilogram relationship before comparing to dimensional weight. Comparing 10 lb to a dimensional weight of 5 kg without converting is meaningless.\"],\"xBU15m\":[\"立方厘米\"],\"xCd3hA\":[\"Dividing cm by 30 instead of 30.48 adds a small but visible error on height (about 0.5 cm at 180 cm). People also convert cm→inches then forget to divide by 12 for feet. Do not treat “foot” as the anatomical foot length; use the unit definition.\"],\"xJEke2\":[\"<0>体积：</0>升、立方英寸、加仑和毫升。\"],\"xKeMa0\":[\"为什么两个供应商在小数点后第四位上存在分歧？\"],\"xLoJAO\":[\"一毫升 (mL) 等于一立方厘米。医学、烹饪和实验室工作使用毫升来精确测量液体体积。\"],\"xM1_13\":[\"Separate clock labels (time zones, DST) from duration units (seconds, hours, days) so meeting math and layover math stop disagreeing.\"],\"xOeXJw\":[\"A knot is a nautical mile per hour\"],\"xQB4Q9\":[\"Charts and distances are often in nautical miles. Using knots keeps speed and distance in the same mile definition, so time = distance ÷ speed stays simple.\"],\"xRJBlt\":[\"Microsecond\"],\"xSy0fo\":[\"Halving the pound value (“close enough to kg”) is ~10% low. Baby weight in pounds and ounces needs ounces converted (16 oz = 1 lb) before switching to kg. Do not use troy or tower pounds here.\"],\"xUi_8z\":[\"国际电缆长度等于 185.2 米（十分之一海里）。海军历史上将其用于短途海上航行。\"],\"xXK4Es\":[\"未找到指南 | Units Converters\"],\"xfkVOo\":[\"Entering “11.6 stone” when someone meant 11 st 6 lb (11 stone + 6/14 ≈ 11.43 st) misstates mass. Livestock “stone” traditions vary historically—stick to the 14 lb stone for people. Do not mix stone with hundredweight without knowing long vs short hundredweight.\"],\"xgbMzR\":[\"Cubic metres give kg/m³. For liquids, kg/L is common and equals g/mL numerically for the same density value.\"],\"xicKBk\":[\"Should I convert to kilograms or pounds first?\"],\"xj4SWA\":[\"与任何帮助维护池的人共享数据卡。双装置可防止周末客人阅读外国标签时服用过量。\"],\"xjhtsV\":[\"链\"],\"xkuIjN\":[\"A microgram (µg) equals one billionth of a kilogram (10⁻⁹ kg). Trace nutrients, pollutants, and sensitive analytical chemistry use micrograms.\"],\"xlbRot\":[\"烤箱各不相同。架子位置、盘颜色和校准误差与单元标签一样重要。使用烤箱温度计。\"],\"xn4DRx\":[\"为什么美国的杯子、品脱和加仑与英国的英制单位不一致，以及如何在不破坏食谱或报告的情况下转换烹饪和液体体积。\"],\"xnqczb\":[\"这些指南解释了 \",[\"tQuantity\"],\" 转换（例如 \",[\"tFrom\"],\" 到 \",[\"tTo\"],\"）背后的系统、陷阱和日常用法。\"],\"xowcRf\":[\"服务条款\"],\"xrWUa0\":[\"做饭是非工程师最常碰到单位摩擦的地方。公制配方以克和毫升为单位称量面粉和液体；美国食谱依赖杯子和汤匙。对于干货来说，重量比体积更可靠，因为包装密度各不相同。当您必须转换体积时，请仔细对待杯和升的转换，并且在精度很重要时更喜欢称重。\"],\"xs9aZ3\":[\"为什么浮点转换器会失败（以及十进制数学如何修复它）\"],\"xt5Cku\":[\"以米为单位，一光年约为 9.46 × 10^5 米（约 9.46 拍米）。以公里为单位，约为 9.46 × 10^2 公里。巨大的尺寸正是天文学家喜欢这个单位的原因：银河距离保持可读。\"],\"xvTYZc\":[\"一平方英寸等于 645.16 平方毫米。美国习惯的技术图纸和包装通常以平方英寸指定面积。\"],\"xxuWj3\":[\"原子、分子、光的波长和晶格都远小于毫米。重复说 0.000 000 000 2 m 是不可读的。前缀 SI 单位和一些传统的科学单位使数字接近人类规模。\"],\"xyfCYb\":[\"硬转换使用精确的因子并在舍入允许的情况下尽可能保留原始意图。软转换在其他单位系统中选择一个方便的接近值，可能会调整公差，以实现本地工具的可制造性。\"],\"y3OKbU\":[\"When volume is still fine\"],\"y3Yg_9\":[\"负摄氏度读数是正常的；负开尔文值不用于普通热力学温度。历史上的怪事和流行科学的错误陈述有时会混淆这一点。如果转换从合理的摄氏输入路径产生负开尔文，则实现是错误的。\"],\"y89PWI\":[\"燃油经济性相邻混乱\"],\"yAR8KT\":[\"Fuel Economy Units Basics\"],\"yA_nzZ\":[\"如果您通过我们的表格或电子邮件提交反馈、建议或其他内容，即表示您授予我们非排他性、免版税的许可，以使用该材料来改进服务。您同意不会滥用本网站、试图破坏本网站、提交非法或滥用内容或干扰其他用户的访问。\"],\"yAkDHH\":[\"在车间，向机械师提供其工具展示单元中的图纸。强迫不断的心理转变比任何因素表辩论都更能增加废品。如果需要双尺寸，请在每次绘图更新时从一个权威的主要值导出辅助单位。\"],\"yCEJDM\":[\"实验室中的微米、纳米和皮克\"],\"yCVJEx\":[\"瓷砖、木板和地毯订单通常会因切割和错误而增加 5-15% 的浪费。在您信任测量的面积后应用废物百分比。转换单位并不能取代废物规划。\"],\"yGxnJc\":[\"包装通常以覆盖指定区域的盒子形式出售。将您的净面积（加上废物）转换为卖方的单位，然后除以每箱的覆盖范围。四舍五入为整箱。\"],\"yIbAkH\":[\"Weight (mass) covers kilograms, grams, pounds, ounces, stone, and related units for luggage, cooking, shipping, and body weight. Convert with exact factors and keep one home unit for logs and forms.\"],\"yKRod9\":[\"This guide focuses on unit conversion among knots, mph, km/h, and m/s. It does not replace performance charts or training on IAS/TAS relationships.\"],\"yLOiJ4\":[\"<0>终极精度：</0>由Decimal.js提供动力，实现零舍入误差。\"],\"yQ0Kng\":[\"使用可信转换器或 10 的精确幂作为 SI 前缀。保留对习惯单位和特殊天文长度的仔细因子查找。\"],\"yRaXxk\":[\"土地公制单位加上公顷 (10⁴ 平方米) 和 (10² 平方米)。即使它们不是米的前缀形式，也可以与 SI 一起使用。与平方公里或英亩混合时仍按平方米换算。\"],\"yVZCfd\":[\"Why is my flight longer than landing time minus takeoff time?\"],\"yVsPvQ\":[\"Using 60×60 incorrectly as 3,000 or 36,000 from zero slips. Decimal hours (0.5 h = 1,800 s) differ from HH:MM:SS parsing. Leap seconds rarely matter for app timeouts under a day.\"],\"yWuRC3\":[\"有些因素是由法律或国际协议定义的并且是准确的。国际英寸正好是25.4毫米。一升正好是 0.001 立方米。使用这些精确值可以避免引入错误的精度或系统偏差。\"],\"yYWE07\":[\"Reverse: kilograms to stone for conversation—divide kg by 6.35029318 to get decimal stone, then split into whole stone and remaining pounds carefully—or convert kg → lb first, then divide by 14 for stone and remainder.\"],\"yb3igQ\":[\"Subtracting 273 from a value already near room temperature can look “almost right” and hide a 0.15 K bias. Negative Kelvin is physically invalid—if you see it, the input was wrong. Do not apply the Fahrenheit offset formulas to Kelvin.\"],\"ybVMSR\":[\"1 Julian year = 365.25 days = 8,766 hours = 525,960 minutes = 31,557,600 seconds. Those relationships are exact under the definition used here. Converters that implement Year (Julian) should match these figures.\"],\"yc-YBj\":[\"厘的使用与毫和公斤一样广泛吗？\"],\"ycIpq-\":[\"人的头发大约有几十微米。可见光波长约为数百纳米。原子间距约为十分之一纳米 (ångströms)。道路距离以公里为单位；机械加工使用毫米；光学和半导体的尺寸为微米和纳米。\"],\"ydLT42\":[\"一公顷 (hm) 等于 100 米。它是气象学（降雨率）和一些运动距离中使用的国际单位制倍数。\"],\"ydN0n-\":[\"说出数量。确认尺寸（L、L²、L³、θ、...）。选择兼容的单位。对长度因子应用正确的幂。最后圆了。估计捕获 100 倍错误的大致程度。如果棒球场失败，请在订购材料之前停止。\"],\"ye30Jw\":[\"School zones and temporary limits are where unit mistakes hurt most because the absolute speeds are lower but enforcement and child safety margins are tight. Convert the posted number before you “nudge a little over.”\"],\"yjU6f5\":[\"为什么我的化学剂量看起来太强了？\"],\"ykrwS3\":[\"Divide 60 by the pace in minutes per kilometre. Example: 6:00 min/km → 60/6 = 10 km/h. Convert seconds into decimal minutes first (5:30 → 5.5).\"],\"yorl4E\":[\"Measure in whatever the scale displays. Convert to the audience’s unit with stone↔kg or lb↔kg tools. Write the compound UK form only for humans who expect it. Store metric in spreadsheets.\"],\"yotZlg\":[\"如何在表格、运动和健康记录中在厘米、米、英尺和英寸之间转换高度，而无需在句子中间混合系统。\"],\"yq9RVX\":[\"Tare the bowl, add the first ingredient to its target weight, tare again, add the next. Working entirely in grams reduces unit toggling. If the recipe is in ounces, either convert the whole recipe before starting or keep the scale in oz for that session—do not mix mid-bowl.\"],\"ywHWsW\":[\"实际检查：1 m3 = 1 000 L = 1 000 000 cm3。 1 平方米 = 10 000 平方厘米。如果转换后的面积或体积相差 100 或 1000 倍，则怀疑前缀上缺少正方形或立方体。\"],\"ywdLUh\":[\"Convert kilograms to avoirdupois pounds for body weight, luggage, and gym plates when scales or airlines mix SI and US customary units. Shipping rate cards and protein powder tubs cross this pair constantly. One kilogram is about 2.20462 lb.\"],\"ywlqvz\":[\"Use our square metre ↔ square foot converter for the area step and metre ↔ foot for checking individual wall lengths on mixed drawings.\"],\"yz_Uj6\":[\"为了将<0>\",[\"tFrom\"],\"</0>转换为<1>\",[\"tTo\"],\"</1>，我们的工具使用基本单位作为桥梁，通过任意精度的十进制算术确保最大精度。\"],\"z-7BXf\":[\"Carpet Area Calculator Workflow\"],\"z-8hWf\":[\"海里（国际）\"],\"z6K72t\":[\"Square metres ↔ square feet\"],\"z6_cZc\":[\"历史告诉转换器者什么\"],\"z7wFp8\":[\"A 10-yard fabric bolt section is 9.144 m—enough to plan metric pattern layouts. A first-down marker at 10 yards is 9.14 m on a metric practice field overlay.\"],\"zBLASl\":[\"拉姆达\"],\"zFY4fe\":[\"一米有多少纳米？\"],\"zI3I0m\":[\"No. 1.30 hours means 1 hour + 0.30 × 60 = 18 minutes. 1 hour 30 minutes is 1.5 hours. Do not read mm as a decimal fraction.\"],\"zIWRzB\":[\"One knot means one nautical mile per hour. The international nautical mile is exactly 1,852 metres, so 1 knot = 1.852 km/h exactly. In statute (land) miles, 1 knot ≈ 1.15078 mph. Mariners and aviators use knots so speed and chart distance share the same mile definition.\"],\"zItrmB\":[\"Using 273 instead of 273.15 is fine for rough work but wrong for precise calorimetry. Multiplying by 273.15 instead of adding is a frequent calculator error. Kelvin is never written with a degree symbol in modern SI (write 300 K, not 300 °K).\"],\"zJ-oU4\":[\"当我们观察远处的物体时，我们看到的是过去留下的光。对于附近的恒星来说，以年为单位的回顾时间在数值上接近以光年为单位的距离。在宇宙尺度上，宇宙膨胀效应使距离测量和回溯时间之间的关系更加微妙。\"],\"zMPCk2\":[\"Treadmill Pace: min/km and Speed Units\"],\"zNWlva\":[\"Body weight, gym plates, and health forms\"],\"zOY1MB\":[\"1 Julian year is 365.25 days. 4 Julian years are 1,461 days—the leap-day pattern baked into that average.\"],\"zVAIyg\":[\"Cookie 同意\"],\"zW9QNz\":[\"未找到单位\"],\"zY9UuN\":[\"圆密耳是直径为 0.001 英寸的圆的面积。电气工程用它来指定电线横截面积。\"],\"zYqng0\":[\"Green light near 550 nm is 5.5×10⁻⁷ m in wave equations. A 7 nm semiconductor node dimension is 7×10⁻⁹ m—useful when comparing to atomic radii quoted in metres.\"],\"zdrl26\":[\"建筑占地面积与地块大小\"],\"zk7B8P\":[\"Treating 1 oz as 25 g or 30 g shifts chocolate tempering and postage. “Net wt 16 oz” is one pound (453.6 g), not 16 × 30. Distinguish ounce-force if you came from an older engineering table.\"],\"zkqP5e\":[\"Identify which variable you know. Convert mass and volume into a consistent pair. Apply the triangle. Convert the answer into the display unit last.\"],\"zlfei8\":[\"Time units nest by sixty—and then by twenty-four\"],\"znRg18\":[\"Historical note: the name comes from counting knots in a line paid out over a sandglass interval. Modern instruments use sensors and GNSS; the unit definition is now fixed by the international nautical mile.\"],\"zntqjv\":[\"小数、有理数和定点替代方案\"],\"zsKJ2q\":[\"仪表\"],\"zx4BuL\":[\"Week\"],\"zx6yEA\":[\"Kilograms vs Pounds in Everyday Life\"],\"zxRKuk\":[\"Why convert speed when talking about fuel economy?\"],\"zygSd2\":[\"mph to km/h for Road Trips\"]}")as Messages;